package com.killclog;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import javax.swing.ImageIcon;
import net.runelite.client.plugins.hiscore.HiscorePanel;
import net.runelite.client.util.ImageUtil;

/**
 * Account badges for names. GIM badges come from the game's mod icons, which
 * the client thread loads at login; this never reads game state itself, since
 * it runs on the panel's thread.
 */
final class AccountBadgeResolver
{
	private AccountBadgeResolver()
	{
	}

	@Nullable
	static ImageIcon labelIcon(@Nullable AccountDisplay display)
	{
		BufferedImage badge = badge(display);
		if (badge == null)
		{
			return null;
		}
		AccountType type = display.accountType();
		return new ImageIcon(type != null && type.isGroupIronman() ? badge : resize(badge, 15));
	}

	@Nullable
	static BufferedImage badge(@Nullable AccountDisplay display)
	{
		if (display == null)
		{
			return null;
		}
		if (display.former() != null)
		{
			return formerBadge(display.former());
		}
		HiscoreTable table = display.hiscoreTable();
		if (table.isSpecial())
		{
			return staticBadge(table);
		}
		AccountType type = display.accountType();
		if (type == null)
		{
			return null;
		}
		return type.isGroupIronman() ? GimBadgeLoader.getGimBadge(type) : staticBadge(type);
	}

	@Nullable
	static String label(@Nullable AccountDisplay display)
	{
		return display != null ? display.label() : null;
	}

	@Nullable
	private static BufferedImage staticBadge(AccountType type)
	{
		String resource = ClogHelper.accountBadgeResource(type);
		return loadHiscoreResource(resource);
	}

	@Nullable
	private static BufferedImage staticBadge(HiscoreTable table)
	{
		return loadHiscoreResource(table.badgeResource());
	}

	/** RuneLite's own helm with the mark of the mode left drawn over it. */
	@Nullable
	private static BufferedImage formerBadge(AccountDisplay.Former former)
	{
		BufferedImage helm = loadHiscoreResource(former.helm);
		BufferedImage overlay = loadResource(AccountBadgeResolver.class, former.overlay);
		if (helm == null || overlay == null)
		{
			return helm;
		}
		BufferedImage badge = new BufferedImage(helm.getWidth(), helm.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = badge.createGraphics();
		g.drawImage(helm, 0, 0, null);
		g.drawImage(overlay, 0, 0, null);
		g.dispose();
		return badge;
	}

	@Nullable
	private static BufferedImage loadHiscoreResource(@Nullable String resource)
	{
		return loadResource(HiscorePanel.class, resource);
	}

	@Nullable
	private static BufferedImage loadResource(Class<?> owner, @Nullable String resource)
	{
		if (resource == null)
		{
			return null;
		}
		try
		{
			return ImageUtil.loadImageResource(owner, resource);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	private static BufferedImage resize(BufferedImage badge, int height)
	{
		int width = (int) Math.round((double) badge.getWidth() / badge.getHeight() * height);
		return ImageUtil.resizeImage(badge, width, height);
	}
}

package com.killclog;

import javax.annotation.Nullable;
import lombok.EqualsAndHashCode;

/**
 * Account identity as shown in the panel. AccountType remains the account mode;
 * HiscoreTable names the rank table when regular pures/skillers refine.
 */
@EqualsAndHashCode
final class AccountDisplay
{
	/** The mode an account left, worn on the frozen board it left behind. */
	enum Former
	{
		DEAD_HARDCORE("Dead Hardcore", "hardcore_ironman.png", "dead-hardcore-overlay.png"),
		DE_IRONED("De-ironed", "ironman.png", "de-ironed-overlay.png");

		final String label;
		final String helm;
		final String overlay;

		Former(String label, String helm, String overlay)
		{
			this.label = label;
			this.helm = helm;
			this.overlay = overlay;
		}
	}

	private final AccountType accountType;
	private final HiscoreTable hiscoreTable;
	@Nullable
	private final Former former;

	private AccountDisplay(@Nullable AccountType accountType, @Nullable HiscoreTable hiscoreTable,
		@Nullable Former former)
	{
		this.accountType = accountType;
		this.hiscoreTable = hiscoreTable != null ? hiscoreTable : HiscoreTable.STANDARD;
		this.former = former;
	}

	static AccountDisplay of(@Nullable AccountType accountType, @Nullable HiscoreTable hiscoreTable)
	{
		HiscoreTable table = accountType == AccountType.REGULAR
			? hiscoreTable : HiscoreTable.STANDARD;
		return new AccountDisplay(accountType, table, null);
	}

	/**
	 * This account as a board's row shows it. Only a recorded frozen row wears the mode left, and
	 * only when the lookup's own answers agree: a dead Hardcore is an Ironman now, a de-ironed
	 * account isn't. A board still loading, unanswered, or without this player, or a lookup whose
	 * regular or Ironman board didn't answer, keeps the account's own badge.
	 */
	AccountDisplay shownOn(@Nullable HiscoreResult view, @Nullable RankLeaderboard board)
	{
		Boolean ironmanNow = view != null ? view.getIronmanNow() : null;
		if (view == null || !view.isFrozen() || view.getTotalLevel() <= 0 || ironmanNow == null)
		{
			return this;
		}
		AccountDisplay shown = frozenOn(board);
		return shown.former == (ironmanNow ? Former.DEAD_HARDCORE : Former.DE_IRONED) ? shown : this;
	}

	/**
	 * This account on a board its stats are frozen on. A Hardcore who died is an Ironman frozen
	 * on the Hardcore board; an iron who became a main is frozen on the iron boards. Any other
	 * frozen board, like an Ultimate who stepped down, keeps the account's own badge.
	 */
	AccountDisplay frozenOn(@Nullable RankLeaderboard board)
	{
		Former left = board == RankLeaderboard.HARDCORE && accountType == AccountType.IRONMAN ? Former.DEAD_HARDCORE
			: accountType == AccountType.REGULAR && (board == RankLeaderboard.IRONMAN
			|| board == RankLeaderboard.HARDCORE || board == RankLeaderboard.ULTIMATE) ? Former.DE_IRONED : null;
		return left != null ? new AccountDisplay(accountType, hiscoreTable, left) : this;
	}

	@Nullable
	Former former()
	{
		return former;
	}

	@Nullable
	AccountType accountType()
	{
		return accountType;
	}

	HiscoreTable hiscoreTable()
	{
		return hiscoreTable;
	}

	@Nullable
	String label()
	{
		if (former != null)
		{
			return former.label;
		}
		if (hiscoreTable.isSpecial())
		{
			return hiscoreTable.displayName();
		}
		return accountType != null ? ClogHelper.accountLabel(accountType) : null;
	}
}

package com.killclog;

import java.util.Locale;
import javax.annotation.Nullable;

public enum AccountType
{
	REGULAR,
	IRONMAN,
	HARDCORE_IRONMAN,
	ULTIMATE_IRONMAN,
	GROUP_IRONMAN,
	HARDCORE_GROUP_IRONMAN,
	UNRANKED_GROUP_IRONMAN;

	boolean isGroupIronman()
	{
		return this == GROUP_IRONMAN
			|| this == HARDCORE_GROUP_IRONMAN
			|| this == UNRANKED_GROUP_IRONMAN;
	}

	@Nullable
	static AccountType displayType(@Nullable AccountType hiscoreType, @Nullable AccountType providerType)
	{
		// The first argument may already carry a higher-trust runtime or
		// first-party GIM subtype. Do not let a later provider cache replace it.
		if (hiscoreType != null && hiscoreType.isGroupIronman())
		{
			return hiscoreType;
		}
		if (providerType != null && (providerType.isGroupIronman() || hiscoreType == null))
		{
			return providerType;
		}
		return hiscoreType;
	}

	@Nullable
	static AccountType fromProviderId(int id)
	{
		switch (id)
		{
			case 0: return REGULAR;
			case 1: return IRONMAN;
			case 2: return HARDCORE_IRONMAN;
			case 3: return ULTIMATE_IRONMAN;
			case 4: return GROUP_IRONMAN;
			case 5: return HARDCORE_GROUP_IRONMAN;
			case 6: return UNRANKED_GROUP_IRONMAN;
			default: return null;
		}
	}

	@Nullable
	static AccountType fromRuneLiteVarbit(int value)
	{
		switch (value)
		{
			case 1: return IRONMAN;
			case 2: return ULTIMATE_IRONMAN;
			case 3: return HARDCORE_IRONMAN;
			case 4: return GROUP_IRONMAN;
			case 5: return HARDCORE_GROUP_IRONMAN;
			case 6: return UNRANKED_GROUP_IRONMAN;
			default: return REGULAR;
		}
	}

	@Nullable
	static AccountType fromProviderValue(@Nullable String value)
	{
		if (value == null)
		{
			return null;
		}
		switch (value.toLowerCase(Locale.ROOT).replace('-', '_').replace(' ', '_'))
		{
			case "regular":
			case "normal":
				return REGULAR;
			case "ironman":
				return IRONMAN;
			case "hardcore_ironman":
				return HARDCORE_IRONMAN;
			case "ultimate_ironman":
				return ULTIMATE_IRONMAN;
			case "group_ironman":
			case "gim":
				return GROUP_IRONMAN;
			case "hardcore_group_ironman":
			case "hcgim":
				return HARDCORE_GROUP_IRONMAN;
			case "unranked_group_ironman":
			case "ugim":
				return UNRANKED_GROUP_IRONMAN;
			default:
				return null;
		}
	}

	@Nullable
	static AccountType fromTempleGameMode(@Nullable String gameMode)
	{
		if (gameMode == null)
		{
			return null;
		}
		try
		{
			return fromProviderId(Integer.parseInt(gameMode));
		}
		catch (NumberFormatException ignored)
		{
			return fromProviderValue(gameMode);
		}
	}

	String displayName()
	{
		switch (this)
		{
			case IRONMAN: return "Ironman";
			case HARDCORE_IRONMAN: return "Hardcore Ironman";
			case ULTIMATE_IRONMAN: return "Ultimate Ironman";
			case GROUP_IRONMAN: return "Group Ironman";
			case HARDCORE_GROUP_IRONMAN: return "Hardcore Group Ironman";
			case UNRANKED_GROUP_IRONMAN: return "Unranked Group Ironman";
			default: return "Regular";
		}
	}
}

/*
 * Copyright (c) 2026, 420 kc <dyl@420kc.dev>
 * Slide-down activities tray: expandable content panel with eased animation.
 * Self-contained widget; the panel hands it the content + an onToggle hook,
 * the tray owns expanded state, the clip's preferred-size override, the
 * separator click target, and the Timer-driven slide.
 */
package com.killclog;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JPanel;
import javax.swing.Timer;
import lombok.Getter;
import net.runelite.client.ui.ColorScheme;

/**
 * Expandable tray with an eased height animation. Construction wires a content
 * panel into a clip whose preferred-size depends on the tray's expanded state;
 * {@link #getSeparator()} is the click target between this tray and whatever
 * lives below it. Clip + separator are exposed as Components so the panel can
 * place them inside its existing GridBag layout.
 */
public class ActivitiesTray
{
	private static final long SLIDE_MS = 150;
	private static final int SLIDE_TICK_MS = 12;

	private final JPanel content;
	@Getter
	private final JPanel clip;
	@Getter
	private final JPanel separator;
	private final Runnable onToggle;
	private boolean expanded;
	private Timer slideTimer;

	/**
	 * @param content the JPanel to show / hide inside the tray
	 * @param initiallyExpanded whether the tray starts expanded
	 * @param onToggle invoked after each toggle with the new expanded state (panel persists to config)
	 */
	public ActivitiesTray(JPanel content, boolean initiallyExpanded, OnToggle onToggle)
	{
		this.content = content;
		this.expanded = initiallyExpanded;
		this.onToggle = () -> onToggle.toggled(expanded);

		this.clip = new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getPreferredSize()
			{
				int h;
				if (slideTimer != null && slideTimer.isRunning())
				{
					h = super.getPreferredSize().height;
				}
				else if (expanded)
				{
					h = content.getPreferredSize().height;
				}
				else
				{
					h = 0;
				}
				return new Dimension(content.getPreferredSize().width, h);
			}
		};
		clip.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		clip.add(content, BorderLayout.NORTH);
		clip.setPreferredSize(new Dimension(0, expanded ? content.getPreferredSize().height : 0));
		clip.setVisible(expanded);

		// The separator is the tray's only toggle (the hamburger switches boss
		// views now), so it stays visible in BOTH states: hidden-when-collapsed
		// would make one collapse unrecoverable for the whole session.
		this.separator = new JPanel();
		separator.setBackground(ColorScheme.DARK_GRAY_COLOR);
		separator.setPreferredSize(new Dimension(0, 7));
		Color sepNormal = ColorScheme.DARK_GRAY_COLOR;
		Color sepHover = new Color(46, 46, 46);
		separator.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				toggle();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				separator.setBackground(sepHover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				separator.setBackground(sepNormal);
			}
		});
	}

	/** Run the slide animation, flip {@link #expanded}, and notify the onToggle hook. */
	public void toggle()
	{
		if (slideTimer != null && slideTimer.isRunning())
		{
			slideTimer.stop();
		}

		int startHeight = clip.getPreferredSize().height;
		expanded = !expanded;
		onToggle.run();

		int targetHeight = expanded ? content.getPreferredSize().height : 0;
		if (expanded)
		{
			clip.setVisible(true);
		}

		long startTime = System.currentTimeMillis();
		slideTimer = new Timer(SLIDE_TICK_MS, null);
		slideTimer.addActionListener(e ->
		{
			long elapsed = System.currentTimeMillis() - startTime;
			float progress = Math.min(1f, (float) elapsed / SLIDE_MS);
			// Ease-out: 1 - (1-t)^2
			float eased = 1f - (1f - progress) * (1f - progress);
			int height = startHeight + Math.round((targetHeight - startHeight) * eased);
			clip.setPreferredSize(new Dimension(0, height));
			clip.getParent().revalidate();

			if (progress >= 1f)
			{
				slideTimer.stop();
				if (!expanded)
				{
					clip.setVisible(false);
				}
			}
		});
		slideTimer.start();
	}

	/** Toggle callback the panel implements (typically: persist the new state to config). */
	public interface OnToggle
	{
		void toggled(boolean expanded);
	}
}

package com.killclog;

import java.util.Map;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import net.runelite.client.game.ItemManager;
import net.runelite.client.hiscore.HiscoreSkill;

final class ActivitySummaryTooltips
{
	private final LookupSession lookupSession;
	private final ComparisonController comparison;
	private final Cells cells;
	private final TooltipController tooltipController;
	private final ItemManager itemManager;
	private final CaRewardSprites caRewardSprites;
	private final Supplier<Boolean> wikiLinks;

	ActivitySummaryTooltips(LookupSession lookupSession, ComparisonController comparison,
		Cells cells, TooltipController tooltipController, ItemManager itemManager,
		CaRewardSprites caRewardSprites,
		Supplier<Boolean> wikiLinks)
	{
		this.lookupSession = lookupSession;
		this.comparison = comparison;
		this.cells = cells;
		this.tooltipController = tooltipController;
		this.itemManager = itemManager;
		this.caRewardSprites = caRewardSprites;
		this.wikiLinks = wikiLinks;
	}

	JToolTip buildPvm(JLabel owner, JPanel parentCell)
	{
		JToolTip tip = soloOrPair(owner,
			pvmTooltip(owner, lookupSession.getHiscoreResult(),
				lookupSession.getClogResult(), lookupSession.getCaResult(),
				cells.getTooltipDataMap()),
			() -> pvmTooltip(owner, comparison.getCompareHiscoreResult(),
				comparison.getCompareClogResult(), comparison.getCompareCaResult(),
				comparison.getCompareTooltipDataMap()));
		tooltipController.keepTooltipOnHover(tip, parentCell);
		return tip;
	}

	/** One player's Combat Summary card: solo mode shows it alone, comparison pairs two. */
	private PvmSummaryTooltip pvmTooltip(JLabel owner, @Nullable HiscoreResult hiscore,
		@Nullable ClogResult clog, @Nullable CombatAchievementResult ca,
		Map<HiscoreSkill, TooltipData> tooltipData)
	{
		PvmSummaryTooltip tip = new PvmSummaryTooltip();
		tip.setComponent(owner);
		// The combat cell's own icon, so the card repeats exactly what the panel shows.
		if (owner.getIcon() instanceof ImageIcon)
		{
			tip.setCombatIcon(((ImageIcon) owner.getIcon()).getImage());
		}
		tip.setWikiLinksEnabled(wikiLinks.get());
		tip.setData(
			hiscore != null ? hiscore.getCombatLevelExact() : 0,
			LookupQueries.sumBossKills(hiscore),
			LookupQueries.countBossesWithKc(hiscore),
			PanelData.bossCount(),
			LookupQueries.getMostKilledBoss(hiscore),
			LookupQueries.getMostKilledKc(hiscore)
		);
		tip.setPvp(hiscore, clog, cells.getPvpActivityIcons());
		tip.setEhb(EhbRates.compute(hiscore, LookupQueries.accountType(hiscore, clog)));
		tip.setSlayer(hiscore, clog);
		if (clog != null)
		{
			tip.setCompletion(
				LookupQueries.countBossesCompleted(tooltipData, cells.getBossLabels().keySet()),
				LookupQueries.countBossesWithClog(tooltipData, cells.getBossLabels().keySet()));
		}
		tip.setMegarares(
			LookupQueries.getClogItemCount(clog, PanelData.COX_CATEGORY, PanelData.TWISTED_BOW_ITEM_ID),
			LookupQueries.getClogItemCount(clog, PanelData.TOB_CATEGORY, PanelData.SCYTHE_ITEM_ID),
			LookupQueries.getClogItemCount(clog, PanelData.TOA_CATEGORY, PanelData.SHADOW_ITEM_ID),
			itemManager
		);
		tip.setSuperiors(
			LookupQueries.getClogItemCount(clog,
				PanelData.SLAYER_CATEGORY, PanelData.IMBUED_HEART_ITEM_ID),
			LookupQueries.getClogItemCount(clog,
				PanelData.SLAYER_CATEGORY, PanelData.ETERNAL_GEM_ITEM_ID),
			itemManager
		);
		if (hiscore != null)
		{
			tip.setRaids(hiscore, clog);
		}
		// A raid row opens that raid's popup where the summary was, like the Clue Summary's rares.
		tip.setOnOpenRaid((press, raid) -> tooltipController.pinTooltipFromPress(owner, (JPanel) owner.getParent(), press,
			TitleTooltip.withBack(cells.buildCellTooltipFor(owner, raid), "< Combat Summary", back ->
				tooltipController.pinTooltipFromPress(owner, (JPanel) owner.getParent(), back, owner.createToolTip()))));
		if (ca != null)
		{
			tip.setCombatAchievements(ca, caRewardSprites.sprite(ca.getReward(), PvmSummaryTooltip.ICON_SIZE));
		}
		return tip;
	}

	JToolTip buildSkills(JLabel owner)
	{
		JToolTip tip = soloOrPair(owner, skillsTooltip(owner, lookupSession.getHiscoreResult()),
			() -> skillsTooltip(owner, comparison.getCompareHiscoreResult()));
		if (owner.getParent() instanceof JPanel)
		{
			tooltipController.keepTooltipOnHover(tip, (JPanel) owner.getParent());
		}
		return tip;
	}

	/** The card alone, or beside the rival's while comparing. */
	private JToolTip soloOrPair(JLabel owner, JToolTip solo, Supplier<JToolTip> rival)
	{
		return comparison.isComparisonMode() && comparison.getCompareHiscoreResult() != null
			? comparison.wrapSideBySide(owner, solo, rival.get()) : solo;
	}

	/** One player's skills summary card: solo mode shows it alone, comparison pairs two. */
	private SkillsTooltip skillsTooltip(JLabel owner, @Nullable HiscoreResult result)
	{
		SkillsTooltip tip = new SkillsTooltip();
		tip.setComponent(owner);
		tip.setData(result);
		return tip;
	}
}

package com.killclog;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Harvests personal bests from the POH Adventure Log's Counters scroll.
 *
 * <p>The log opens in one of TWO menu interfaces and the player's in-game
 * interface-style setting decides which: the original ({@code MENU}) or the
 * newer ({@code MENU_NEW}). Vanilla's own harvest watches only the original,
 * so it works for players on that style and silently does nothing for
 * everyone on the newer one - which is why those players see no pbs beyond
 * what live kill-timer messages recorded since install. This reads both, so
 * the scroll backfills regardless of the setting.
 *
 * <p>Times land in Kill Clog's OWN rs-profile store - never vanilla's
 * "personalbest" namespace, which stays vanilla's to write - and the sync
 * payload tags them "advlog".
 */
@Slf4j
final class AdvLogPbs
{
	/* package */ static final String CONFIG_GROUP = "killclog";

	/**
	 * The harvest's timing, vanilla's two-stage shape: a menu load names the log's owner and the
	 * Counters scroll load triggers the parse a tick later, once its children are populated. The owner
	 * is scoped to one POH visit, so a friend's log can never linger and gate a later harvest.
	 */
	static final class Watch
	{
		private boolean titleLoaded;
		private boolean countersLoaded;
		private String owner;

		/** Both menu interfaces are watched: the interface-style setting decides which hosts the log. */
		void onWidgetLoaded(int groupId)
		{
			if (groupId == InterfaceID.MENU_NEW || groupId == InterfaceID.MENU)
			{
				titleLoaded = true;
			}
			else if (groupId == InterfaceID.JOURNALSCROLL)
			{
				countersLoaded = true;
			}
		}

		void dropOwner()
		{
			owner = null;
		}

		void onTick(Client client, ConfigManager configManager)
		{
			if (titleLoaded)
			{
				titleLoaded = false;
				// The new menu hosts more than the Adventure Log; another title leaves the owner as-is.
				String read = readOwner(client);
				if (read != null)
				{
					owner = read;
				}
			}
			if (countersLoaded)
			{
				countersLoaded = false;
				net.runelite.api.Player local = client.getLocalPlayer();
				if (local != null && sameName(local.getName(), owner))
				{
					new AdvLogPbs(configManager).harvest(client);
				}
				else
				{
					// Someone else's house, or the title never resolved: "not yours", not "found nothing".
					log.debug("adventure log counters skipped: owner '{}' is not the local player", owner);
				}
			}
		}
	}
	/* package */ static final String KEY_PREFIX = "advlogpb.";

	private static final Pattern TITLE_PATTERN = Pattern.compile("The Exploits of (.+)");
	// Vanilla's adventure-log pb line shape, verbatim: "Overall time" and
	// "(former)" lines intentionally fall through, and "-" (no time) never
	// matches the time group.
	private static final String TEAM_SIZES = "(?<teamsize>\\d+(?:\\+|-\\d+)? players?|Solo)";
	private static final Pattern PB_PATTERN = Pattern.compile(
		"Fastest (?:kill|run|Room time)(?: - \\(Team size: \\(?" + TEAM_SIZES + "\\)\\)?)?: (?<time>[0-9:]+(?:\\.[0-9]+)?)");

	/**
	 * Scroll section titles whose stored pb key differs beyond the article and
	 * colon shapes {@link PersonalBests#keyCandidates} already bridges. Values
	 * are vanilla's own store names (lowercased), so a scroll harvest and a
	 * live kill-timer message land on the same key.
	 */
	private static final Map<String, String> SCROLL_RENAMES = buildScrollRenames();

	private static Map<String, String> buildScrollRenames()
	{
		Map<String, String> renames = new LinkedHashMap<>();
		renames.put("tzhaar fight cave", "tztok-jad");
		renames.put("inferno", "tzkal-zuk");
		renames.put("fortis colosseum", "sol heredit");
		renames.put("lunar chests", "lunar chest");
		renames.put("doom", "doom of mokhaiotl");
		renames.put("chambers of xeric - challenge mode", "chambers of xeric challenge mode");
		renames.put("theatre of blood - hard mode", "theatre of blood hard mode");
		renames.put("theatre of blood - entry mode", "theatre of blood entry mode");
		renames.put("theatre of blood - story mode", "theatre of blood entry mode");
		renames.put("tombs of amascut - entry", "tombs of amascut entry mode");
		renames.put("tombs of amascut - expert", "tombs of amascut expert mode");
		return renames;
	}

	private final ConfigManager configManager;

	AdvLogPbs(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/**
	 * The Adventure Log owner, or null when the loaded menu is not an
	 * Adventure Log.
	 *
	 * <p>The game ships TWO menu interfaces and the player's interface-style
	 * setting decides which one opens: the original ({@code MENU}, what
	 * vanilla's chat-commands harvest watches) and the newer
	 * ({@code MENU_NEW}). Watching only one silently harvests nothing for
	 * every player on the other style, so both are read here. Cost of the
	 * unused lookup is one null widget.
	 *
	 * <p>The title text sits at a different child index in each, and is
	 * surrounded by null and non-text children, so both are scanned for the
	 * first matching line rather than indexed.
	 */
	static String readOwner(Client client)
	{
		String owner = readOwnerFrom(client, InterfaceID.MenuNew.TITLE);
		if (owner != null)
		{
			log.debug("adventure log owner '{}' read from the newer menu interface", owner);
			return owner;
		}
		owner = readOwnerFrom(client, InterfaceID.Menu.LJ_LAYER2);
		if (owner != null)
		{
			log.debug("adventure log owner '{}' read from the original menu interface", owner);
		}
		return owner;
	}

	/** Scan one container (its own text, then its children) for the title. */
	private static String readOwnerFrom(Client client, int componentId)
	{
		Widget container = client.getWidget(componentId);
		if (container == null)
		{
			return null;
		}
		String own = matchOwner(container.getText());
		if (own != null)
		{
			return own;
		}
		Widget[] children = container.getChildren();
		if (children == null)
		{
			return null;
		}
		for (Widget child : children)
		{
			if (child == null)
			{
				continue;
			}
			String found = matchOwner(child.getText());
			if (found != null)
			{
				return found;
			}
		}
		return null;
	}

	/* package */ static String matchOwner(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		Matcher matcher = TITLE_PATTERN.matcher(Text.removeTags(raw));
		return matcher.find() ? matcher.group(1) : null;
	}

	/** Owner gate with the nbsp/tag hygiene vanilla's raw compare lacks. */
	static boolean sameName(String localName, String owner)
	{
		return localName != null && owner != null
			&& Text.standardize(localName).equals(Text.standardize(owner));
	}

	/**
	 * Parse the Counters scroll into variant pb keys -> seconds. Lines arrive
	 * tag-stripped; the walk is vanilla's own (section title, then pb lines
	 * until a blank), with team sizes normalized exactly the way vanilla
	 * stores them ("1 player" -> solo, "2 player" -> "2 players").
	 */
	/* package */ static Map<String, Double> parseCounters(String[] text)
	{
		Map<String, Double> out = new LinkedHashMap<>();
		for (int i = 0; i < text.length; ++i)
		{
			String boss = canonicalSection(text[i]);
			for (i = i + 1; i < text.length; ++i)
			{
				String line = text[i];
				if (line.isEmpty())
				{
					break;
				}
				Matcher matcher = PB_PATTERN.matcher(line);
				if (!matcher.find())
				{
					continue;
				}
				double seconds = timeToSeconds(matcher.group("time"));
				String teamSize = matcher.group("teamsize");
				String key = boss;
				if (teamSize != null)
				{
					if (teamSize.equals("1 player"))
					{
						teamSize = "Solo";
					}
					else if (teamSize.endsWith("player"))
					{
						teamSize = teamSize + "s";
					}
					key = boss + " " + teamSize.toLowerCase(Locale.ROOT);
				}
				// Duplicate sections exist in real scrolls; keep the fastest.
				Double prev = out.get(key);
				if (seconds > 0 && (prev == null || seconds < prev))
				{
					out.put(key, seconds);
				}
			}
		}
		return out;
	}

	/**
	 * A scroll section title in the pb store's key space: lowercase, leading
	 * article dropped (vanilla's store names do - "The Nightmare" lives under
	 * "nightmare"), the mode-raid separator collapsed, true renames applied.
	 * Whatever shape survives, the gather probes both article forms via
	 * {@link PersonalBests#keyCandidates}, so the lanes converge either way.
	 */
	/* package */ static String canonicalSection(String title)
	{
		String key = title.toLowerCase(Locale.ROOT).trim();
		String[] keys = PersonalBests.keyCandidates(key);
		return SCROLL_RENAMES.getOrDefault(key, keys[keys.length - 1]);
	}

	/** Vanilla's time parser: mm:ss(.f) and h:mm:ss(.f). */
	/* package */ static double timeToSeconds(String time)
	{
		String[] s = time.split(":");
		if (s.length == 2)
		{
			return Integer.parseInt(s[0]) * 60 + Double.parseDouble(s[1]);
		}
		else if (s.length == 3)
		{
			return Integer.parseInt(s[0]) * 60 * 60 + Integer.parseInt(s[1]) * 60 + Double.parseDouble(s[2]);
		}
		return Double.parseDouble(time);
	}

	/**
	 * Read the loaded Counters scroll and persist every parsed pb, min-wins
	 * per key. Returns how many keys were recorded or improved. Client thread
	 * (widget + config access).
	 */
	int harvest(Client client)
	{
		Widget parent = client.getWidget(InterfaceID.Journalscroll.TEXTLAYER);
		if (parent == null || parent.getStaticChildren() == null)
		{
			return 0;
		}
		Widget[] children = parent.getStaticChildren();
		String[] text = new String[children.length];
		for (int i = 0; i < children.length; i++)
		{
			String raw = children[i] != null ? children[i].getText() : null;
			text[i] = raw != null ? Text.removeTags(raw) : "";
		}
		Map<String, Double> parsed = parseCounters(text);
		int recorded = 0;
		for (Map.Entry<String, Double> entry : parsed.entrySet())
		{
			if (record(entry.getKey(), entry.getValue()))
			{
				recorded++;
			}
		}
		// Both counts, always: a repeat visit legitimately records nothing
		// (min-wins keeps the existing time), and a silent zero is
		// indistinguishable from a parse that never ran.
		log.debug("adventure log harvest: {} lines, parsed {} pbs, {} new or improved",
			text.length, parsed.size(), recorded);
		return recorded;
	}

	/** Min-wins write into the plugin's own store; true when it changed. */
	private boolean record(String key, double seconds)
	{
		Double prev = configManager.getRSProfileConfiguration(
			CONFIG_GROUP, KEY_PREFIX + key, double.class);
		if (prev != null && prev > 0 && prev <= seconds)
		{
			return false;
		}
		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_PREFIX + key, seconds);
		return true;
	}
}

/*
 * Copyright (c) 2026, 420 kc <dyl@420kc.dev>
 * Full-width boss list in the hiscores' own order: the list-style alternative
 * to the boss grid. One row per boss - [icon] name, colored kc - reusing the
 * grid's tooltip routing so every row opens the same clog popup as its cell.
 */
package com.killclog;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.beans.PropertyChangeListener;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import javax.swing.border.EmptyBorder;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * List-style rendering of the boss cells. Rows MIRROR the grid labels rather
 * than re-deriving values: the grid is always rendered (even while hidden),
 * and each row listens to its grid label's text / foreground / icon property
 * changes. Every writer - the search-start reset, results landing, the
 * completionist highlighter, whatever comes next - propagates into
 * the list with no per-call-site wiring, which is what keeps the two views
 * incapable of disagreeing.
 *
 * <p>The one deliberate pause: while comparison holds the grid on screen the
 * mirror skips text and foreground, so compare's per-hover HTML rewrites
 * never reach the hidden rows; the exit path rewrites both, which resyncs
 * them. Icons keep mirroring straight through - comparison never writes
 * icons, and an async sprite landing mid-compare would otherwise be lost
 * for good (reapplying the same ImageIcon later fires no change event).
 * {@link #resyncAll()} backstops the whole contract whenever the list is
 * about to show.
 */
public class BossListView
{
	private static final int ROW_HEIGHT = 22;
	private static final int KC_WIDTH = 46;

	private final JPanel root;
	private final Map<HiscoreSkill, Row> rows = new LinkedHashMap<>();
	private final BooleanSupplier mirrorActive;

	private static final class Row
	{
		JLabel icon;
		JLabel name;
		JLabel kc;
		JLabel gridLabel;
	}

	/**
	 * @param mirrorActive false while the grid is the forced view (compare);
	 * the mirror skips those writes and the exit rewrite resyncs the rows
	 */
	public BossListView(TooltipController tooltipController, Cells cells, BooleanSupplier mirrorActive)
	{
		this.mirrorActive = mirrorActive;
		root = new JPanel();
		root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
		root.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		// PanelData.BOSSES is the Jagex hiscores order: near-alphabetical with
		// vanilla's deliberate pairings kept (Nightmare then Phosani's,
		// Gauntlet then Corrupted). The list keeps vanilla's order rather
		// than imposing a strict sort - players have already scanned this
		// exact order in the game's own hiscores.
		for (HiscoreSkill boss : PanelData.BOSSES)
		{
			root.add(buildRow(boss, tooltipController, cells));
			installMirror(boss, cells);
		}
	}

	/** The stacked-rows component the panel places where the grid goes. */
	public JPanel component()
	{
		return root;
	}

	/**
	 * Re-copy every row from its grid label. Called before the list shows,
	 * so it always opens on grid truth regardless of what the paused mirror
	 * skipped - the structural backstop for the pause contract above.
	 */
	public void resyncAll()
	{
		for (Row row : rows.values())
		{
			if (row.gridLabel == null)
			{
				continue;
			}
			sync(row, row.gridLabel, "text");
			sync(row, row.gridLabel, "foreground");
			sync(row, row.gridLabel, "icon");
		}
	}

	/**
	 * Subscribe the row to its grid label: one listener, registered under
	 * each mirrored property name. Named registration keeps it off the
	 * label's unrelated property traffic (tooltips flip on every lookup).
	 */
	private void installMirror(HiscoreSkill boss, Cells cells)
	{
		JLabel gridLabel = cells.getBossLabel(boss);
		Row row = rows.get(boss);
		if (gridLabel == null || row == null)
		{
			return;
		}
		row.gridLabel = gridLabel;
		PropertyChangeListener mirror = e ->
		{
			// Icons pass the pause: comparison never writes them, and an
			// async sprite load landing mid-compare is the only icon event
			// there is - skip it and the post-exit render reapplies the same
			// ImageIcon object, which fires nothing to catch the row up.
			if ("icon".equals(e.getPropertyName()) || mirrorActive.getAsBoolean())
			{
				sync(row, gridLabel, e.getPropertyName());
			}
		};
		gridLabel.addPropertyChangeListener("text", mirror);
		gridLabel.addPropertyChangeListener("foreground", mirror);
		gridLabel.addPropertyChangeListener("icon", mirror);

		// Initial sync: the labels are freshly built with cold defaults, but
		// copying once here removes any ordering assumption.
		sync(row, gridLabel, "text");
		sync(row, gridLabel, "foreground");
		sync(row, gridLabel, "icon");
	}

	private static void sync(Row row, JLabel gridLabel, String property)
	{
		switch (property)
		{
			case "text":
				String text = gridLabel.getText();
				row.kc.setText(text != null ? text.trim() : "");
				break;
			case "foreground":
				// The name wears the same color as the kc: completion
				// gradient when the highlighter is on, soft kc/grey when off.
				row.kc.setForeground(gridLabel.getForeground());
				row.name.setForeground(gridLabel.getForeground());
				break;
			case "icon":
				// The grid renders the exact icon the row wants (same 20x20
				// pipeline, dim state decided by renderBossValue), so mirror
				// the object itself; any future icon writer is covered too.
				row.icon.setIcon(gridLabel.getIcon());
				break;
			default:
				break;
		}
	}

	private JPanel buildRow(HiscoreSkill boss, TooltipController tooltipController,
		Cells cells)
	{
		Row row = new Row();

		// All three labels carry the boss tooltip so the WHOLE row pops the
		// clog popup in hover mode - icon and kc included, no dead zones.
		// The icon itself arrives via the mirror when the grid's loads.
		row.icon = bossTooltipLabel(boss, cells);
		row.icon.setPreferredSize(new Dimension(24, ROW_HEIGHT));
		row.icon.setHorizontalAlignment(JLabel.CENTER);

		row.name = bossTooltipLabel(boss, cells);
		row.name.setText(boss.getName());
		row.name.setFont(FontManager.getRunescapeSmallFont());
		row.name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		ClogHelper.antialias(row.name);

		row.kc = bossTooltipLabel(boss, cells);
		row.kc.setText("--");
		row.kc.setFont(FontManager.getRunescapeSmallFont());
		row.kc.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		row.kc.setHorizontalAlignment(JLabel.RIGHT);
		row.kc.setPreferredSize(new Dimension(KC_WIDTH, ROW_HEIGHT));
		row.kc.setBorder(new EmptyBorder(0, 0, 0, 4));
		ClogHelper.antialias(row.kc);

		JPanel panel = new JPanel(new BorderLayout(4, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(TooltipController.CELL_BORDER);
		panel.setPreferredSize(new Dimension(0, ROW_HEIGHT));
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		panel.add(row.icon, BorderLayout.WEST);
		panel.add(row.name, BorderLayout.CENTER);
		panel.add(row.kc, BorderLayout.EAST);
		// Outline color follows the kc label (mirrored from the grid, so the
		// completion highlighter shows through, same as the grid cell); the
		// name stays the popup anchor for bare-cell presses.
		tooltipController.addCellHoverEffect(panel, row.kc, row.name, row.icon, row.kc);

		rows.put(boss, row);
		return panel;
	}

	/** A row label that routes its tooltip through the grid's boss popup. */
	private static JLabel bossTooltipLabel(HiscoreSkill boss, Cells cells)
	{
		JLabel label = new JLabel()
		{
			@Override
			public JToolTip createToolTip()
			{
				return cells.buildCellTooltipFor(this, boss);
			}
		};
		label.setToolTipText(" ");
		return label;
	}

}

package com.killclog;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.AccessLevel;
import lombok.Getter;

final class BulkCaptureState
{
	@Getter(AccessLevel.PACKAGE)
	private boolean active;
	int startTickCount = -1;
	int finalizeTickCount = -1;
	int clogCount = -1;
	int clogTotal = -1;
	final List<ClogResult.ClogItem> obtained = new ArrayList<>();
	final Set<Integer> obtainedIds = new HashSet<>();

	boolean readyToFinalize(int tickCount)
	{
		return active && finalizeTickCount > 0 && tickCount >= finalizeTickCount;
	}

	boolean timedOut(int tickCount, int timeoutTicks)
	{
		return active && finalizeTickCount < 0 && startTickCount >= 0
			&& tickCount - startTickCount > timeoutTicks;
	}

	void arm(int tickCount, int clogCount, int clogTotal)
	{
		active = true;
		startTickCount = tickCount;
		finalizeTickCount = -1;
		this.clogCount = clogCount;
		this.clogTotal = clogTotal;
		obtained.clear();
		obtainedIds.clear();
	}

	void captureScriptArguments(Object[] args, int tickCount)
	{
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}

		int itemId = (int) args[1];
		int count = (int) args[2];
		if (itemId <= 0 || count <= 0)
		{
			return;
		}
		if (obtainedIds.add(itemId))
		{
			obtained.add(new ClogResult.ClogItem(itemId, count, null));
		}
		finalizeTickCount = tickCount + 3;
	}

	void scheduleEmptySearchFinalization(int tickCount)
	{
		if (active && clogCount == 0)
		{
			// A known catalog total is already settled. Both counters at zero can
			// also mean a brand-new account, so leave room for delayed scripts.
			finalizeTickCount = tickCount + (clogTotal > 0 ? 3 : 10);
		}
	}

	void deferEmptyFinalizationIfItemsReported(int reportedCount)
	{
		if (active && reportedCount > 0 && obtained.isEmpty())
		{
			finalizeTickCount = -1;
		}
	}

	void reset()
	{
		active = false;
		startTickCount = -1;
		finalizeTickCount = -1;
		clogCount = -1;
		clogTotal = -1;
		obtained.clear();
		obtainedIds.clear();
	}
}

package com.killclog;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

/**
 * Live Combat Achievement catalog, read from the game's own tier-threshold
 * varbits. The client broadcasts the current points threshold for every tier,
 * and those thresholds encode the whole catalog: each tier's step over the
 * previous threshold is that tier's total points, so its task count is the
 * step divided by its points per task. A Combat Achievement release moves the
 * varbits on day one, so tier math computed from here never trails the game
 * the way the fallback constants in {@link CombatAchievementTier} or a
 * provider snapshot can.
 *
 * <p>Captured on the client thread; published as an immutable map through a
 * volatile field so HTTP-thread consumers (RuneProfile parsing) see a complete
 * snapshot or none.
 */
final class CaCatalog
{
	private volatile Map<CombatAchievementTier, Integer> totals;

	/** True for the tier-threshold varbits this catalog is derived from. */
	static boolean isThresholdVarbit(int id)
	{
		return id == VarbitID.CA_THRESHOLD_EASY
			|| id == VarbitID.CA_THRESHOLD_MEDIUM
			|| id == VarbitID.CA_THRESHOLD_HARD
			|| id == VarbitID.CA_THRESHOLD_ELITE
			|| id == VarbitID.CA_THRESHOLD_MASTER
			|| id == VarbitID.CA_THRESHOLD_GRANDMASTER;
	}

	/**
	 * Read the six threshold varbits and derive per-tier task totals. Keeps the
	 * previous capture when the read is invalid (pre-login zeros or a
	 * mid-update partial state).
	 */
	boolean capture(Client client)
	{
		Map<CombatAchievementTier, Integer> thresholds = new EnumMap<>(CombatAchievementTier.class);
		thresholds.put(CombatAchievementTier.EASY, client.getVarbitValue(VarbitID.CA_THRESHOLD_EASY));
		thresholds.put(CombatAchievementTier.MEDIUM, client.getVarbitValue(VarbitID.CA_THRESHOLD_MEDIUM));
		thresholds.put(CombatAchievementTier.HARD, client.getVarbitValue(VarbitID.CA_THRESHOLD_HARD));
		thresholds.put(CombatAchievementTier.ELITE, client.getVarbitValue(VarbitID.CA_THRESHOLD_ELITE));
		thresholds.put(CombatAchievementTier.MASTER, client.getVarbitValue(VarbitID.CA_THRESHOLD_MASTER));
		thresholds.put(CombatAchievementTier.GRANDMASTER, client.getVarbitValue(VarbitID.CA_THRESHOLD_GRANDMASTER));

		Map<CombatAchievementTier, Integer> derived = deriveTotals(thresholds);
		if (derived == null)
		{
			return false;
		}
		totals = Collections.unmodifiableMap(derived);
		return true;
	}

	/** Current per-tier task totals, or null before a valid capture. */
	Map<CombatAchievementTier, Integer> totals()
	{
		return totals;
	}

	/** Test seam: a catalog pre-published with the given totals. */
	/* package */ static CaCatalog withTotals(Map<CombatAchievementTier, Integer> totals)
	{
		CaCatalog catalog = new CaCatalog();
		catalog.totals = Collections.unmodifiableMap(new EnumMap<>(totals));
		return catalog;
	}

	void clear()
	{
		totals = null;
	}

	/**
	 * Thresholds to per-tier task counts. Each tier's step over the previous
	 * threshold must be positive and divide evenly by its points per task;
	 * anything else is a partial or garbled read and yields null.
	 */
	/* package */ static Map<CombatAchievementTier, Integer> deriveTotals(
		Map<CombatAchievementTier, Integer> thresholds)
	{
		Map<CombatAchievementTier, Integer> derived = new EnumMap<>(CombatAchievementTier.class);
		int prev = 0;
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			Integer threshold = thresholds.get(tier);
			if (threshold == null || threshold <= prev)
			{
				return null;
			}
			int step = threshold - prev;
			if (step % tier.pointsPerTask() != 0)
			{
				return null;
			}
			derived.put(tier, step / tier.pointsPerTask());
			prev = threshold;
		}
		return derived;
	}
}

package com.killclog;

import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;
import javax.swing.SwingUtilities;

final class CaRewardSprites
{
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final Runnable onLoaded;
	private final Map<CombatAchievementReward, BufferedImage> cache =
		new EnumMap<>(CombatAchievementReward.class);
	private final Set<CombatAchievementReward> loading =
		EnumSet.noneOf(CombatAchievementReward.class);

	CaRewardSprites(ItemManager itemManager, ClientThread clientThread, Runnable onLoaded)
	{
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.onLoaded = onLoaded;
	}

	void preloadAll()
	{
		for (CombatAchievementReward reward : CombatAchievementReward.values())
		{
			request(reward);
		}
	}

	void request(CombatAchievementReward reward)
	{
		if (reward == null || cache.containsKey(reward) || !loading.add(reward))
		{
			return;
		}
		clientThread.invokeLater(() -> load(reward));
	}

	BufferedImage sprite(CombatAchievementReward reward, int height)
	{
		if (reward == null)
		{
			return null;
		}
		BufferedImage img = cache.get(reward);
		if (img == null)
		{
			request(reward);
			return null;
		}
		if (img.getHeight() <= 0)
		{
			return null;
		}
		int width = (int) Math.round((double) img.getWidth() / img.getHeight() * height);
		return ImageUtil.resizeImage(img, width, height);
	}

	private void load(CombatAchievementReward reward)
	{
		BufferedImage img = itemManager.getImage(reward.itemId(), 1, false);
		if (img instanceof AsyncBufferedImage)
		{
			((AsyncBufferedImage) img).onLoaded(() ->
				SwingUtilities.invokeLater(() -> store(reward, img)));
		}
		else
		{
			SwingUtilities.invokeLater(() -> store(reward, img));
		}
	}

	private void store(CombatAchievementReward reward, BufferedImage img)
	{
		if (img != null)
		{
			cache.put(reward, img);
		}
		loading.remove(reward);
		onLoaded.run();
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.ObjIntConsumer;
import java.util.function.ToIntFunction;
import javax.annotation.Nullable;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * A card's body as one list of parts. Each part measures itself, paints itself and registers its own
 * hover and click areas, so a card states its layout once: its size and its painting can't disagree,
 * and a new row is one more part.
 */
final class CardBody
{
	/** One piece of a body: its width and height, and how it paints at a given y. */
	interface Part
	{
		int width(Ctx c);

		int height(Ctx c);

		void paint(Ctx c, int y);
	}

	/** Paints one part at y. */
	interface Painter
	{
		void paint(Ctx c, int y);
	}

	/** Paints a clickable row at y, white while hovered. */
	interface RowPainter
	{
		void paint(Ctx c, int y, boolean hovered);
	}

	/** What a part sees: its card, the small and bold fonts, and while painting the surface and width. */
	static final class Ctx
	{
		final TitleTooltip card;
		final FontMetrics fm;
		final FontMetrics bfm;
		final int available;
		final Graphics2D g;
		final int w;
		final List<TooltipItemHover.HitBox> hits = new ArrayList<>();
		// What shows of a scrolled part: a row moved out of it can't be pressed.
		@Nullable
		Rectangle window;

		private Ctx(TitleTooltip card, FontMetrics fm, FontMetrics bfm, int available, Graphics2D g, int w)
		{
			this.card = card;
			this.fm = fm;
			this.bfm = bfm;
			this.available = available;
			this.g = g;
			this.w = w;
		}

		int inset()
		{
			return NativeTooltip.getInset();
		}
	}

	private final List<Part> parts = new ArrayList<>();

	CardBody add(Part part)
	{
		parts.add(part);
		return this;
	}

	/** The body's parts as one part, as a card scrolls everything under its anchored band. */
	Part asPart()
	{
		return part(c ->
		{
			int width = 0;
			for (Part part : parts)
			{
				width = Math.max(width, part.width(c));
			}
			return width;
		}, c ->
		{
			int height = 0;
			for (Part part : parts)
			{
				height += part.height(c);
			}
			return height;
		}, (c, y) ->
		{
			int top = y;
			for (Part part : parts)
			{
				part.paint(c, top);
				top += part.height(c);
			}
		});
	}

	/** A titled section under the parts before it: room above, not a divider, since its title carries a rule. */
	CardBody titled(String title)
	{
		return add(gap(SECTION_SPACE)).add(section(title));
	}

	/** The body's size: as wide as its widest part, as tall as its parts together. */
	Dimension size(TitleTooltip card, int available)
	{
		Ctx c = new Ctx(card, card.getFontMetrics(FontManager.getRunescapeSmallFont()),
			card.getFontMetrics(FontManager.getRunescapeBoldFont()), available, null, 0);
		int width = 0;
		int height = 0;
		for (Part part : parts)
		{
			width = Math.max(width, part.width(c));
			height += part.height(c);
		}
		return new Dimension(width, height);
	}

	/** Paints every part down from startY in the small font; returns the item hit boxes they laid down. */
	List<TooltipItemHover.HitBox> paint(TitleTooltip card, Graphics2D g, int w, int startY)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		Ctx c = new Ctx(card, g.getFontMetrics(), g.getFontMetrics(FontManager.getRunescapeBoldFont()),
			w - 2 * NativeTooltip.getInset(), g, w);
		int y = startY;
		for (Part part : parts)
		{
			part.paint(c, y);
			y += part.height(c);
		}
		return c.hits;
	}

	// ---- Parts --------------------------------------------------------------------------------

	static Part part(ToIntFunction<Ctx> width, ToIntFunction<Ctx> height, Painter painter)
	{
		return new Part()
		{
			@Override
			public int width(Ctx c)
			{
				return width.applyAsInt(c);
			}

			@Override
			public int height(Ctx c)
			{
				return height.applyAsInt(c);
			}

			@Override
			public void paint(Ctx c, int y)
			{
				painter.paint(c, y);
			}
		};
	}

	/** One line of the given height painted by hand, measured by width. */
	static Part row(int height, ToIntFunction<Ctx> width, Painter painter)
	{
		return part(width, c -> height, painter);
	}

	static Part gap(int height)
	{
		return part(c -> 0, c -> height, (c, y) ->
		{
		});
	}

	/** Holds the body at least this wide without taking any room. */
	static Part minWidth(ToIntFunction<Ctx> width)
	{
		return part(width, c -> 0, (c, y) ->
		{
		});
	}

	/** An orange label with its value right after it. */
	static Part line(String label, String value, Color color)
	{
		return row(NativeTooltip.LINE_HEIGHT, c -> c.fm.stringWidth(label + value),
			(c, y) -> TitleTooltip.drawLabelValue(c.g, c.fm, c.inset(), y + c.fm.getAscent(), label, value, color));
	}

	static Part line(String label, String value)
	{
		return line(label, value, Color.WHITE);
	}

	static Part text(String text, Color color, boolean measured)
	{
		return row(NativeTooltip.LINE_HEIGHT, c -> measured ? c.fm.stringWidth(text) : 0, (c, y) ->
		{
			c.g.setColor(color);
			c.g.drawString(text, c.inset(), y + c.fm.getAscent());
		});
	}

	// A section's title owns a full-width rule just under it, then room before its rows; sections stand apart by
	// space alone. Every card titles its sections this way, and a skill log titles its headings the same.
	static final int SECTION_SPACE = 8;
	static final int SECTION_RULE = 3;
	static final int SECTION_AFTER = 4;

	/** A section's bold title with its rule under it. */
	static Part section(String title)
	{
		return row(TitleTooltip.SUBHEADER_HEIGHT + SECTION_RULE + SECTION_AFTER, c -> c.bfm.stringWidth(title), (c, y) ->
		{
			c.card.paintSubheader(c.g, y, title);
			sectionRule(c.g, y + TitleTooltip.SUBHEADER_HEIGHT + 1, c.inset(), c.w);
		});
	}

	/** The rule under a section's title, across the card. */
	static void sectionRule(Graphics2D g, int y, int inset, int w)
	{
		g.setColor(TitleTooltip.SEPARATOR_COLOR);
		g.drawLine(inset, y, w - inset - 1, y);
	}

	static Part separator(int pad)
	{
		return row(TitleTooltip.separatorHeight(pad), c -> 0, (c, y) -> c.card.paintSeparator(c.g, c.w, y, pad));
	}

	private static final int BAND_PAD = 4;

	/**
	 * The line a card names its hovered item on, above its sprites between a divider above and one below, so
	 * the name has the card's full width and its own place while the sprites scroll under it.
	 */
	static Part hoverBand()
	{
		return band(BAND_PAD);
	}

	/** The same band straight under the header, the header's own divider the one above it. */
	static Part headerHoverBand()
	{
		return band(-1 - TitleTooltip.SEPARATOR_GAP);
	}

	/** A band whose top divider sits {@code above} the part's top; a negative one is the divider already there. */
	private static Part band(int above)
	{
		return part(c -> 0, c -> above + 1 + TitleTooltip.hoverRowHeight(c.fm) + 1 + BAND_PAD, (c, y) ->
		{
			int top = y + above;
			int height = TitleTooltip.hoverRowHeight(c.fm);
			c.g.setColor(TitleTooltip.SEPARATOR_COLOR);
			if (above >= 0)
			{
				c.g.drawLine(c.inset(), top, c.w - c.inset() - 1, top);
			}
			c.g.drawLine(c.inset(), top + height + 1, c.w - c.inset() - 1, top + height + 1);
			c.card.paintHeaderHoverLine(c.g, c.fm, c.w, top + 1 + c.fm.getAscent());
		});
	}

	/**
	 * A row of full-size item sprites from the left edge, a grid one row high: unobtained ones dimmed,
	 * quantities in the corner, each hover-naming and wiki-linking like the grids do.
	 */
	static Part sprites(int section, @Nullable TooltipItemSprites sprites, int[] ids, String[] names, int[] counts,
		int pad)
	{
		Map<Integer, String> named = new HashMap<>();
		Map<Integer, Integer> held = new HashMap<>();
		Set<Integer> obtained = new HashSet<>();
		for (int i = 0; i < ids.length; i++)
		{
			named.put(ids[i], names[i]);
			held.put(ids[i], counts[i]);
			if (counts[i] > 0)
			{
				obtained.add(ids[i]);
			}
		}
		int width = ids.length * (GRID_SPRITE + pad) - pad;
		return row(GRID_SPRITE, c -> width, (c, y) -> c.hits.addAll(TooltipItemSprites.paintGrid(c.g, sprites, named,
			section, TooltipData.itemList(ids), obtained, held, c.inset(), y,
			ids.length, GRID_SPRITE, GRID_SPRITE + pad)));
	}

	/** One row that opens something: it answers hover in white and a left press with its key. */
	static Part clickRow(ClickRows rows, int key, ToIntFunction<Ctx> width, RowPainter painter)
	{
		return clickRow(rows, key, NativeTooltip.LINE_HEIGHT, width, painter);
	}

	/** The same row at its own height, for text a size up. */
	static Part clickRow(ClickRows rows, int key, int height, ToIntFunction<Ctx> width, RowPainter painter)
	{
		return row(height, width, (c, y) ->
		{
			// Only what shows of the row answers, so one scrolled out of view can't be pressed.
			int top = c.window != null ? Math.max(y, c.window.y) : y;
			int bottom = c.window != null ? Math.min(y + height, c.window.y + c.window.height) : y + height;
			rows.span(top, bottom - top, key);
			painter.paint(c, y, rows.lastY >= top && rows.lastY < bottom);
		});
	}

	static final int RAIL_WIDTH = 3;
	static final int RAIL_GAP = 4;
	// Every scrolled card shows the same height: 24 lines, the length of a long Collection Log tab.
	static final int WINDOW = 24 * NativeTooltip.LINE_HEIGHT;

	/** The thin rail beside a scrolled window: its track, and the thumb where the window sits. */
	static void rail(Ctx c, int y, int track, int shown, int total, int offset, int range)
	{
		int x = c.w - c.inset() - RAIL_WIDTH;
		int thumb = Math.max(NativeTooltip.LINE_HEIGHT, track * shown / total);
		c.g.setColor(NativeTooltip.railTrack(TitleTooltip.SEPARATOR_COLOR));
		c.g.fillRect(x, y, RAIL_WIDTH, track);
		c.g.setColor(NativeTooltip.railThumb());
		c.g.fillRect(x, y + (track - thumb) * offset / range, RAIL_WIDTH, thumb);
	}

	/**
	 * A part shown through a window no taller than {@code window}: the mouse wheel moves it a step at a
	 * time beside a rail, and only what shows can be hovered or pressed. A part that fits paints as it is.
	 */
	static Part scroll(Scroll scroll, Part inner)
	{
		return part(c -> inner.width(c) + (scroll.scrolls(inner.height(c)) ? RAIL_GAP + RAIL_WIDTH : 0),
			c -> scroll.scrolls(inner.height(c)) ? scroll.window : inner.height(c), (c, y) ->
			{
				if (!scroll.scrolls(inner.height(c)))
				{
					scroll.range = 0;
					inner.paint(c, y);
					return;
				}
				Ctx view = new Ctx(c.card, c.fm, c.bfm, c.available - RAIL_GAP - RAIL_WIDTH, c.g, c.w - RAIL_GAP - RAIL_WIDTH);
				Rectangle window = new Rectangle(0, y, c.w, scroll.window);
				view.window = window;
				int height = inner.height(view);
				scroll.range = Math.max(0, height - scroll.window);
				scroll.offset = Math.min(scroll.offset, scroll.range);
				Shape clip = c.g.getClip();
				c.g.clipRect(0, y, c.w, scroll.window);
				inner.paint(view, y - scroll.offset);
				c.g.setClip(clip);
				for (TooltipItemHover.HitBox hit : view.hits)
				{
					TooltipItemHover.HitBox shown = hit.within(window);
					if (shown != null)
					{
						c.hits.add(shown);
					}
				}
				rail(c, y, scroll.window, scroll.window, height, scroll.offset, scroll.range);
			});
	}

	/** Where a scrolled part's window sits; the card's mouse wheel moves it. */
	static final class Scroll
	{
		private final TitleTooltip card;
		private final int window;
		private final int step;
		private int offset;
		private int range;
		private double wheel;
		@Nullable
		private Scroll partner;

		Scroll(TitleTooltip card, int window, int step)
		{
			this.card = card;
			this.window = window;
			this.step = step;
			card.addMouseWheelListener(this::wheel);
		}

		/** Keeps two players' sides at the same place as either one scrolls. */
		void scrollWith(Scroll other)
		{
			partner = other;
			other.partner = this;
		}

		int offset()
		{
			return offset;
		}

		/** Only a part that would move at least a notch scrolls; one that overflows by less shows whole. */
		boolean scrolls(int height)
		{
			return height > window + step;
		}

		/** For a part that draws its own window, like a list: how far it can move; returns where it is. */
		int follow(int range)
		{
			this.range = range;
			offset = Math.min(offset, range);
			return offset;
		}

		void wheel(MouseWheelEvent e)
		{
			if (range <= 0)
			{
				return;
			}
			wheel += e.getPreciseWheelRotation();
			int notches = (int) wheel;
			wheel -= notches;
			moveTo(offset + notches * step);
			if (partner != null)
			{
				partner.moveTo(offset);
			}
			e.consume();
		}

		private void moveTo(int next)
		{
			next = Math.max(0, Math.min(range, next));
			if (next != offset)
			{
				offset = next;
				card.itemHover.rehoverAfterPaint();
				card.repaint();
			}
		}
	}

	// Full-size item sprites a gap apart; a scrolled grid's window holds whole rows of them.
	static final int GRID_SPRITE = 32;
	static final int GRID_GAP = 4;
	static final int GRID_CELL = GRID_SPRITE + GRID_GAP;
	static final int GRID_WINDOW = WINDOW / GRID_CELL * GRID_CELL - GRID_GAP;

	/**
	 * Full-size item sprites centered in at least {@code minCols} columns, or as many more as the card's
	 * width already holds: unobtained ones dimmed, quantities in the corner, each hover-naming and wiki-linking.
	 */
	static Part grid(int minCols, @Nullable TooltipItemSprites sprites, @Nullable Map<Integer, String> names,
		List<Integer> ids, Set<Integer> obtained, Map<Integer, Integer> counts)
	{
		int count = ids.size();
		return part(c -> gridColumns(minCols, count, c.available) * GRID_CELL - GRID_GAP,
			c -> (count + gridColumns(minCols, count, c.available) - 1) / gridColumns(minCols, count, c.available)
				* GRID_CELL - GRID_GAP, (c, y) ->
			{
				int cols = gridColumns(minCols, count, c.available);
				int width = cols * GRID_CELL - GRID_GAP;
				c.hits.addAll(TooltipItemSprites.paintGrid(c.g, sprites, names, 0, ids, obtained, counts,
					c.inset() + (c.w - 2 * c.inset() - width) / 2, y, cols, GRID_SPRITE, GRID_CELL));
			});
	}

	/** A grid's own columns: the minimum asked for, no fewer than four even for a shorter list. */
	static int gridColumns(int minCols, int count)
	{
		return Math.min(Math.max(minCols, 1), Math.max(4, Math.max(count, 1)));
	}

	/** The grid's own columns, or more when a long title already pays for the width. */
	private static int gridColumns(int minCols, int count, int available)
	{
		int cols = gridColumns(minCols, count);
		int fit = (available + GRID_GAP) / GRID_CELL;
		return available > 0 && fit > cols ? Math.min(fit, count) : cols;
	}

	/**
	 * A table of icon, label, a right-aligned score column, then a progress column and a rank column,
	 * each as wide as its widest entry. Progress and rank show only where the caller gives them.
	 */
	static Part table(BufferedImage[] icons, String[] labels, int[] scores, int[] obtained, int[] total,
		int[] ranks, int iconSize, int iconGap, int colGap)
	{
		ToIntFunction<FontMetrics> scoreRight = fm ->
		{
			int labelCol = 0;
			for (String label : labels)
			{
				labelCol = Math.max(labelCol, fm.stringWidth(label));
			}
			return iconSize + iconGap + labelCol + colGap + TitleTooltip.widestValue(fm, scores, TitleTooltip::scoreText);
		};
		ToIntFunction<FontMetrics> progressCol = fm ->
		{
			int width = 0;
			for (int i = 0; i < labels.length; i++)
			{
				if (obtained[i] >= 0)
				{
					width = Math.max(width, TitleTooltip.wrappedProgressCountWidth(fm, obtained[i], total[i]));
				}
			}
			return width;
		};
		ToIntFunction<FontMetrics> rankCol = fm ->
		{
			int width = 0;
			for (int i = 0; ranks != null && i < labels.length; i++)
			{
				if (ranks[i] > 0)
				{
					width = Math.max(width, 1 + fm.stringWidth(TitleTooltip.rankTailText(ranks[i])));
				}
			}
			return width;
		};
		return part(c -> scoreRight.applyAsInt(c.fm) + progressCol.applyAsInt(c.fm) + rankCol.applyAsInt(c.fm),
			c -> NativeTooltip.LINE_HEIGHT * labels.length, (c, y) ->
			{
				Graphics2D g = c.g;
				FontMetrics fm = c.fm;
				int x = c.inset();
				int right = x + scoreRight.applyAsInt(fm);
				int rankX = right + progressCol.applyAsInt(fm);
				for (int i = 0; i < labels.length; i++)
				{
					int textY = y + fm.getAscent();
					BufferedImage icon = icons != null && i < icons.length ? icons[i] : null;
					if (icon != null)
					{
						g.drawImage(icon, x, y + (NativeTooltip.LINE_HEIGHT - iconSize) / 2, null);
					}
					g.setColor(NativeTooltip.OSRS_ORANGE);
					g.drawString(labels[i], x + iconSize + iconGap, textY);
					g.setColor(Color.WHITE);
					TitleTooltip.drawRightAligned(g, fm, TitleTooltip.scoreText(scores[i]), right, textY);
					if (obtained[i] >= 0)
					{
						TitleTooltip.paintWrappedProgressCount(g, fm, right, textY, obtained[i], total[i]);
					}
					if (ranks != null && ranks[i] > 0)
					{
						TitleTooltip.drawLabelValue(g, fm, rankX + 1, textY, " #", TitleTooltip.grouped(ranks[i]));
					}
					y += NativeTooltip.LINE_HEIGHT;
				}
			});
	}

	/**
	 * Rows a card opens things from. Each paint lays the rows' spans down again; a hovered row repaints
	 * white, and a left press hands its key to the card.
	 */
	static final class ClickRows
	{
		private final JComponent card;
		private final List<int[]> spans = new ArrayList<>();
		private int hovered = -1;
		private int lastY = -1;

		ClickRows(JComponent card, ObjIntConsumer<MouseEvent> onPress)
		{
			this.card = card;
			MouseAdapter mouse = new MouseAdapter()
			{
				@Override
				public void mouseMoved(MouseEvent e)
				{
					lastY = e.getY();
					hover(at(lastY));
				}

				@Override
				public void mousePressed(MouseEvent e)
				{
					int key = at(e.getY());
					if (key >= 0 && e.getButton() == MouseEvent.BUTTON1)
					{
						onPress.accept(e, key);
					}
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					lastY = -1;
					hover(-1);
				}
			};
			card.addMouseMotionListener(mouse);
			card.addMouseListener(mouse);
		}

		void span(int top, int key)
		{
			span(top, NativeTooltip.LINE_HEIGHT, key);
		}

		void span(int top, int height, int key)
		{
			spans.removeIf(s -> s[1] == key);
			spans.add(new int[]{top, key, height});
		}

		/** Forgets every row: a scrolled list lays down only the rows it shows. */
		void clear()
		{
			spans.clear();
		}

		/** Hovers whatever row now sits under the still mouse, as after a list scrolls beneath it. */
		void rehover()
		{
			hover(at(lastY));
		}

		/** The row under a y coordinate, or -1. Rows are full width. */
		int at(int y)
		{
			for (int[] s : spans)
			{
				if (y >= s[0] && y < s[0] + s[2])
				{
					return s[1];
				}
			}
			return -1;
		}

		int hovered()
		{
			return hovered;
		}

		private void hover(int key)
		{
			if (hovered != key)
			{
				hovered = key;
				card.repaint();
			}
		}
	}
}

package com.killclog;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;

/**
 * Reader for the plugin's bundled catalog tables: tab-separated rows, one per
 * line, {@code #} comment lines skipped. Catalog data ships as versioned
 * resources beside the classes that own it, in the same shape as
 * {@code ehb-rates.csv}.
 */
@Slf4j
final class CatalogTsv
{
	private CatalogTsv()
	{
	}

	// Bundled resources are immutable for the plugin's lifetime, and several
	// classes read the same file many times at init.
	private static final Map<String, List<String[]>> CACHE = new ConcurrentHashMap<>();

	/**
	 * Rows with exactly {@code columns} fields. A malformed or blank-keyed row
	 * is logged and skipped rather than failing the load; the catalog-parity
	 * tests pin the complete expected contents at build time.
	 */
	static List<String[]> rows(Class<?> owner, String resource, int columns)
	{
		return CACHE.computeIfAbsent(owner.getName() + '|' + resource + '|' + columns,
			key -> readRows(owner, resource, columns));
	}

	/** Column 1 of the rows whose column 0 equals {@code kind}, in file order. */
	static List<String> values(Class<?> owner, String resource, String kind)
	{
		List<String> values = new ArrayList<>();
		for (String[] row : rows(owner, resource, 2))
		{
			if (kind.equals(row[0]))
			{
				values.add(row[1]);
			}
		}
		return values;
	}

	private static List<String[]> readRows(Class<?> owner, String resource, int columns)
	{
		List<String[]> rows = new ArrayList<>();
		try (InputStream in = owner.getResourceAsStream(resource))
		{
			if (in == null)
			{
				log.warn("catalog resource missing: {}", resource);
				return rows;
			}
			BufferedReader reader = new BufferedReader(
				new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] fields = line.split("\t", -1);
				if (fields.length != columns)
				{
					log.warn("catalog row in {} has {} fields, expected {}: {}",
						resource, fields.length, columns, line);
					continue;
				}
				if (fields[0].trim().isEmpty())
				{
					log.warn("catalog row in {} has a blank key: {}", resource, line);
					continue;
				}
				rows.add(fields);
			}
		}
		catch (IOException e)
		{
			log.warn("catalog resource unreadable: {}", resource, e);
		}
		return Collections.unmodifiableList(rows);
	}
}

