package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemVariationMapping;

/** Maps observed item forms onto unambiguous slots in the live Collection Log catalog. */
final class ClogItemCanonicalizer
{
	private final Map<Integer, Integer> declaredAliases;
	private final Map<Integer, Integer> catalogVariants;

	ClogItemCanonicalizer(Map<String, List<Integer>> categoryItems,
		Map<Integer, Integer> declaredAliases)
	{
		this.declaredAliases = Collections.unmodifiableMap(new HashMap<>(declaredAliases));
		catalogVariants = buildCatalogVariants(categoryItems, declaredAliases);
	}

	int canonicalItemId(int itemId)
	{
		int declared = declaredAliases.getOrDefault(itemId, itemId);
		return catalogVariants.getOrDefault(declared, declared);
	}

	List<ClogResult.ClogItem> canonicalizeItems(List<ClogResult.ClogItem> items)
	{
		Map<Integer, ClogResult.ClogItem> canonical = new LinkedHashMap<>();
		if (items != null)
		{
			for (ClogResult.ClogItem item : items)
			{
				int itemId = canonicalItemId(item.getId());
				ClogResult.ClogItem prior = canonical.get(itemId);
				canonical.put(itemId, prior == null
					? copyItem(item, itemId) : mergeItems(prior, item, itemId));
			}
		}
		return new ArrayList<>(canonical.values());
	}

	int declaredAliasCount()
	{
		return declaredAliases.size();
	}

	int catalogVariantCount()
	{
		return catalogVariants.size();
	}

	private static Map<Integer, Integer> buildCatalogVariants(
		Map<String, List<Integer>> categoryItems, Map<Integer, Integer> declaredAliases)
	{
		Set<Integer> catalogIds = new HashSet<>();
		for (List<Integer> items : categoryItems.values())
		{
			catalogIds.addAll(items);
		}

		Map<Integer, Set<Integer>> candidates = new HashMap<>();
		for (int itemId : catalogIds)
		{
			addCandidates(candidates, itemId, itemId);
		}
		for (Map.Entry<Integer, Integer> alias : declaredAliases.entrySet())
		{
			if (catalogIds.contains(alias.getValue()))
			{
				addCandidates(candidates, alias.getKey(), alias.getValue());
			}
		}

		Map<Integer, Integer> variants = new HashMap<>();
		for (Map.Entry<Integer, Set<Integer>> candidate : candidates.entrySet())
		{
			if (!catalogIds.contains(candidate.getKey())
				&& !declaredAliases.containsKey(candidate.getKey())
				&& candidate.getValue().size() == 1)
			{
				variants.put(candidate.getKey(), candidate.getValue().iterator().next());
			}
		}
		return Collections.unmodifiableMap(variants);
	}

	private static void addCandidates(Map<Integer, Set<Integer>> candidates,
		int sourceItemId, int canonicalItemId)
	{
		for (int variantId : ItemVariationMapping.getVariations(sourceItemId))
		{
			candidates.computeIfAbsent(variantId, ignored -> new HashSet<>())
				.add(canonicalItemId);
		}
	}

	private static ClogResult.ClogItem copyItem(ClogResult.ClogItem item, int itemId)
	{
		return new ClogResult.ClogItem(itemId, item.getCount(), item.getDate(),
			item.getObtainedAtKc(), item.getObtainedFrom());
	}

	private static ClogResult.ClogItem mergeItems(ClogResult.ClogItem prior,
		ClogResult.ClogItem current, int itemId)
	{
		return new ClogResult.ClogItem(itemId, Math.max(prior.getCount(), current.getCount()),
			current.getDate() != null ? current.getDate() : prior.getDate(),
			current.getObtainedAtKc() > 0 ? current.getObtainedAtKc() : prior.getObtainedAtKc(),
			current.getObtainedFrom() != null
				? current.getObtainedFrom() : prior.getObtainedFrom());
	}
}

package com.killclog;

import java.util.function.Consumer;
import javax.inject.Provider;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.util.Text;

final class ClogLookupMenu
{
	// OSRS player right-click menu reserves indexes 4-7 for plugins (4 slots total).
	private static final int FIRST_PLUGIN_PLAYER_SLOT = 4;
	private static final int LAST_PLUGIN_PLAYER_SLOT_EXCLUSIVE = 8;

	// Right-click menu option strings used to filter Kill Clog lookup entries.
	private static final String OPT_ADD_FRIEND = "Add friend";
	private static final String OPT_ADD_IGNORE = "Add ignore";
	private static final String OPT_REMOVE_FRIEND = "Remove friend";
	private static final String OPT_REMOVE_IGNORE = "Remove ignore";
	private static final String OPT_DELETE = "Delete";
	private static final String OPT_MESSAGE = "Message";

	private String menuOption = "Kill Clog";
	private boolean playerMenuSlotWarned;

	void start(KillClogConfig config, Provider<MenuManager> menuManager)
	{
		menuOption = config.menuLabel().getLabel();
		setPlayerMenuItemEnabled(config, menuManager, config.playerMenuLookup());
	}

	void stop(KillClogConfig config, Provider<MenuManager> menuManager)
	{
		setPlayerMenuItemEnabled(config, menuManager, false);
		playerMenuSlotWarned = false;
	}

	void refresh(KillClogConfig config, Provider<MenuManager> menuManager)
	{
		menuManager.get().removePlayerMenuItem(menuOption);
		menuOption = config.menuLabel().getLabel();
		setPlayerMenuItemEnabled(config, menuManager, config.playerMenuLookup());
	}

	void warnIfPlayerMenuSlotUnavailable(Client client, KillClogConfig config,
		KillClogChatNotifier chatNotifier)
	{
		if (playerMenuSlotWarned || !config.playerMenuLookup() || !config.menuOnPlayers())
		{
			return;
		}

		String[] options = client.getPlayerOptions();
		if (options == null || options.length < LAST_PLUGIN_PLAYER_SLOT_EXCLUSIVE)
		{
			return;
		}
		for (int i = FIRST_PLUGIN_PLAYER_SLOT; i < LAST_PLUGIN_PLAYER_SLOT_EXCLUSIVE; i++)
		{
			if (menuOption.equals(options[i]))
			{
				return;
			}
		}

		playerMenuSlotWarned = true;
		chatNotifier.send(ChatNotice.WARNING,
			"Right-click menu is full. Use the side panel or right-click names in chat instead.");
	}

	void addLookupEntry(MenuEntryAdded event, Client client, KillClogConfig config,
		Consumer<String> lookup)
	{
		if (!config.playerMenuLookup())
		{
			return;
		}

		if (event.getType() != MenuAction.CC_OP.getId()
			&& event.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId())
		{
			return;
		}

		int componentId = event.getActionParam1();
		int groupId = WidgetUtil.componentToInterface(componentId);

		if (!isLookupEligible(config, groupId, componentId, event.getOption()))
		{
			return;
		}

		String target = event.getTarget();
		if (target == null)
		{
			return;
		}
		String name = Text.toJagexName(Text.removeTags(target).trim());
		client.getMenu().createMenuEntry(-2)
			.setOption(menuOption)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier())
			.onClick(e -> lookup.accept(name));
	}

	void handlePlayerLookup(MenuOptionClicked event, KillClogConfig config,
		Consumer<String> lookup)
	{
		if (event.getMenuAction() != MenuAction.RUNELITE_PLAYER
			|| !event.getMenuOption().equals(menuOption)
			|| !config.menuOnPlayers())
		{
			return;
		}

		Player player = event.getMenuEntry().getPlayer();
		if (player == null || player.getName() == null)
		{
			return;
		}

		lookup.accept(Text.toJagexName(player.getName()));
	}

	private void setPlayerMenuItemEnabled(KillClogConfig config,
		Provider<MenuManager> menuManager, boolean enabled)
	{
		if (enabled && config.menuOnPlayers())
		{
			menuManager.get().addPlayerMenuItem(menuOption);
		}
		else
		{
			menuManager.get().removePlayerMenuItem(menuOption);
		}
	}

	private boolean isLookupEligible(KillClogConfig config, int groupId, int componentId, String option)
	{
		// Clan player lists live in two different interfaces; match by componentId, not groupId.
		if (componentId == InterfaceID.ClansSidepanel.PLAYERLIST)
		{
			return config.menuOnClanList()
				&& (OPT_ADD_IGNORE.equals(option) || OPT_REMOVE_FRIEND.equals(option));
		}
		if (componentId == InterfaceID.ClansGuestSidepanel.PLAYERLIST)
		{
			return config.menuOnGuestClanList()
				&& (OPT_ADD_IGNORE.equals(option) || OPT_REMOVE_FRIEND.equals(option));
		}
		switch (groupId)
		{
			case InterfaceID.FRIENDS:
				return config.menuOnFriendsList() && OPT_DELETE.equals(option);
			case InterfaceID.IGNORE:
				return config.menuOnIgnoreList() && OPT_DELETE.equals(option);
			case InterfaceID.CHATCHANNEL_CURRENT:
				return config.menuOnChatChannels()
					&& (OPT_ADD_IGNORE.equals(option) || OPT_REMOVE_FRIEND.equals(option));
			case InterfaceID.CHATBOX:
				return config.menuOnChat()
					&& (OPT_ADD_IGNORE.equals(option) || OPT_MESSAGE.equals(option));
			case InterfaceID.PM_CHAT:
				return config.menuOnPrivateMessages()
					&& (OPT_ADD_IGNORE.equals(option) || OPT_MESSAGE.equals(option));
			case InterfaceID.GIM_SIDEPANEL:
				return config.menuOnGroupIronman()
					&& (OPT_ADD_FRIEND.equals(option)
						|| OPT_REMOVE_FRIEND.equals(option)
						|| OPT_REMOVE_IGNORE.equals(option));
			default:
				return false;
		}
	}
}

package com.killclog;

import java.awt.Component;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import lombok.Setter;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Every Collection Log page, reached from the Collection Log card: a tab's row opens the tab's pages in the
 * game's order, and a page opens its popup, each where the summary was. A page that is one panel boss's
 * opens that boss's own popup; any other shows the game's own items for it, held from anywhere in the
 * log. A row's count always comes from the popup it opens. A comparison pairs both players at every step.
 */
final class ClogPages
{
	// Each page's panel bosses, keyed as the game's pages are.
	private static final Map<String, List<HiscoreSkill>> PAGE_BOSSES = new HashMap<>();

	static
	{
		for (HiscoreSkill boss : PanelData.BOSSES)
		{
			PAGE_BOSSES.computeIfAbsent(ClogService.bossToCategory(
				PanelData.NAME_OVERRIDES.getOrDefault(boss.getName(), boss.getName())), k -> new ArrayList<>()).add(boss);
		}
	}

	private final TooltipController tooltipController;
	private final Cells cells;
	private final ComparisonController comparison;
	private final LookupSession lookupSession;
	private final TooltipDataBuilder tooltipDataBuilder;
	private final KillClogConfig config;
	@Setter
	@Nullable
	private ClogIndex clogIndex;

	ClogPages(TooltipController tooltipController, Cells cells, ComparisonController comparison,
		LookupSession lookupSession, TooltipDataBuilder tooltipDataBuilder, KillClogConfig config)
	{
		this.tooltipController = tooltipController;
		this.cells = cells;
		this.comparison = comparison;
		this.lookupSession = lookupSession;
		this.tooltipDataBuilder = tooltipDataBuilder;
		this.config = config;
	}

	/** A tab row's press: the tab's pages replace the Collection Log card it came from. */
	void openTab(JComponent owner, MouseEvent press, String tab)
	{
		pin(owner, press, tabCard(owner, tab));
	}

	JToolTip tabCard(JComponent owner, String tab)
	{
		ClogTabTooltip blue = side(owner, tab, lookupSession.getClogResult(), false);
		if (!comparison.isComparisonMode())
		{
			return blue;
		}
		return comparison.wrapSideBySide(owner, blue, side(owner, tab, comparison.getCompareClogResult(), true));
	}

	/** A page's popup, as its row opens it, leading back to its tab. */
	JToolTip pageCard(JComponent owner, String tab, String key)
	{
		return TitleTooltip.withBack(page(owner, key), "< " + tab, press -> pin(owner, press, tabCard(owner, tab)));
	}

	private JToolTip page(JComponent owner, String key)
	{
		JLabel anchor = anchor(owner);
		String name = name(key);
		HiscoreSkill cell = cell(key, name);
		if (cell != null)
		{
			return cells.buildCellTooltipFor(anchor, cell);
		}
		int rare = rare(key);
		if (rare >= 0)
		{
			return cells.buildRareTooltipFor(anchor, rare);
		}
		List<Integer> items = items(key);
		TooltipData blue = tooltipDataBuilder.buildPageData(name, items, lookupSession.getClogResult());
		TooltipData red = comparison.isComparisonMode()
			? tooltipDataBuilder.buildPageData(name, items, comparison.getCompareClogResult()) : null;
		for (TooltipData data : new TooltipData[]{blue, red})
		{
			if (data != null)
			{
				tooltipDataBuilder.preloadItemImages(data);
			}
		}
		return cells.buildPageTooltip(anchor, name, blue, red);
	}

	/** One player's side of a tab: each page's count from the popup its row opens. */
	private ClogTabTooltip side(JComponent owner, String tab, @Nullable ClogResult clog, boolean red)
	{
		ClogIndex index = clogIndex;
		List<String> keys = index != null ? index.tabPages().getOrDefault(tab, Collections.emptyList())
			: Collections.emptyList();
		String[] names = new String[keys.size()];
		int[] obtained = new int[keys.size()];
		int[] total = new int[keys.size()];
		Set<Integer> slots = new HashSet<>();
		for (int i = 0; i < keys.size(); i++)
		{
			String key = keys.get(i);
			names[i] = name(key);
			Set<Integer> items = distinct(items(key));
			slots.addAll(items);
			HiscoreSkill cell = cell(key, names[i]);
			int rare = rare(key);
			TooltipData data = cell == null && rare < 0 ? tooltipDataBuilder.buildPageData(names[i], items(key), clog)
				: rare >= 0 ? cells.rareData(rare, red)
				: !red ? cells.getTooltipDataMap().get(cell)
				: PanelData.CLUE_CATEGORIES.containsKey(cell) ? comparison.buildCompareClueTierData(cell)
				: comparison.getCompareTooltipData(cell);
			obtained[i] = data != null ? data.obtainedCount : -1;
			total[i] = data != null ? data.totalItems : items.size();
		}
		Map<String, int[]> progress = clog == null || index == null ? Collections.emptyMap()
			: index.tabProgress(clog, ClogHelper.sumClogTotals(clog, index::canonicalItemId));

		ClogTabTooltip card = new ClogTabTooltip();
		card.setComponent(owner);
		card.setTab(tab, progress.get(tab), slots.size());
		// Page names wear the panel's progression colors when its highlighter is on, as the boss list does.
		card.setPages(names, obtained, total, config.completionistHighlighter() ? config : null);
		card.setBack("< Collection Log", press -> pin(owner, press, owner.createToolTip()));
		card.setOnOpenPage((press, page) -> pin(owner, press, pageCard(owner, tab, keys.get(page))));
		return card;
	}

	/**
	 * The panel boss whose popup is this page's: the one boss on the page, or the one the page is named
	 * for (Chambers of Xeric, not its Challenge Mode; The Nightmare, not Phosani's). A page shared by
	 * bosses, like the Dagannoth Kings, has its own popup.
	 */
	@Nullable
	static HiscoreSkill pageBoss(String key, String name)
	{
		List<HiscoreSkill> bosses = PAGE_BOSSES.getOrDefault(key, Collections.emptyList());
		HiscoreSkill boss = bosses.size() == 1 ? bosses.get(0) : null;
		for (HiscoreSkill candidate : bosses)
		{
			if (candidate.getName().replaceFirst("(?i)^the ", "").equalsIgnoreCase(name.replaceFirst("(?i)^the ", "")))
			{
				boss = candidate;
			}
		}
		return boss;
	}

	/**
	 * The panel cell whose card is this page's, while that cell has one: the page's boss, or the clue tier the
	 * page logs. One log keeps one card wherever it opens.
	 */
	@Nullable
	private HiscoreSkill cell(String key, String name)
	{
		HiscoreSkill cell = pageBoss(key, name);
		for (Map.Entry<HiscoreSkill, String> tier : PanelData.CLUE_CATEGORIES.entrySet())
		{
			cell = cell == null && tier.getValue().equals(key) ? tier.getKey() : cell;
		}
		return cell != null && cells.getTooltipDataMap().get(cell) != null ? cell : null;
	}

	/** The Clue Summary rare row this page stands for, while that row has a card; -1 otherwise. */
	private int rare(String key)
	{
		int row = Arrays.asList(PanelData.RARE_PAGES).indexOf(key);
		return row >= 0 && cells.rareData(row, false) != null ? row : -1;
	}

	private String name(String key)
	{
		String name = clogIndex != null ? clogIndex.pageName(key) : null;
		return name != null ? name : key;
	}

	private List<Integer> items(String key)
	{
		List<Integer> items = clogIndex != null ? clogIndex.categoryItems().get(key) : null;
		return items != null ? items : Collections.emptyList();
	}

	private Set<Integer> distinct(List<Integer> items)
	{
		Set<Integer> distinct = new HashSet<>();
		for (int item : items)
		{
			distinct.add(clogIndex != null ? clogIndex.canonicalItemId(item) : item);
		}
		return distinct;
	}

	/** The new card where the summary was: under the same cell, from the same source. */
	private void pin(JComponent owner, MouseEvent press, JToolTip tip)
	{
		tooltipController.pinTooltipFromPress(owner,
			owner instanceof JPanel ? (JPanel) owner : (JPanel) owner.getParent(), press, tip);
	}

	/** The label popups hang from: the summary's own, or the first label of the comparison's totals bar. */
	private static JLabel anchor(JComponent owner)
	{
		if (owner instanceof JLabel)
		{
			return (JLabel) owner;
		}
		for (Component child : owner.getComponents())
		{
			if (child instanceof JLabel)
			{
				return (JLabel) child;
			}
		}
		throw new IllegalStateException("no label to anchor a page popup");
	}
}

package com.killclog;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

final class ClogProviderFanout
{
	private static final long PROVIDER_TIMEOUT_SECONDS = 7;

	private ClogProviderFanout()
	{
	}

	/** Shared by panel and chat; remote-self legs never replace local observations. */
	static CompletableFuture<ClogResult> lookup(boolean isSelf,
		Supplier<CompletableFuture<ClogResult>> temple,
		Supplier<CompletableFuture<ClogResult>> runeProfile,
		Supplier<CompletableFuture<ClogResult>> killclog)
	{
		return chooseFullest(fetch(temple),
			isSelf ? CompletableFuture.completedFuture(null) : fetch(runeProfile),
			isSelf ? CompletableFuture.completedFuture(null) : fetch(killclog));
	}

	private static CompletableFuture<ClogResult> fetch(Supplier<CompletableFuture<ClogResult>> provider)
	{
		try
		{
			return provider.get();
		}
		catch (Exception ex)
		{
			return CompletableFuture.completedFuture(null);
		}
	}

	static CompletableFuture<ClogResult> chooseFreshest(
		CompletableFuture<ClogResult> temple,
		CompletableFuture<ClogResult> runeProfile)
	{
		return chooseFreshest(temple, runeProfile, PROVIDER_TIMEOUT_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * All three legs: the provider pair races on recency as before, then the
	 * player's own killclog.com sync joins on coverage -- fullest leads, ties
	 * prefer first-party ({@link ClogResult#pickFullest}).
	 */
	static CompletableFuture<ClogResult> chooseFullest(
		CompletableFuture<ClogResult> temple,
		CompletableFuture<ClogResult> runeProfile,
		CompletableFuture<ClogResult> killclog)
	{
		return chooseFreshest(temple, runeProfile)
			.thenCombine(
				providerOrNull(killclog, PROVIDER_TIMEOUT_SECONDS, TimeUnit.SECONDS),
				ClogResult::pickFullest);
	}

	static CompletableFuture<ClogResult> chooseFreshest(
		CompletableFuture<ClogResult> temple,
		CompletableFuture<ClogResult> runeProfile,
		long timeout,
		TimeUnit unit)
	{
		return providerOrNull(temple, timeout, unit)
			.thenCombine(providerOrNull(runeProfile, timeout, unit), ClogResult::pickFreshest);
	}

	private static CompletableFuture<ClogResult> providerOrNull(
		CompletableFuture<ClogResult> future,
		long timeout,
		TimeUnit unit)
	{
		return future.copy()
			.completeOnTimeout(null, timeout, unit)
			.exceptionally(ex -> null);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Pure record math for the local store: no state, no I/O. An own log holds
 * only what its account's client captured; a 2.4 file marked which of its
 * records were captured, and only those survive into an own log.
 */
final class ClogRecords
{
	private ClogRecords()
	{
	}

	static boolean hasFirstPartyMarks(PlayerClogData data)
	{
		if (data == null || data.firstPartyByCategory == null)
		{
			return false;
		}
		for (List<Integer> ids : data.firstPartyByCategory.values())
		{
			if (ids != null && !ids.isEmpty())
			{
				return true;
			}
		}
		return false;
	}

	/** Only an explicit completed Collection Log Search counts; marks alone never do. */
	static boolean hasCompletedFirstPartySetup(PlayerClogData data)
	{
		return data != null && Boolean.TRUE.equals(data.firstPartySetupComplete);
	}

	/**
	 * A proven copy's first-party core: an own log as it stands; a 2.4 file
	 * cut to its marked records, each judged in its own category, so a mark
	 * never certifies a record it was not earned on. Pending unlocks keep only
	 * the account's own.
	 */
	static PlayerClogData ownCore(PlayerClogData data, String ownerHash)
	{
		Map<String, List<ClogResult.ClogItem>> kept = new HashMap<>();
		if (data.obtained != null)
		{
			for (Map.Entry<String, List<ClogResult.ClogItem>> e : data.obtained.entrySet())
			{
				List<Integer> marks = data.firstPartyByCategory != null
					? data.firstPartyByCategory.get(e.getKey()) : null;
				List<ClogResult.ClogItem> items = new ArrayList<>();
				for (ClogResult.ClogItem item : e.getValue())
				{
					if (data.firstPartyByCategory == null || marks != null && marks.contains(item.getId()))
					{
						items.add(item);
					}
				}
				if (!items.isEmpty())
				{
					kept.put(e.getKey(), items);
				}
			}
		}
		data.obtained = kept;
		data.categories = data.categories != null ? new HashMap<>(data.categories) : new HashMap<>();
		data.firstPartyByCategory = null;
		data.pendingUnlocks = owned(data.pendingUnlocks, ownerHash);
		data.firstPartySetupComplete = hasCompletedFirstPartySetup(data);
		data.ownerHash = ownerHash;
		return data;
	}

	/**
	 * Two cores of one account become one. Every record is first-party, so the
	 * base wins where both hold an item; anything only the other knows (items,
	 * category ids, pending unlocks) carries over. Nothing is summed.
	 */
	static PlayerClogData mergeOwn(PlayerClogData base, PlayerClogData other)
	{
		for (Map.Entry<String, List<Integer>> e : other.categories.entrySet())
		{
			List<Integer> ids = new ArrayList<>(base.categories.getOrDefault(e.getKey(), new ArrayList<>()));
			for (Integer id : e.getValue())
			{
				if (!ids.contains(id))
				{
					ids.add(id);
				}
			}
			base.categories.put(e.getKey(), ids);
		}
		for (Map.Entry<String, List<ClogResult.ClogItem>> e : other.obtained.entrySet())
		{
			List<ClogResult.ClogItem> items = new ArrayList<>(base.obtained.getOrDefault(e.getKey(), new ArrayList<>()));
			for (ClogResult.ClogItem item : e.getValue())
			{
				if (items.stream().noneMatch(have -> have.getId() == item.getId()))
				{
					items.add(item);
				}
			}
			base.obtained.put(e.getKey(), items);
		}
		List<PendingClogUnlock> pending = base.pendingUnlocks != null ? new ArrayList<>(base.pendingUnlocks) : new ArrayList<>();
		for (PendingClogUnlock event : other.pendingUnlocks != null ? other.pendingUnlocks : new ArrayList<PendingClogUnlock>())
		{
			if (!pending.contains(event))
			{
				pending.add(event);
			}
		}
		while (pending.size() > 32)
		{
			pending.remove(0);
		}
		base.pendingUnlocks = pending.isEmpty() ? null : pending;
		base.uniqueObtained = Math.max(base.uniqueObtained, other.uniqueObtained);
		base.uniqueTotal = Math.max(base.uniqueTotal, other.uniqueTotal);
		if (base.lastChanged == null
			|| (other.lastChanged != null && other.lastChanged.compareTo(base.lastChanged) > 0))
		{
			base.lastChanged = other.lastChanged;
		}
		if (base.providerAccountType == null)
		{
			base.providerAccountType = other.providerAccountType;
		}
		base.firstPartySetupComplete = base.firstPartySetupComplete || other.firstPartySetupComplete;
		return base;
	}

	private static List<PendingClogUnlock> owned(List<PendingClogUnlock> events, String ownerHash)
	{
		if (events == null)
		{
			return null;
		}
		List<PendingClogUnlock> kept = new ArrayList<>();
		for (PendingClogUnlock event : events)
		{
			if (event != null && ownerHash.equals(event.ownerHash) && !kept.contains(event))
			{
				kept.add(event);
			}
		}
		return kept.isEmpty() ? null : kept;
	}
}

package com.killclog;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.Getter;
import lombok.Setter;

/**
 * Parsed collection log data for a player from the active provider.
 */
public class ClogResult
{
	/** Canonical player name with best-known capitalization from the provider */
	@Getter
	private final String playerName;
	/** category key -> list of obtained items with counts */
	@Getter
	private final Map<String, List<ClogItem>> obtainedItems;
	/** category key -> all item IDs in that category */
	@Getter
	private final Map<String, List<Integer>> categoryItems;
	/** item id -> display name, concurrent: written from client thread, read from EDT. */
	private final Map<Integer, String> itemNames;
	/** When the player last synced clog data, or null for providers without it */
	@Getter
	private final String lastChanged;
	/** Account type reported by the active provider, or null if unknown */
	@Getter
	private final AccountType providerAccountType;
	/** Game-reported unique obtained count (varp 2943), or -1 if unavailable */
	@Getter
	@Setter
	private int uniqueObtained = -1;
	/** Game-reported total clog slots (varp 2944), or -1 if unavailable */
	@Getter
	@Setter
	private int uniqueTotal = -1;
	/** True when TempleOSRS returned usable collection-log data for this lookup */
	@Getter
	private boolean fromTemple;
	/** True when RuneProfile returned usable collection-log data for this lookup */
	@Getter
	private boolean fromRuneProfile;
	/** True when the player's own killclog.com sync returned itemized clog data */
	@Getter
	private boolean fromKillclog;
	/** True when the result includes the local player's completed game capture. */
	@Getter
	private boolean fromLocal;

	public ClogResult(
		String playerName,
		Map<String, List<ClogItem>> obtainedItems,
		Map<String, List<Integer>> categoryItems,
		Map<Integer, String> itemNames,
		String lastChanged,
		AccountType providerAccountType)
	{
		this.playerName = playerName;
		this.obtainedItems = obtainedItems;
		this.categoryItems = categoryItems;
		this.itemNames = new ConcurrentHashMap<>();
		if (itemNames != null)
		{
			this.itemNames.putAll(itemNames);
		}
		this.lastChanged = lastChanged;
		this.providerAccountType = providerAccountType;
	}

	/**
	 * Shallow combine copy: shares the item/category maps with the source
	 * (they are read-only after construction, except itemNames, whose shared
	 * concurrent map deliberately keeps the name-resolution cache warm across
	 * lookups). Only identity, account type, and provenance flags are per-copy.
	 */
	private ClogResult(ClogResult source, AccountType accountType)
	{
		this.playerName = source.playerName;
		this.obtainedItems = source.obtainedItems;
		this.categoryItems = source.categoryItems;
		this.itemNames = source.itemNames;
		this.lastChanged = source.lastChanged;
		this.providerAccountType = accountType;
		this.uniqueObtained = source.uniqueObtained;
		this.uniqueTotal = source.uniqueTotal;
		this.fromLocal = source.fromLocal;
	}

	/**
	 * Combine result carrying this data with per-combine provenance. Cached
	 * provider/killclog instances are shared across overlapping lookups whose
	 * legs can resolve differently (timeouts, cancellations), so combines
	 * must NEVER mutate them -- every combine returns its own copy.
	 */
	private ClogResult copyWithProvenance(boolean temple, boolean runeProfile, boolean killclog,
		AccountType fallbackType)
	{
		AccountType accountType = providerAccountType != null ? providerAccountType : fallbackType;
		return copyWithProvenanceAndAccountType(temple, runeProfile, killclog, accountType);
	}

	private ClogResult copyWithProvenanceAndAccountType(boolean temple, boolean runeProfile,
		boolean killclog, AccountType accountType)
	{
		ClogResult copy = new ClogResult(this, accountType);
		copy.fromTemple = temple;
		copy.fromRuneProfile = runeProfile;
		copy.fromKillclog = killclog;
		return copy;
	}

	/**
	 * Stamp a result at the provider boundary without mutating a cached instance.
	 * Fanout combines may receive local fallback data in a provider-shaped slot,
	 * so argument position is never sufficient evidence of provenance.
	 */
	ClogResult withSources(boolean temple, boolean runeProfile, boolean killclog)
	{
		return copyWithProvenanceAndAccountType(
			temple, runeProfile, killclog, providerAccountType);
	}

	ClogResult withLocalSource(boolean local)
	{
		ClogResult copy = withSources(fromTemple, fromRuneProfile, fromKillclog);
		copy.fromLocal = local;
		return copy;
	}

	public boolean isItemResolved(int id)
	{
		return itemNames.containsKey(id);
	}

	public void markItemResolved(int id)
	{
		itemNames.putIfAbsent(id, "Item " + id);
	}

	public void markItemResolved(int id, String name)
	{
		if (name == null || name.isBlank() || "null".equalsIgnoreCase(name))
		{
			return;
		}
		itemNames.put(id, name);
	}

	public String getItemName(int id)
	{
		return itemNames.get(id);
	}

	/**
	 * Compare two clog results and return whichever represents the most
	 * recent sync. Collection log items only accumulate, so the result
	 * with more obtained items is fresher. When counts are close (within 5),
	 * prefer TempleOSRS for its richer sync timestamp.
	 */
	public static ClogResult pickFreshest(ClogResult temple, ClogResult rp)
	{
		ClogResult winner = chooseFreshest(temple, rp);
		if (winner == null)
		{
			return null;
		}
		// Provenance comes from provider-stamped inputs, never argument position:
		// the Temple-shaped leg can legitimately contain unmarked local data.
		ClogResult loser = winner == temple ? rp : temple;
		return winner.copyWithProvenance(sourceTemple(temple, rp),
			sourceRuneProfile(temple, rp), sourceKillclog(temple, rp),
			loser != null ? loser.providerAccountType : null)
			.withLocalSource(sourceLocal(temple, rp));
	}

	/**
	 * Combine the provider winner with the player's own killclog.com sync.
	 * The rule is the website's, not {@link #pickFreshest}'s recency lean:
	 * the FULLEST result leads, and ties prefer first-party. A partial sync
	 * (six items from a fresh install) must never shrink a profile below
	 * what providers prove; a complete sync must never lose to a stale
	 * provider snapshot.
	 */
	public static ClogResult pickFullest(ClogResult provider, ClogResult killclog)
	{
		if (provider == null && killclog == null)
		{
			return null;
		}
		if (killclog == null)
		{
			// Copied even though the composed caller hands us pickFreshest's
			// own copy: this method must be safe on cached instances too.
			return provider.copyWithProvenance(
				provider.fromTemple, provider.fromRuneProfile, provider.fromKillclog, null);
		}
		if (provider == null)
		{
			return killclog.copyWithProvenance(
				killclog.fromTemple, killclog.fromRuneProfile, killclog.fromKillclog, null);
		}
		boolean templeSource = sourceTemple(provider, killclog);
		boolean runeProfileSource = sourceRuneProfile(provider, killclog);
		boolean killclogSource = sourceKillclog(provider, killclog);
		// The coverage race compares the same metric on both sides: distinct
		// itemized coverage. The varp counter describes the ACCOUNT, not the
		// payload - a six-item partial sync still carries the account's full
		// unique count, and letting it race on that number replays the shrink
		// bug against a complete provider log.
		if (coverageCount(killclog) >= coverageCount(provider))
		{
			return killclog.copyWithProvenance(
				templeSource, runeProfileSource, killclogSource,
				provider.providerAccountType).withLocalSource(sourceLocal(provider, killclog));
		}
		AccountType firstPartyType = killclog.providerAccountType;
		AccountType accountType = firstPartyType != null && firstPartyType.isGroupIronman()
			? firstPartyType : provider.providerAccountType;
		return provider.copyWithProvenanceAndAccountType(
			templeSource, runeProfileSource, killclogSource, accountType)
			.withLocalSource(sourceLocal(provider, killclog));
	}

	private static boolean sourceLocal(ClogResult first, ClogResult second)
	{
		return first != null && first.fromLocal || second != null && second.fromLocal;
	}

	private static boolean sourceTemple(ClogResult first, ClogResult second)
	{
		return first != null && first.fromTemple || second != null && second.fromTemple;
	}

	private static boolean sourceRuneProfile(ClogResult first, ClogResult second)
	{
		return first != null && first.fromRuneProfile || second != null && second.fromRuneProfile;
	}

	private static boolean sourceKillclog(ClogResult first, ClogResult second)
	{
		return first != null && first.fromKillclog || second != null && second.fromKillclog;
	}

	/** Distinct itemized coverage, deliberately ignoring the varp counter. */
	static int coverageCount(ClogResult result)
	{
		java.util.Set<Integer> distinct = new java.util.HashSet<>();
		for (List<ClogItem> items : result.obtainedItems.values())
		{
			for (ClogItem item : items)
			{
				distinct.add(item.getId());
			}
		}
		return distinct.size();
	}

	private static ClogResult chooseFreshest(ClogResult temple, ClogResult rp)
	{
		if (temple == null)
		{
			return rp;
		}
		if (rp == null)
		{
			return temple;
		}

		int templeCount = obtainedCount(temple);
		int rpCount = obtainedCount(rp);

		// RuneProfile has significantly more items, so it is clearly fresher.
		if (rpCount > templeCount + 5)
		{
			return rp;
		}
		// TempleOSRS wins ties and near-ties because it has lastChanged.
		return temple;
	}

	private static int obtainedCount(ClogResult result)
	{
		// Distinct ids, not a per-category sum: one item can sit in several
		// categories, and a duplicate-heavy partial result must not outcount
		// a genuinely fuller one.
		return result.uniqueObtained >= 0 ? result.uniqueObtained : coverageCount(result);
	}

	public static class ClogItem
	{
		private final int id;
		private final int count;
		private final String date;
		// Provenance captured at the live unlock moment, when the vanilla
		// kill-count message landed just before the clog message. 0 / null
		// mean unknown: provider data, full log captures, and pre-capture cache
		// files never carry these.
		private final int obtainedAtKc;
		private final String obtainedFrom;

		public ClogItem(int id, int count, String date)
		{
			this(id, count, date, 0, null);
		}

		public ClogItem(int id, int count, String date, int obtainedAtKc, String obtainedFrom)
		{
			this.id = id;
			this.count = count;
			this.date = date;
			this.obtainedAtKc = obtainedAtKc;
			this.obtainedFrom = obtainedFrom;
		}

		public int getId()
		{
			return id;
		}

		public int getCount()
		{
			return count;
		}

		public String getDate()
		{
			return date;
		}

		public int getObtainedAtKc()
		{
			return obtainedAtKc;
		}

		public String getObtainedFrom()
		{
			return obtainedFrom;
		}
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.TreeMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * Fetches the TempleOSRS collection-log provider lane and item names from OSRS Wiki.
 * Category definitions and item names are loaded once per session and reused.
 */
@Slf4j
@Singleton
public class ClogService
{
	private static final String TEMPLE_CATEGORIES_URL =
		"https://templeosrs.com/api/collection-log/categories.php";
	private static final String TEMPLE_PLAYER_URL =
		"https://templeosrs.com/api/collection-log/player_collection_log.php";
	private static final String TEMPLE_STATS_URL =
		"https://templeosrs.com/api/player_stats.php";
	private static final String WIKI_MAPPING_URL =
		"https://prices.runescape.wiki/api/v1/osrs/mapping";

	// Boss name to TempleOSRS category key overrides, from the bundled
	// catalog; the parity test pins its exact contents.
	private static final Map<String, String> BOSS_CATEGORY_OVERRIDES = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
	static
	{
		for (String[] row : CatalogTsv.rows(ClogService.class, "clog-category-overrides.tsv", 2))
		{
			BOSS_CATEGORY_OVERRIDES.put(row[0], row[1]);
		}
	}

	/** Read-only view for catalog-parity tests. */
	/* package */ static Map<String, String> bossCategoryOverrides()
	{
		return Collections.unmodifiableMap(BOSS_CATEGORY_OVERRIDES);
	}

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final LocalClogCache localClogCache;

	// Cached data loaded once per session.
	private volatile Map<String, List<Integer>> cachedCategories;
	private volatile Map<Integer, String> cachedItemNames;

	// In-flight futures prevent duplicate HTTP requests from concurrent callers.
	private final Map<String, CompletableFuture<Map<String, List<Integer>>>> categoriesFlight = new java.util.concurrent.ConcurrentHashMap<>();
	private final Map<String, CompletableFuture<Map<Integer, String>>> namesFlight = new java.util.concurrent.ConcurrentHashMap<>();

	// Failure cooldown skips TempleOSRS briefly after transient errors.
	private static final long TEMPLE_FAILURE_TTL_MS = 3 * 60 * 1000;
	private final Map<String, Long> templeFailures = new java.util.concurrent.ConcurrentHashMap<>();

	// Freshness gate skips TempleOSRS when the cache is still hot.
	private static final long CLOG_TTL_MS = 5 * 60 * 1000; // 5 minutes
	private final Map<String, Long> clogFetchTimes = new java.util.concurrent.ConcurrentHashMap<>();
	// A date-overlay attempt is recorded before HTTP; keep successful Temple
	// proof separately so the active-player result stays attributed during TTL.
	private final Map<String, Long> templeOverlaySuccessTimes =
		new java.util.concurrent.ConcurrentHashMap<>();

	@Inject
	public ClogService(OkHttpClient httpClient, Gson gson, LocalClogCache localClogCache)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.localClogCache = localClogCache;
	}

	/** Clear all failure cooldowns immediately (called on login). TTL handles auto-expiry otherwise. */
	public void clearTempleFailures()
	{
		templeFailures.clear();
	}

	/**
	 * Convert a boss name to its TempleOSRS collection log category key.
	 */
	public static String bossToCategory(String bossName)
	{
		String override = BOSS_CATEGORY_OVERRIDES.get(bossName);
		if (override != null)
		{
			return override;
		}
		return bossName.toLowerCase().replace("'", "")
			.replaceAll("[^a-z0-9]+", "_").replaceAll("^_|_$", "");
	}

	/**
	 * Get a cached ClogResult immediately without any API calls.
	 * Returns null if no local cache exists. Used for SWR rendering.
	 */
	public ClogResult getCachedResult(String playerName)
	{
		if (!localClogCache.hasDataFor(playerName))
		{
			return null;
		}
		if (localClogCache.isActivePlayer(playerName)
			&& !localClogCache.hasCompletedFirstPartySetupFor(playerName))
		{
			return null;
		}
		Map<Integer, String> names = cachedItemNames;
		ClogResult result = localClogCache.toClogResult(playerName, names != null ? names : new HashMap<>());
		if (result != null && localClogCache.isActivePlayer(playerName))
		{
			result = result.withLocalSource(true);
			Long successfulAt = templeOverlaySuccessTimes.get(playerName.toLowerCase());
			if (successfulAt != null && System.currentTimeMillis() - successfulAt < CLOG_TTL_MS)
			{
				result = markTempleSource(result);
			}
		}
		return result;
	}

	/** A League's own local log for the active player, once item names have loaded. */
	CompletableFuture<ClogResult> lookupLocal(LocalClogCache cache, String playerName)
	{
		return fetchItemNames().thenApply(names -> localResult(cache, playerName));
	}

	/** A League's own local log for the active player, now. League logs never take provider data. */
	@Nullable
	ClogResult localResult(LocalClogCache cache, String playerName)
	{
		if (!cache.isActivePlayer(playerName) || !cache.hasDataFor(playerName))
		{
			return null;
		}
		Map<Integer, String> names = cachedItemNames;
		ClogResult result = cache.toClogResult(playerName, names != null ? names : new HashMap<>());
		return result != null ? result.withLocalSource(true) : null;
	}

	/**
	 * Look up this service's TempleOSRS collection-log lane for a player.
	 * Active player with widget-read data is served from cache (authoritative).
	 * Public lookup orchestration races this with RuneProfile and picks the fresher result.
	 */
	public CompletableFuture<ClogResult> lookup(String playerName)
	{
		// Active player: local cache is authoritative.
		if (localClogCache.isActivePlayer(playerName))
		{
			if (localClogCache.hasDataFor(playerName)
				&& localClogCache.hasCompletedFirstPartySetupFor(playerName))
			{
				log.debug("Using local clog cache for active player: {}", playerName);
				// Dates-only provider overlay before serving: heals undated
				// cache entries (pre-dating live merges, or unlocks while the
				// plugin was off) so the recents shelf stays current. TTL-gated
				// and failure-proof; counts and membership stay chalice-owned.
				return overlayProviderDates(playerName)
					.thenCompose(fromTemple -> fetchItemNames().thenApply(names ->
					{
						ClogResult result = localClogCache.toClogResult(playerName,
							names != null ? names : new HashMap<>());
						if (result != null)
						{
							result = result.withLocalSource(true);
						}
						return fromTemple ? markTempleSource(result) : result;
					}));
			}
			// No local cache yet, so the panel shows the sync prompt.
			return CompletableFuture.completedFuture(null);
		}

		// Fresh data: skip the TempleOSRS lane if we fetched recently.
		String normalizedName = playerName.toLowerCase();
		Long lastFetch = clogFetchTimes.get(normalizedName);
		if (lastFetch != null && System.currentTimeMillis() - lastFetch < CLOG_TTL_MS
			&& localClogCache.hasDataFor(playerName))
		{
			log.debug("Using fresh cached clog for '{}' ({}s old)",
				playerName, (System.currentTimeMillis() - lastFetch) / 1000);
			return fetchItemNames().thenApply(names -> markTempleSource(
				localClogCache.toClogResult(playerName, names != null ? names : new HashMap<>())));
		}

		// Skip TempleOSRS if it failed for this player within the cooldown window.
		Long failedAt = templeFailures.get(normalizedName);
		if (failedAt != null && System.currentTimeMillis() - failedAt < TEMPLE_FAILURE_TTL_MS)
		{
			if (localClogCache.hasDataFor(playerName))
			{
				return fetchItemNames().thenApply(names ->
					localClogCache.toClogResult(playerName, names != null ? names : new HashMap<>()));
			}
			return CompletableFuture.completedFuture(null);
		}

		// Build the TempleOSRS lane, with local cache as fallback.
		String encoded = URLEncoder.encode(playerName, StandardCharsets.UTF_8);

		CompletableFuture<PlayerClogData> playerFuture =
			fetchClog(encoded);
		CompletableFuture<Map<String, List<Integer>>> categoriesFuture =
			fetchCategories();
		CompletableFuture<Map<Integer, String>> namesFuture =
			fetchItemNames();
		CompletableFuture<AccountType> statsFuture =
			fetchStatsAccountType(encoded);

		return CompletableFuture.allOf(playerFuture, categoriesFuture, namesFuture, statsFuture)
			.thenApply(v ->
			{
				PlayerClogData playerData = playerFuture.join();
				Map<String, List<Integer>> categories = categoriesFuture.join();
				Map<Integer, String> names = namesFuture.join();
				AccountType statsType = statsFuture.join();

				if (playerData != null)
				{
					// Clog endpoint returns game_mode 0 for GIMs.
					// Prefer stats endpoint when clog has no useful type.
					AccountType accountType = playerData.accountType;
					if (statsType != null
						&& (accountType == null || accountType == AccountType.REGULAR))
					{
						accountType = statsType;
					}

					ClogResult result = new ClogResult(
						playerData.canonicalName,
						playerData.obtainedItems,
						categories != null ? categories : new HashMap<>(),
						names != null ? names : new HashMap<>(),
						playerData.lastChanged,
						accountType
					).withSources(true, false, false);
					localClogCache.cacheResult(result);
					clogFetchTimes.put(normalizedName, System.currentTimeMillis());
					HttpUtil.prune(clogFetchTimes, CLOG_TTL_MS);
					return result;
				}

				// TempleOSRS lane failed. Remember timestamp and fall back to local cache.
				templeFailures.put(normalizedName, System.currentTimeMillis());
				HttpUtil.prune(templeFailures, TEMPLE_FAILURE_TTL_MS);
				if (localClogCache.hasDataFor(playerName))
				{
					log.debug("TempleOSRS unavailable, using cached data for: {}", playerName);
					return localClogCache.toClogResult(playerName, names != null ? names : new HashMap<>());
				}

				return null;
			});
	}

	private static ClogResult markTempleSource(ClogResult result)
	{
		return result != null ? result.withSources(true, false, false) : null;
	}

	private static class PlayerClogData
	{
		final String canonicalName;
		final Map<String, List<ClogResult.ClogItem>> obtainedItems;
		final String lastChanged;
		final AccountType accountType;

		PlayerClogData(String canonicalName, Map<String, List<ClogResult.ClogItem>> obtainedItems,
			String lastChanged, AccountType accountType)
		{
			this.canonicalName = canonicalName;
			this.obtainedItems = obtainedItems;
			this.lastChanged = lastChanged;
			this.accountType = accountType;
		}
	}

	/**
	 * Parse TempleOSRS game_mode into our AccountType.
	 * Returns null if the mode is unrecognized or absent.
	 */
	private static AccountType parseGameMode(String gameMode)
	{
		return AccountType.fromTempleGameMode(gameMode);
	}

	/**
	 * Fetch the provider's dated view of the active player and stamp missing
	 * dates onto the local cache. Shares the clog TTL so a self-search never
	 * fans out. The return value records a usable Temple collection-log
	 * response, even when its dates were already present locally; failures and
	 * Temple's unsynced shape resolve false so local data remains unmarked.
	 */
	private CompletableFuture<Boolean> overlayProviderDates(String playerName)
	{
		String normalizedName = playerName.toLowerCase();
		String ttlKey = "dates:" + normalizedName;
		long now = System.currentTimeMillis();
		Long lastFetch = clogFetchTimes.get(ttlKey);
		if (lastFetch != null && now - lastFetch < CLOG_TTL_MS)
		{
			Long successfulAt = templeOverlaySuccessTimes.get(normalizedName);
			return CompletableFuture.completedFuture(successfulAt != null
				&& now - successfulAt < CLOG_TTL_MS);
		}
		clogFetchTimes.put(ttlKey, now);
		HttpUtil.prune(clogFetchTimes, CLOG_TTL_MS);
		String encoded = URLEncoder.encode(playerName, StandardCharsets.UTF_8);
		return fetchClog(encoded)
			.thenApply(player ->
			{
				if (player == null)
				{
					templeOverlaySuccessTimes.remove(normalizedName);
					return false;
				}
				if (player.obtainedItems != null)
				{
					localClogCache.mergeProviderDates(playerName, player.obtainedItems);
				}
				templeOverlaySuccessTimes.put(normalizedName, System.currentTimeMillis());
				HttpUtil.prune(templeOverlaySuccessTimes, CLOG_TTL_MS);
				return true;
			})
			.exceptionally(t ->
			{
				templeOverlaySuccessTimes.remove(normalizedName);
				log.debug("Provider date overlay failed for '{}'", playerName, t);
				return false;
			});
	}

	private CompletableFuture<PlayerClogData> fetchClog(String encodedPlayer)
	{
		String url = TEMPLE_PLAYER_URL + "?player=" + encodedPlayer + "&categories=all";
		return httpGet(url).thenApply(json ->
		{
			if (json == null)
			{
				return null;
			}
			try
			{
				JsonObject root = gson.fromJson(json, JsonObject.class);
				JsonObject data = root.getAsJsonObject("data");
				if (data == null || !data.has("items"))
				{
					return null;
				}

				String canonicalName = null;
				if (data.has("player_name_with_capitalization"))
				{
					canonicalName = data.get("player_name_with_capitalization").getAsString();
				}

				String lastChanged = null;
				if (data.has("last_changed"))
				{
					lastChanged = data.get("last_changed").getAsString();
				}

				AccountType accountType = null;
				if (data.has("game_mode") && !data.get("game_mode").isJsonNull())
				{
					accountType = parseGameMode(data.get("game_mode").getAsString());
				}

				JsonObject itemsObj = data.getAsJsonObject("items");
				Map<String, List<ClogResult.ClogItem>> result = new HashMap<>();

				for (Map.Entry<String, JsonElement> entry : itemsObj.entrySet())
				{
					String category = entry.getKey();
					JsonArray items = entry.getValue().getAsJsonArray();
					List<ClogResult.ClogItem> itemList = new ArrayList<>();

					for (JsonElement item : items)
					{
						JsonObject obj = item.getAsJsonObject();
						int id = obj.get("id").getAsInt();
						int count = obj.has("count") ? obj.get("count").getAsInt() : 1;
						String date = obj.has("date") ? obj.get("date").getAsString() : null;
						itemList.add(new ClogResult.ClogItem(id, count, date));
					}

					result.put(category, itemList);
				}

				// A player TempleOSRS tracks from hiscores but who never synced a
				// collection log returns zero obtained items and no last_changed.
				// Treat that as no clog data, not a real 0% profile: return null so
				// the provider fanout can fall back to RuneProfile, and the panel
				// shows the unknown state instead of painting every boss as empty.
				int obtainedTotal = 0;
				for (List<ClogResult.ClogItem> categoryItems : result.values())
				{
					obtainedTotal += categoryItems.size();
				}
				if (obtainedTotal == 0 && lastChanged == null)
				{
					return null;
				}

				return new PlayerClogData(canonicalName, result, lastChanged, accountType);
			}
			catch (Exception e)
			{
				log.debug("Failed to parse player clog: {}", e.getMessage());
				return null;
			}
		});
	}

	/** True once the global category catalog has loaded. */
	public boolean hasCatalog()
	{
		return cachedCategories != null;
	}

	/** Every category key in the loaded catalog, or empty when it hasn't loaded. */
	public java.util.Set<String> getCatalogCategoryKeys()
	{
		Map<String, List<Integer>> cats = cachedCategories;
		return cats != null ? new java.util.HashSet<>(cats.keySet()) : java.util.Collections.emptySet();
	}

	/**
	 * Canonical item ids for a category from the cached global definitions,
	 * or null when the catalog hasn't loaded or the category is unknown.
	 * Returns a defensive copy.
	 */
	@Nullable
	public List<Integer> getCategoryCatalogIds(String category)
	{
		Map<String, List<Integer>> cats = cachedCategories;
		if (cats == null)
		{
			return null;
		}
		List<Integer> items = cats.get(category);
		return items != null ? new ArrayList<>(items) : null;
	}

	/**
	 * Prefetch the category and item-name catalog so the panel can preview
	 * the log's shape before any player has been looked up.
	 */
	public CompletableFuture<Void> warmCatalog()
	{
		return CompletableFuture.allOf(fetchCategories(), fetchItemNames());
	}

	@Nullable
	public ClogResult getCatalogResult(String playerName)
	{
		Map<String, List<Integer>> cats = cachedCategories;
		if (cats == null)
		{
			return null;
		}

		Map<String, List<Integer>> categories = new HashMap<>();
		Map<String, List<ClogResult.ClogItem>> obtained = new HashMap<>();
		for (Map.Entry<String, List<Integer>> entry : cats.entrySet())
		{
			categories.put(entry.getKey(), new ArrayList<>(entry.getValue()));
			obtained.put(entry.getKey(), Collections.emptyList());
		}

		Map<Integer, String> names = cachedItemNames != null
			? new HashMap<>(cachedItemNames) : new HashMap<>();
		return new ClogResult(playerName, obtained, categories, names, null, null);
	}

	private CompletableFuture<Map<String, List<Integer>>> fetchCategories()
	{
		// Rechecked inside the flight so a fetch that just landed is never repeated.
		return cachedCategories != null ? CompletableFuture.completedFuture(cachedCategories)
			: HttpUtil.singleFlightLookup(categoriesFlight, "", () -> cachedCategories != null
			? CompletableFuture.completedFuture(cachedCategories) : httpGet(TEMPLE_CATEGORIES_URL).thenApply(json ->
			{
				try
				{
					if (json == null)
					{
						return null;
					}
					JsonObject root = gson.fromJson(json, JsonObject.class);
					Type type = new TypeToken<Map<String, List<Integer>>>()
				{
				}.getType();
					Map<String, List<Integer>> categories = new HashMap<>();
					for (Map.Entry<String, JsonElement> entry : root.entrySet())
					{
						if (!entry.getValue().isJsonObject())
						{
							continue;
						}
						Map<String, List<Integer>> sectionMap = gson.fromJson(entry.getValue(), type);
						if (sectionMap != null)
						{
							categories.putAll(sectionMap);
						}
					}
					if (categories.isEmpty())
					{
						return null;
					}
					cachedCategories = categories;
					return categories;
				}
				catch (Exception e)
				{
					log.debug("Failed to parse clog categories: {}", e.getMessage());
					return null;
				}
			}));
	}

	private CompletableFuture<Map<Integer, String>> fetchItemNames()
	{
		return cachedItemNames != null ? CompletableFuture.completedFuture(cachedItemNames)
			: HttpUtil.singleFlightLookup(namesFlight, "", () -> cachedItemNames != null
			? CompletableFuture.completedFuture(cachedItemNames) : httpGet(WIKI_MAPPING_URL).thenApply(json ->
			{
				try
				{
					if (json == null)
					{
						return null;
					}
					JsonArray arr = gson.fromJson(json, JsonArray.class);
					Map<Integer, String> names = new HashMap<>();

					for (JsonElement elem : arr)
					{
						JsonObject obj = elem.getAsJsonObject();
						if (obj.has("id") && obj.has("name"))
						{
							names.put(obj.get("id").getAsInt(), obj.get("name").getAsString());
						}
					}

					cachedItemNames = names;
					return names;
				}
				catch (Exception e)
				{
					log.debug("Failed to parse item names: {}", e.getMessage());
					return null;
				}
			}));
	}

	/**
	 * Fetch account type from the TempleOSRS stats endpoint.
	 * The clog endpoint reports game_mode 0 for GIMs, but the stats
	 * endpoint exposes a GIM field with the group ID.
	 */
	private CompletableFuture<AccountType> fetchStatsAccountType(String encodedPlayer)
	{
		String url = TEMPLE_STATS_URL + "?player=" + encodedPlayer;
		return httpGet(url).thenApply(json ->
		{
			if (json == null)
			{
				return null;
			}
			try
			{
				JsonObject root = gson.fromJson(json, JsonObject.class);
				JsonObject data = root.getAsJsonObject("data");
				if (data == null)
				{
					return null;
				}
				JsonObject info = data.getAsJsonObject("info");
				if (info == null)
				{
					return null;
				}

				if (info.has("Game mode") && !info.get("Game mode").isJsonNull())
				{
					AccountType type = parseGameMode(info.get("Game mode").getAsString());
					if (type != null && type != AccountType.REGULAR)
					{
						return type;
					}
				}

				if (info.has("GIM") && !info.get("GIM").isJsonNull())
				{
					int gimId = info.get("GIM").getAsInt();
					if (gimId > 0)
					{
						return AccountType.GROUP_IRONMAN;
					}
				}

				return null;
			}
			catch (Exception e)
			{
				log.debug("Failed to parse stats account type: {}", e.getMessage());
				return null;
			}
		});
	}

	/**
	 * Fetch only the canonical player name from TempleOSRS player stats.
	 * Lightweight identity fallback when collection-log data is unavailable.
	 */
	public CompletableFuture<String> lookupRsn(String playerName)
	{
		String encoded = URLEncoder.encode(playerName, StandardCharsets.UTF_8);
		String url = TEMPLE_STATS_URL + "?player=" + encoded;
		return httpGet(url).thenApply(json ->
		{
			if (json == null)
			{
				return null;
			}
			try
			{
				JsonObject root = gson.fromJson(json, JsonObject.class);
				JsonObject data = root.getAsJsonObject("data");
				if (data == null)
				{
					return null;
				}
				JsonObject info = data.getAsJsonObject("info");
				if (info != null && info.has("player_name_with_capitalization"))
				{
					return info.get("player_name_with_capitalization").getAsString();
				}
				return null;
			}
			catch (Exception e)
			{
				log.debug("Failed to parse canonical name: {}", e.getMessage());
				return null;
			}
		});
	}

	private CompletableFuture<String> httpGet(String url)
	{
		return HttpUtil.httpGet(httpClient, url).thenApply(r -> r.body);
	}
}

