package com.killclog;

import java.util.EnumMap;
import java.util.Map;

/**
 * Combat Achievement tiers and their Combat Summary reward sprites.
 *
 * <p>Easy through Master unlock by points. Grandmaster requires every task in
 * every tier to be complete. Thresholds are never stored: each tier's
 * threshold is the total points of all tasks in it and below, so they derive
 * from task counts. The task counts here are a fallback snapshot for cold
 * starts; {@link CaCatalog} supplies the live counts from the running game
 * build, which is what keeps tier math honest across a Combat Achievement
 * release.
 */
enum CombatAchievementTier
{
	EASY(1, 41),
	MEDIUM(2, 60),
	HARD(3, 86),
	ELITE(4, 164),
	MASTER(5, 174),
	GRANDMASTER(6, 121);

	private final int pointsPerTask;
	private final int totalTasks;

	CombatAchievementTier(int pointsPerTask, int totalTasks)
	{
		this.pointsPerTask = pointsPerTask;
		this.totalTasks = totalTasks;
	}

	int pointsPerTask()
	{
		return pointsPerTask;
	}

	int totalTasks()
	{
		return totalTasks;
	}

	/** The Combat Summary reward sprite for this tier. */
	CombatAchievementReward reward()
	{
		switch (this)
		{
			case EASY:
				return CombatAchievementReward.EASY;
			case MEDIUM:
				return CombatAchievementReward.MEDIUM;
			case HARD:
				return CombatAchievementReward.HARD;
			case ELITE:
				return CombatAchievementReward.ELITE;
			case MASTER:
				return CombatAchievementReward.MASTER;
			case GRANDMASTER:
				return CombatAchievementReward.GRANDMASTER;
			default:
				throw new AssertionError("Unhandled tier: " + this);
		}
	}

	/** Match a RuneProfile tier row name. */
	static CombatAchievementTier fromName(String name)
	{
		if (name == null)
		{
			return null;
		}
		for (CombatAchievementTier tier : values())
		{
			if (tier.name().equalsIgnoreCase(name))
			{
				return tier;
			}
		}
		return null;
	}

	/** Highest points-unlocked tier against the fallback task counts. */
	static CombatAchievementTier highestForPoints(int totalPoints)
	{
		return highestForPoints(totalPoints, fallbackTotals());
	}

	/**
	 * Highest points-unlocked tier against the given task counts, with each
	 * threshold derived as the cumulative points of that tier and below.
	 * Grandmaster is completion-gated and never returned here.
	 */
	static CombatAchievementTier highestForPoints(int totalPoints,
		Map<CombatAchievementTier, Integer> totals)
	{
		CombatAchievementTier unlocked = null;
		int threshold = 0;
		for (CombatAchievementTier tier : values())
		{
			if (tier == GRANDMASTER)
			{
				continue;
			}
			threshold += totals.getOrDefault(tier, tier.totalTasks) * tier.pointsPerTask;
			if (totalPoints >= threshold)
			{
				unlocked = tier;
			}
		}
		return unlocked;
	}

	/** The fallback task counts as a map, for callers that merge with live data. */
	static Map<CombatAchievementTier, Integer> fallbackTotals()
	{
		Map<CombatAchievementTier, Integer> totals = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : values())
		{
			totals.put(tier, tier.totalTasks);
		}
		return totals;
	}
}

package com.killclog;

import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.BooleanSupplier;
import java.util.function.Function;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import net.runelite.client.ui.FontManager;

final class CompareClogTotalsBar
{
	private final BooleanSupplier comparisonMode;
	private final TooltipController tooltipController;
	private final Function<JComponent, JToolTip> tooltipFactory;
	private final JPanel panel;
	private final JLabel blueTotal;
	private final JLabel redTotal;

	CompareClogTotalsBar(BooleanSupplier comparisonMode, TooltipController tooltipController,
		Function<JComponent, JToolTip> tooltipFactory)
	{
		this.comparisonMode = comparisonMode;
		this.tooltipController = tooltipController;
		this.tooltipFactory = tooltipFactory;
		this.panel = buildPanel();
		this.blueTotal = buildTotalLabel(JLabel.LEFT);
		this.redTotal = buildTotalLabel(JLabel.RIGHT);
		wireClickAndHover();
		layoutLabels();
	}

	JPanel component()
	{
		return panel;
	}

	void setVisible(boolean visible)
	{
		panel.setVisible(visible);
	}

	void update(int[] blueClog, int[] redClog, PanelIconCache iconCache)
	{
		setTotal(blueTotal, blueClog, iconCache);
		setTotal(redTotal, redClog, iconCache);
		panel.setVisible(true);
		panel.revalidate();
	}

	private JPanel buildPanel()
	{
		JPanel totalsPanel = new JPanel(new GridBagLayout())
		{
			@Override
			public JToolTip createToolTip()
			{
				if (!comparisonMode.getAsBoolean())
				{
					return super.createToolTip();
				}
				return tooltipFactory.apply(this);
			}
		};
		totalsPanel.setOpaque(false);
		totalsPanel.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		totalsPanel.setVisible(false);
		totalsPanel.setToolTipText(" ");
		return totalsPanel;
	}

	private JLabel buildTotalLabel(int alignment)
	{
		JLabel label = new HoverLabel()
		{
			@Override
			public JToolTip createToolTip()
			{
				if (!comparisonMode.getAsBoolean())
				{
					return super.createToolTip();
				}
				return tooltipFactory.apply(panel);
			}
		};
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setHorizontalAlignment(alignment);
		label.setIconTextGap(3);
		label.setToolTipText(" ");
		ClogHelper.antialias(label);
		return label;
	}

	private void wireClickAndHover()
	{
		blueTotal.setForeground(ComparisonController.COMPARE_BLUE);
		redTotal.setForeground(ComparisonController.COMPARE_RED);
		tooltipController.trackTooltipComponent(panel);
		tooltipController.trackTooltipComponent(blueTotal);
		tooltipController.trackTooltipComponent(redTotal);

		MouseAdapter clickHandler = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (panel.getToolTipText() != null)
				{
					tooltipController.pinTooltipFromPress(panel, panel, e);
				}
			}
		};
		panel.addMouseListener(clickHandler);
		blueTotal.addMouseListener(clickHandler);
		redTotal.addMouseListener(clickHandler);
		HoverLabel.installHover(blueTotal,
			() -> blueTotal.getToolTipText() != null || comparisonMode.getAsBoolean());
		HoverLabel.installHover(redTotal,
			() -> redTotal.getToolTipText() != null || comparisonMode.getAsBoolean());
	}

	private void layoutLabels()
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridy = 0;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.gridx = 0;
		c.weightx = 1.0;
		c.anchor = GridBagConstraints.WEST;
		panel.add(blueTotal, c);
		c.gridx = 1;
		c.anchor = GridBagConstraints.EAST;
		panel.add(redTotal, c);
	}

	private static void setTotal(JLabel label, int[] totals, PanelIconCache iconCache)
	{
		if (totals[0] < 0)
		{
			label.setIcon(null);
			label.setText("--");
			return;
		}
		String tierName = totals[1] > 0 ? ClogHelper.getClogTierName(totals[0], totals[1]) : null;
		ImageIcon icon = iconCache.clogTierIcon(tierName);
		label.setIcon(icon);
		label.setText(String.valueOf(totals[0]));
	}
}

