	// Pure helpers

	/**
	 * Wrap the two players' single tooltips into one side-by-side comparison
	 * card, named and colored per player.
	 */
	public JToolTip wrapSideBySide(JComponent owner, JToolTip blueTip, JToolTip redTip)
	{
		TitleTooltip.scrollTogether(blueTip, redTip);
		String blueName = blueNameSupplier.get();
		if (blueName == null || blueName.trim().isEmpty())
		{
			blueName = renderTarget != null ? renderTarget.playerName().getText().trim() : "";
		}
		if (blueName.isEmpty())
		{
			blueName = "Blue";
		}
		String redName = compared.rsn != null ? compared.rsn : "Red";
		SideBySideTooltip tip = new SideBySideTooltip(blueName, blueTip, redName, redTip);
		if (renderTarget != null)
		{
			// Reuse displayed account identity, never the selected rank leaderboard.
			tip.setAccountBadges(renderTarget.playerName().getIcon(), renderTarget.clogInfoLabel().getIcon());
		}
		tip.setComponent(owner);
		return tip;
	}

	@Nullable
	public TooltipData buildClueRare(String name, String clogCategory)
	{
		ClogResult clog = getCompareClogResult();
		TooltipData data = clog != null
			? tooltipDataBuilder.buildClueRareData(name, clogCategory, clog) : null;
		return data != null ? data : unsyncedClueRare(name, clogCategory);
	}

	@Nullable
	public TooltipData buildCustomRare(String name, int[] itemIds)
	{
		ClogResult clog = getCompareClogResult();
		TooltipData data = clog != null
			? tooltipDataBuilder.buildCustomRareData(name, itemIds, clog) : null;
		return data != null ? data
			: tooltipDataBuilder.buildUnsyncedItemData(name, itemIds, unsyncedCatalog.result());
	}

	@Nullable
	private TooltipData unsyncedClueRare(String name, String clogCategory)
	{
		ClogResult catalog = unsyncedCatalog.result();
		TooltipData data = tooltipDataBuilder.buildUnsyncedTooltipData(
			name, clogCategory, -1, null, -1, catalog);
		if (data != null)
		{
			return data;
		}
		if (PanelData.CLOG_THIRD_AGE.equals(clogCategory))
		{
			return tooltipDataBuilder.buildUnsyncedItemData(name, PanelData.THIRD_AGE_ITEMS, catalog);
		}
		if (PanelData.CLOG_GILDED.equals(clogCategory))
		{
			return tooltipDataBuilder.buildUnsyncedItemData(name, PanelData.GILDED_ITEMS, catalog);
		}
		return null;
	}

	/** Set a cell to dual blue/red values, with optional completion-color hover state. */
	public void setCompareCell(JLabel label, int blueVal, int redVal,
		@Nullable Color blueHover, @Nullable Color redHover)
	{
		String blueText = blueVal > 0 ? ClogHelper.formatKc(blueVal) : "--";
		String redText = redVal > 0 ? ClogHelper.formatKc(redVal) : "--";
		label.putClientProperty(COMPARE_BLUE_TEXT_KEY, blueText);
		label.putClientProperty(COMPARE_RED_TEXT_KEY, redText);
		label.putClientProperty(COMPARE_BLUE_HOVER_KEY, blueHover != null ? colorHex(blueHover) : null);
		label.putClientProperty(COMPARE_RED_HOVER_KEY, redHover != null ? colorHex(redHover) : null);
		renderCompareCell(label, false);
		label.setForeground(null);
		label.setHorizontalAlignment(JLabel.CENTER);
	}

	/** Drop a cell's comparison state without repainting; caller renders solo. */
	public void clearCompareCell(JLabel label)
	{
		label.putClientProperty(COMPARE_BLUE_TEXT_KEY, null);
		label.putClientProperty(COMPARE_RED_TEXT_KEY, null);
		label.putClientProperty(COMPARE_BLUE_HOVER_KEY, null);
		label.putClientProperty(COMPARE_RED_HOVER_KEY, null);
	}

	/**
	 * Wire the hover listeners that swap a comparison cell's blue/red values to
	 * each player's completion colors while hovered. Shared by every dual-value
	 * cell: bosses, activities, and skills.
	 */
	public void installCompareCellHover(JPanel cell, JLabel label)
	{
		MouseAdapter compareHover = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				setCompareCellHover(label, true);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (!isInsideCell(cell, e))
				{
					setCompareCellHover(label, false);
				}
			}
		};

		cell.addMouseListener(compareHover);
		label.addMouseListener(compareHover);
	}

	private static boolean isInsideCell(JPanel cell, MouseEvent e)
	{
		Object source = e.getSource();
		if (!(source instanceof Component))
		{
			return false;
		}
		Point p = SwingUtilities.convertPoint((Component) source, e.getPoint(), cell);
		return p.x >= 0 && p.y >= 0 && p.x < cell.getWidth() && p.y < cell.getHeight();
	}

	/** Apply or clear the hover-only completion colors for a comparison cell. */
	public void setCompareCellHover(JLabel label, boolean hovering)
	{
		if (label != null && label.getClientProperty(COMPARE_BLUE_TEXT_KEY) instanceof String)
		{
			renderCompareCell(label, hovering);
		}
	}

	private void renderCompareCell(JLabel label, boolean hovering)
	{
		String blueText = String.valueOf(label.getClientProperty(COMPARE_BLUE_TEXT_KEY));
		String redText = String.valueOf(label.getClientProperty(COMPARE_RED_TEXT_KEY));
		String blueColor = hovering ? (String) label.getClientProperty(COMPARE_BLUE_HOVER_KEY) : null;
		String redColor = hovering ? (String) label.getClientProperty(COMPARE_RED_HOVER_KEY) : null;
		if (blueColor == null)
		{
			blueColor = COMPARE_BLUE_HEX;
		}
		if (redColor == null)
		{
			redColor = COMPARE_RED_HEX;
		}
		label.setText("<html><div style='text-align:center;'>"
			+ "<span style='color:" + blueColor + ";'>" + blueText + "</span><br>"
			+ "<span style='color:" + redColor + ";'>" + redText + "</span>"
			+ "</div></html>");
	}

	/** Restore a cell to single-player solo display. */
	public void restoreSoloCell(JLabel label, int val)
	{
		clearCompareCell(label);
		label.setHorizontalAlignment(JLabel.LEADING);
		Color infoColor = renderTarget != null ? renderTarget.getInfoColor()
			: ColorScheme.LIGHT_GRAY_COLOR;
		if (val > 0)
		{
			label.setText(ClogHelper.pad(ClogHelper.formatKc(val)));
			label.setForeground(infoColor);
		}
		else
		{
			label.setText(ClogHelper.pad("--"));
			label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		}
	}

	/**
	 * Render comparison identity in the summary bar, or restore single-player
	 * display when comparison mode is off.
	 */
	public void updateInfoBar()
	{
		if (renderTarget == null)
		{
			return;
		}
		JLabel playerName = renderTarget.playerName();
		JLabel clogInfoLabel = renderTarget.clogInfoLabel();
		if (comparisonMode)
		{
			playerName.setForeground(COMPARE_BLUE);
			tooltipController.setTooltipText(playerName, " ");
			clogInfoLabel.setText(compared.rsn != null ? compared.rsn : "");
			clogInfoLabel.setForeground(COMPARE_RED);
			tooltipController.setTooltipText(clogInfoLabel, " ");
			clogInfoLabel.setIcon(null);
			clogInfoLabel.setHorizontalAlignment(JLabel.RIGHT);
			// The primary name keeps the identity the panel resolved, RuneLite's own type included.
			AccountDisplay blue = renderTarget.primaryIdentity();
			renderTarget.applyBadge(playerName, blue != null ? blue
				: LookupQueries.accountDisplay(lookupSession.getHiscoreResult(), lookupSession.getNativeClogResult()));
			renderTarget.applyBadge(clogInfoLabel, compareAccountDisplay());
		}
		else
		{
			playerName.setForeground(renderTarget.getInfoColor());
			clogInfoLabel.setHorizontalAlignment(JLabel.RIGHT);
			renderTarget.restoreClogCellForCompare(lookupSession.getClogResult());
		}
	}

	@Nullable
	private AccountDisplay compareAccountDisplay()
	{
		AccountType type = compared.selfType != null ? compared.selfType
			: LookupQueries.accountType(compared.hiscore, compared.clog);
		if (compared.rsn == null)
		{
			return AccountDisplay.of(type,
				compared.hiscore != null ? compared.hiscore.getHiscoreTable()
					: HiscoreTable.STANDARD);
		}
		AccountType providerType = runeProfileService.getCachedAccountType(compared.rsn);
		return AccountDisplay.of(
			AccountType.displayType(type,
				providerType != null && providerType.isGroupIronman() ? providerType : null),
			compared.hiscore != null ? compared.hiscore.getHiscoreTable()
				: HiscoreTable.STANDARD);
	}

	/**
	 * Refresh every cell on the panel for comparison mode (or restore each
	 * cell to single-player display when comparison is off). Iterates the
	 * boss / activity / clue-tier label maps + the standalone cells (combat,
	 * total).
	 */
	public void updateAllCells()
	{
		if (renderTarget == null)
		{
			return;
		}
		HiscoreResult blueHiscore = lookupSession.getHiscoreResult();
		HiscoreResult redHiscore = getCompareHiscoreResult();

		for (Map.Entry<HiscoreSkill, JLabel> entry : cells.getBossLabels().entrySet())
		{
			String name = PanelData.NAME_OVERRIDES.getOrDefault(entry.getKey().getName(), entry.getKey().getName());
			compareOrRestore(entry.getValue(), hiscoreKc(blueHiscore, name), hiscoreKc(redHiscore, name),
				cells.getTooltipData(entry.getKey()), compareTooltipDataMap.get(entry.getKey()));
		}
		for (Map.Entry<HiscoreSkill, JLabel> entry : cells.getActivityLabels().entrySet())
		{
			String name = entry.getKey().getName();
			compareOrRestore(entry.getValue(), activityScore(blueHiscore, name), activityScore(redHiscore, name));
		}

		for (Map.Entry<HiscoreSkill, JLabel> entry : cells.getClueTierLabels().entrySet())
		{
			String name = entry.getKey().getName();
			TooltipData redData = buildCompareClueTierData(entry.getKey());
			compareOrRestore(entry.getValue(), activityScore(blueHiscore, name), activityScore(redHiscore, name),
				cells.getTooltipData(entry.getKey()), redData);
		}

		compareOrRestore(renderTarget.combatCell(),
			blueHiscore != null ? blueHiscore.getCombatLevel() : -1,
			redHiscore != null ? redHiscore.getCombatLevel() : -1);

		boolean virtualTotal = virtualTotalLevel.get();
		compareOrRestore(renderTarget.totalLvlCell(),
			blueHiscore != null ? ClogHelper.displayTotalLevel(blueHiscore, virtualTotal) : -1,
			redHiscore != null ? ClogHelper.displayTotalLevel(redHiscore, virtualTotal) : -1);
	}

	@Nullable
	TooltipData buildCompareClueTierData(HiscoreSkill tier)
	{
		String category = PanelData.CLUE_CATEGORIES.get(tier);
		if (category == null)
		{
			return null;
		}
		int rank = compared.hiscore != null
			? getCompareHiscoreResult().getActivityRank(tier.getName()) : -1;
		ClogResult clog = getCompareClogResult();
		TooltipData data = clog != null
			? tooltipDataBuilder.buildTooltipData(Cells.capitalizeTier(tier),
				category, rank, clog) : null;
		if (data != null)
		{
			return data;
		}
		int score = compared.hiscore != null
			? getCompareHiscoreResult().getActivityScore(tier.getName()) : -1;
		return tooltipDataBuilder.buildUnsyncedTooltipData(
			Cells.capitalizeTier(tier), category, rank, Cells.cluesCompletedLabel(tier), score, unsyncedCatalog.result());
	}

	private static int hiscoreKc(@Nullable HiscoreResult r, String hiscoreName)
	{
		return r != null ? r.getKc(hiscoreName) : -1;
	}

	private static int activityScore(@Nullable HiscoreResult r, String name)
	{
		return r != null ? r.getActivityScore(name) : -1;
	}

	/** Toggle a cell between compare and solo display based on current mode. */
	public void compareOrRestore(JLabel label, int blueVal, int redVal)
	{
		compareOrRestore(label, blueVal, redVal, null, null);
	}

	/** Toggle a cell between compare and solo display with optional hover colors. */
	public void compareOrRestore(JLabel label, int blueVal, int redVal,
		@Nullable TooltipData blueData, @Nullable TooltipData redData)
	{
		if (label == null)
		{
			return;
		}
		if (comparisonMode)
		{
			setCompareCell(label, blueVal, redVal,
				completionColor(blueData), completionColor(redData));
		}
		else
		{
			restoreSoloCell(label, blueVal);
		}
	}

	@Nullable
	private Color completionColor(@Nullable TooltipData data)
	{
		if (data == null || data.totalItems <= 0 || data.obtainedCount < 0)
		{
			return null;
		}
		return ClogHelper.clogColor(data.obtainedCount, data.totalItems, config);
	}

	private static String colorHex(Color color)
	{
		return String.format("#%06x", color.getRGB() & 0xFFFFFF);
	}
}

package com.killclog;

import net.runelite.client.config.ConfigManager;

/** One-time moves of saved settings whose shape changed between releases. */
final class ConfigMigrations
{
	private static final String GROUP = "killclog";

	private ConfigMigrations()
	{
	}

	static void run(ConfigManager configManager)
	{
		skillColorMode(configManager);
		skillLocation(configManager);
	}

	private static void skillColorMode(ConfigManager configManager)
	{
		String legacy = configManager.getConfiguration(GROUP, "skillCompletionColor");
		if (legacy == null)
		{
			return;
		}

		if (configManager.getConfiguration(GROUP, "skillColorMode") == null)
		{
			configManager.setConfiguration(GROUP, "skillColorMode",
				SkillColorMode.fromLegacyCompletionColor(legacy));
		}
		configManager.unsetConfiguration(GROUP, "skillCompletionColor");
	}

	/**
	 * "Skill Summary only" hid the skill cells because the summary carried its
	 * own skill grid. The summary is two totals since 2.4.0, so those players
	 * move to the activity tray: still a compact panel, still every skill. A
	 * saved value RuneLite can no longer read would otherwise fall silently to
	 * the main grid.
	 */
	private static void skillLocation(ConfigManager configManager)
	{
		if ("TOOLTIP".equals(configManager.getConfiguration(GROUP, "skillDisplay")))
		{
			configManager.setConfiguration(GROUP, "skillDisplay", SkillDisplay.TRAY);
		}
	}
}

package com.killclog;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Efficient Hours Bossed: hiscore kill counts divided by community kill rates.
 * EHB rates by TempleOSRS (templeosrs.com), bundled as a versioned resource
 * and refreshed each release. A zero rate means the boss awards no EHB for
 * that mode; an unranked kill count awards nothing.
 */
@Slf4j
final class EhbRates
{
	private static final String RESOURCE = "ehb-rates.csv";

	// Boss name (hiscore CSV form) -> [main rate, ironman rate].
	private static final Map<String, double[]> RATES = load();

	private EhbRates()
	{
	}

	/**
	 * Sum of kc/rate across rated bosses, or -1 without hiscore data.
	 * GIMs only reach the hiscores through the regular table, so the
	 * resolved account type outranks the raw hiscore tag; every ironman
	 * mode uses the ironman column.
	 */
	static double compute(HiscoreResult result, AccountType resolvedType)
	{
		if (result == null)
		{
			return -1;
		}
		AccountType type = resolvedType != null ? resolvedType : result.getAccountType();
		boolean ironman = type != null && type != AccountType.REGULAR;
		double hours = 0;
		for (Map.Entry<String, double[]> entry : RATES.entrySet())
		{
			double rate = entry.getValue()[ironman ? 1 : 0];
			if (rate <= 0)
			{
				continue;
			}
			int kc = result.getKc(entry.getKey());
			if (kc > 0)
			{
				hours += kc / rate;
			}
		}
		return hours;
	}

	/** Read-only view for resource-integrity tests. */
	static Map<String, double[]> rates()
	{
		return Collections.unmodifiableMap(RATES);
	}

	private static Map<String, double[]> load()
	{
		Map<String, double[]> rates = new LinkedHashMap<>();
		try (InputStream in = EhbRates.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("EHB rates resource missing");
				return rates;
			}
			BufferedReader reader = new BufferedReader(
				new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				// Boss names hold no commas; the last two fields are rates.
				int imSep = line.lastIndexOf(',');
				int mainSep = line.lastIndexOf(',', imSep - 1);
				String name = line.substring(0, mainSep);
				double main = Double.parseDouble(line.substring(mainSep + 1, imSep));
				double im = Double.parseDouble(line.substring(imSep + 1));
				rates.put(name, new double[]{main, im});
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("EHB rates failed to load", e);
		}
		return rates;
	}
}

package com.killclog;

/** Panel feedback for one first-party control. All access stays on the EDT. */
final class FirstPartyFeedback
{
	/** Receives the messages this control is allowed to show. */
	interface Status
	{
		void show(StatusMessage.Kind kind, String text, boolean autoClear);
	}

	// A server that refuses this version: retrying cannot help, only an update can.
	static final String UPDATE_REQUIRED = "Kill Clog needs an update to keep syncing. Restart RuneLite to update it.";

	private final KillClogConfig config;
	private final Status status;
	private final Runnable successFlash;
	private final String failureText;
	private String lastFailure;

	FirstPartyFeedback(KillClogConfig config, Status status, Runnable successFlash, String failureText)
	{
		this.config = config;
		this.status = status;
		this.successFlash = successFlash;
		this.failureText = failureText;
	}

	void progress(boolean manual, String text, boolean autoClear)
	{
		show(manual, StatusMessage.Kind.PROGRESS, text, autoClear);
	}

	/** Manual actions always speak; automatic ones only when the user opted into their feedback. */
	void show(boolean manual, StatusMessage.Kind kind, String text, boolean autoClear)
	{
		if (manual || !config.silentAutomaticSync())
		{
			status.show(kind, text, autoClear);
		}
	}

	void complete(boolean manual, boolean ok, String message)
	{
		lastFailure = ok ? null : message != null ? message : failureText;
		if (ok)
		{
			if (manual || !config.silentAutomaticSync())
			{
				successFlash.run();
			}
		}
		else
		{
			show(manual, StatusMessage.Kind.RESULT, updateRequired() ? "update needed" : failureText, true);
		}
	}

	String lastFailure()
	{
		return lastFailure;
	}

	/** The control's hover label: its usual one, its failure one, or a call to update. */
	String hoverText(String normal, String failed)
	{
		return lastFailure == null ? normal : updateRequired() ? "update needed - restart RuneLite" : failed;
	}

	private boolean updateRequired()
	{
		return lastFailure != null && lastFailure.startsWith(UPDATE_REQUIRED);
	}

	void reset()
	{
		lastFailure = null;
	}
}

package com.killclog;

import java.util.EnumSet;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.WorldType;

/** Which game a world belongs to. Anything not known to be the main game or the active League has no mode. */
final class GameMode
{
	static final String MAIN = "main";
	// World flags that do not create a separate character.
	private static final Set<WorldType> MAIN_FLAGS = EnumSet.of(WorldType.MEMBERS, WorldType.PVP,
		WorldType.BOUNTY, WorldType.SKILL_TOTAL, WorldType.HIGH_RISK, WorldType.LAST_MAN_STANDING);

	private GameMode()
	{
	}

	/** Main, the League the server announced for seasonal worlds, or null. */
	@Nullable
	static String of(@Nullable Set<WorldType> flags, @Nullable String activeLeague)
	{
		if (flags == null)
		{
			return null;
		}
		for (WorldType flag : flags)
		{
			if (flag != WorldType.SEASONAL && !MAIN_FLAGS.contains(flag))
			{
				return null;
			}
		}
		return flags.contains(WorldType.SEASONAL) ? activeLeague : MAIN;
	}
}

/*
 * Copyright (c) 2026, 420 kc <dyl@420kc.dev>
 * Owns the GIM badge images: loads them from the game's modicons and holds
 * the per-type cache the badge resolver reads. Badge state is game-sprite
 * runtime state, so it lives here rather than in ClogHelper's pure helpers.
 */
package com.killclog;

import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import net.runelite.api.Client;
import net.runelite.api.IconID;
import net.runelite.api.IndexedSprite;

final class GimBadgeLoader
{
	private static final int MODICON_GIM = IconID.GROUP_IRONMAN.getIndex();
	private static final int MODICON_HCGIM = IconID.HARDCORE_GROUP_IRONMAN.getIndex();
	private static final int MODICON_UNRANKED_GIM = IconID.UNRANKED_GROUP_IRONMAN.getIndex();

	// Cached GIM badge images (loaded from game modicons at runtime)
	private static volatile BufferedImage gimBadge;
	private static volatile BufferedImage hcgimBadge;
	private static volatile BufferedImage unrankedGimBadge;

	private GimBadgeLoader()
	{
	}

	static void load(Client client)
	{
		IndexedSprite[] modIcons = client.getModIcons();
		if (modIcons == null)
		{
			return;
		}

		setGimBadges(
			imageAt(modIcons, MODICON_GIM),
			imageAt(modIcons, MODICON_HCGIM),
			imageAt(modIcons, MODICON_UNRANKED_GIM));
	}

	static void setGimBadges(BufferedImage gim, BufferedImage hcgim, BufferedImage unrankedGim)
	{
		gimBadge = gim;
		hcgimBadge = hcgim;
		unrankedGimBadge = unrankedGim;
	}

	static BufferedImage getGimBadge(AccountType type)
	{
		if (type == AccountType.GROUP_IRONMAN) return gimBadge;
		if (type == AccountType.HARDCORE_GROUP_IRONMAN) return hcgimBadge;
		if (type == AccountType.UNRANKED_GROUP_IRONMAN) return unrankedGimBadge;
		return null;
	}

	@Nullable
	static BufferedImage indexedSpriteToImage(IndexedSprite sprite)
	{
		if (sprite == null) return null;
		int w = sprite.getWidth();
		int h = sprite.getHeight();
		if (w <= 0 || h <= 0) return null;

		int canvasW = sprite.getOriginalWidth() > 0 ? sprite.getOriginalWidth() : w;
		int canvasH = sprite.getOriginalHeight() > 0 ? sprite.getOriginalHeight() : h;
		BufferedImage img = new BufferedImage(canvasW, canvasH, BufferedImage.TYPE_INT_ARGB);
		byte[] pixels = sprite.getPixels();
		int[] palette = sprite.getPalette();
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int idx = pixels[y * w + x] & 0xFF;
				int px = x + sprite.getOffsetX();
				int py = y + sprite.getOffsetY();
				if (px >= 0 && px < canvasW && py >= 0 && py < canvasH)
				{
					img.setRGB(px, py, idx == 0 ? 0 : 0xFF000000 | palette[idx]);
				}
			}
		}
		return img;
	}

	private static BufferedImage imageAt(IndexedSprite[] modIcons, int index)
	{
		return modIcons.length > index ? indexedSpriteToImage(modIcons[index]) : null;
	}
}

package com.killclog;

import java.util.Collections;
import java.util.Map;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;

/**
 * Parsed hiscore data for a player.
 */
public class HiscoreResult
{
	@Getter
	private final AccountType accountType;
	@Getter(AccessLevel.PACKAGE)
	private final HiscoreTable hiscoreTable;
	@Getter
	private final Map<String, Integer> bossKills;
	private final Map<String, Integer> bossRanks;
	private final Map<String, Integer> activityScores;
	private final Map<String, Integer> activityRanks;
	private final Map<String, Integer> skillLevels;
	private final Map<String, Integer> skillRanks;
	private final Map<String, Long> skillXps;
	@Getter
	private final int totalLevel;
	@Getter
	private final long totalXp;
	/** Unrounded, so the Combat Summary can show what vanilla calls Exact Combat Level. */
	@Getter
	private final double combatLevelExact;
	@Getter
	private final int overallRank;
	@Getter(AccessLevel.PACKAGE)
	private boolean rankDataAvailable = true;

	// Set when the hiscore CSV line count no longer matches the known format:
	// the boss maps were left empty on purpose (positions cannot be trusted).
	// Surfaces render their normal quiet absent state; no banner, by design.
	@Getter
	@Setter(AccessLevel.PACKAGE)
	private boolean bossSectionShifted;

	/** Another leaderboard's row that trails this player's stats, like a Hardcore's after the death. */
	@Getter(AccessLevel.PACKAGE)
	private boolean frozen;

	/**
	 * Whether this lookup's own answers make the account an Ironman now: true when its regular and
	 * Ironman rows matched or RuneLite named the type, false when the Ironman row trailed, and null
	 * when either board didn't answer. It stays with the lookup, so later caches can't change it.
	 */
	@Getter(AccessLevel.PACKAGE)
	@Setter(AccessLevel.PACKAGE)
	private Boolean ironmanNow;

	public HiscoreResult(AccountType accountType, Map<String, Integer> bossKills,
		Map<String, Integer> bossRanks, Map<String, Integer> activityScores,
		Map<String, Integer> activityRanks, Map<String, Integer> skillLevels,
		int totalLevel, long totalXp, double combatLevel, int overallRank)
	{
		this(accountType, HiscoreTable.STANDARD, bossKills, bossRanks, activityScores,
			activityRanks, skillLevels, Collections.emptyMap(), Collections.emptyMap(),
			totalLevel, totalXp, combatLevel, overallRank);
	}

	public HiscoreResult(AccountType accountType, HiscoreTable hiscoreTable,
		Map<String, Integer> bossKills, Map<String, Integer> bossRanks,
		Map<String, Integer> activityScores, Map<String, Integer> activityRanks,
		Map<String, Integer> skillLevels, int totalLevel, long totalXp,
		double combatLevel, int overallRank)
	{
		this(accountType, hiscoreTable, bossKills, bossRanks, activityScores,
			activityRanks, skillLevels, Collections.emptyMap(), Collections.emptyMap(),
			totalLevel, totalXp, combatLevel, overallRank);
	}

	public HiscoreResult(AccountType accountType, HiscoreTable hiscoreTable,
		Map<String, Integer> bossKills, Map<String, Integer> bossRanks,
		Map<String, Integer> activityScores, Map<String, Integer> activityRanks,
		Map<String, Integer> skillLevels, Map<String, Integer> skillRanks,
		Map<String, Long> skillXps, int totalLevel, long totalXp,
		double combatLevel, int overallRank)
	{
		this.accountType = accountType;
		this.hiscoreTable = hiscoreTable != null ? hiscoreTable : HiscoreTable.STANDARD;
		this.bossKills = bossKills != null ? bossKills : Collections.emptyMap();
		this.bossRanks = bossRanks != null ? bossRanks : Collections.emptyMap();
		this.activityScores = activityScores != null ? activityScores : Collections.emptyMap();
		this.activityRanks = activityRanks != null ? activityRanks : Collections.emptyMap();
		this.skillLevels = skillLevels != null ? skillLevels : Collections.emptyMap();
		this.skillRanks = skillRanks != null ? skillRanks : Collections.emptyMap();
		this.skillXps = skillXps != null ? skillXps : Collections.emptyMap();
		this.totalLevel = totalLevel;
		this.totalXp = totalXp;
		this.combatLevelExact = combatLevel;
		this.overallRank = overallRank;
	}

	/** The whole combat level every cell and comparison uses. */
	public int getCombatLevel()
	{
		return (int) Math.floor(combatLevelExact);
	}

	public int getKc(String bossName)
	{
		return bossKills.getOrDefault(bossName, -1);
	}

	/** Another leaderboard's whole row under this player's own type and table, so a Hardcore
	 *  who died reads their Hardcore stats as they stood at the death. */
	HiscoreResult withRow(HiscoreResult row)
	{
		HiscoreResult view = new HiscoreResult(accountType, hiscoreTable, row.bossKills, row.bossRanks,
			row.activityScores, row.activityRanks, row.skillLevels, row.skillRanks, row.skillXps,
			row.totalLevel, row.totalXp, row.combatLevelExact, row.overallRank);
		view.bossSectionShifted = row.bossSectionShifted;
		view.rankDataAvailable = row.rankDataAvailable;
		view.frozen = row.totalXp < totalXp;
		view.ironmanNow = ironmanNow;
		return view;
	}

	/** A display-only projection. A missing table blanks ranks, never stats or identity. */
	HiscoreResult withRanks(HiscoreResult ranks)
	{
		HiscoreResult view = new HiscoreResult(accountType, hiscoreTable, bossKills,
			ranks != null ? ranks.bossRanks : Collections.emptyMap(), activityScores,
			ranks != null ? ranks.activityRanks : Collections.emptyMap(), skillLevels,
			ranks != null ? ranks.skillRanks : Collections.emptyMap(), skillXps,
			totalLevel, totalXp, combatLevelExact, ranks != null ? ranks.overallRank : -1);
		view.bossSectionShifted = bossSectionShifted;
		view.rankDataAvailable = ranks != null && ranks.rankDataAvailable;
		view.ironmanNow = ironmanNow;
		return view;
	}

	public int getRank(String bossName)
	{
		return bossRanks.getOrDefault(bossName, -1);
	}

	public int getActivityScore(String name)
	{
		return activityScores.getOrDefault(name, -1);
	}

	public int getActivityRank(String name)
	{
		return activityRanks.getOrDefault(name, -1);
	}

	public int getSkillLevel(String name)
	{
		return skillLevels.getOrDefault(name, -1);
	}

	public int getSkillRank(String name)
	{
		return skillRanks.getOrDefault(name, -1);
	}

	public long getSkillXp(String name)
	{
		return skillXps.getOrDefault(name, -1L);
	}
}

