package com.killclog;

import java.awt.Color;
import javax.swing.Timer;

/**
 * One occupant of the panel status row: who wrote it, how it shares the row,
 * and the expiry that belongs to it. Two messages with the same text are still
 * two messages, so a stale expiry can never clear a newer one.
 */
final class StatusMessage
{
	enum Owner
	{
		LOOKUP, SYNC, CHARACTER
	}

	enum Kind
	{
		/** A control's hover line; yields to anything and clears when the pointer leaves. */
		HOVER,
		/** An actionable hint; yields to anything and keeps the controls visible while it expires. */
		NOTICE,
		/** Work in flight; holds the row until its owner replaces it. */
		PROGRESS,
		/** An outcome; holds the row until it expires or its owner replaces it. */
		RESULT
	}

	final Owner owner;
	final Kind kind;
	final String text;
	final Color color;
	private Timer expiry;

	StatusMessage(Owner owner, Kind kind, String text, Color color)
	{
		this.owner = owner;
		this.kind = kind;
		this.text = text;
		this.color = color;
	}

	/** Hover lines and notices leave the row free for the next writer. */
	boolean yields()
	{
		return kind == Kind.HOVER || kind == Kind.NOTICE;
	}

	/** Runs the action once on the EDT after the delay unless {@link #cancelExpiry} comes first. */
	void expireAfter(int delayMs, Runnable action)
	{
		cancelExpiry();
		expiry = new Timer(delayMs, e -> action.run());
		expiry.setRepeats(false);
		expiry.start();
	}

	void cancelExpiry()
	{
		if (expiry != null)
		{
			expiry.stop();
			expiry = null;
		}
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.channels.FileChannel;
import java.nio.channels.FileLock;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * The one-time move from 2.4's name-keyed files to account-keyed own logs.
 *
 * <p>A file is an own log only with proof: its owner stamp, plus first-party
 * marks or a completed Collection Log Search. Proven copies of one account
 * merge provenance first ({@link ClogRecords#mergeOwn}); pure provider copies
 * become lookups; everything else is archived in {@code legacy/}, never
 * deleted and never read. It runs under a file lock until the layout marker
 * exists, so two clients take turns and a crash resumes on the next start.
 */
@Slf4j
final class StoreMigration
{
	static final String MARKER = ".kill-clog-layout";
	static final String LOOKUPS = "lookups";
	static final String LEGACY = "legacy";
	private static final String LOCK = ".migration.lock";
	private static final String LEDGER = ".kill-clog-identity.json";
	private static final String SIDECAR = ".displaced-";

	private StoreMigration()
	{
	}

	/**
	 * True once the store is in the account layout; false leaves it for the next
	 * start. The file lock orders clients; this monitor orders stores in one client.
	 */
	static synchronized boolean run(Gson gson, Filepath folder)
	{
		try
		{
			folder.createDirectories();
			if (folder.join(MARKER).exists())
			{
				return true;
			}
			try (FileChannel channel = folder.join(LOCK).openFileChannel(
				StandardOpenOption.CREATE, StandardOpenOption.WRITE);
				FileLock ignored = channel.lock())
			{
				if (!folder.join(MARKER).exists())
				{
					migrate(gson, folder);
					folder.join(MARKER).write("2");
				}
			}
			return true;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Kill Clog will finish moving its files on the next start: {}", e.getMessage());
			return false;
		}
	}

	/** An account's own-log file: its hash as 16 hex digits, longer than any character name. */
	static String ownFileName(String hashKey)
	{
		return String.format("%016x", Long.parseLong(hashKey)) + ".json";
	}

	private static final class Candidate
	{
		final Filepath file;
		final PlayerClogData data;

		Candidate(Filepath file, PlayerClogData data)
		{
			this.file = file;
			this.data = data;
		}
	}

	private static void migrate(Gson gson, Filepath folder) throws IOException
	{
		Map<String, String> ledger = ledgerNames(gson, folder.join(LEDGER));
		Map<String, List<Candidate>> own = new LinkedHashMap<>();
		Map<String, PlayerClogData> earlier = new HashMap<>();
		for (Filepath file : list(folder))
		{
			String name = file.getFileName();
			if (name.matches("[0-9a-f]{16}\\.json"))
			{
				// An interrupted earlier run's own log stays only when whole and named for its owner.
				PlayerClogData data = read(gson, file, PlayerClogData.class);
				if (data != null && name.equals(LocalClogCache.ownFile(data.ownerHash)))
				{
					earlier.put(data.ownerHash, data);
				}
				else
				{
					LocalClogCache.atomicMove(file, folder.join(".unreadable-" + name + "-" + System.currentTimeMillis() + ".json"));
				}
				continue;
			}
			if (!name.endsWith(".json") || (name.startsWith(".") && !name.startsWith(SIDECAR)))
			{
				continue;
			}
			PlayerClogData data = read(gson, file, PlayerClogData.class);
			String hash = data != null ? provenOwner(name, data) : null;
			if (hash != null)
			{
				own.computeIfAbsent(hash, h -> new ArrayList<>()).add(new Candidate(file, data));
			}
			else if (data == null || ClogRecords.hasFirstPartyMarks(data)
				|| Boolean.TRUE.equals(data.firstPartySetupComplete) || data.firstPartyByCategory == null)
			{
				archive(folder, file, LEGACY);
			}
			else
			{
				toLookups(gson, folder, file, data);
			}
		}
		for (Map.Entry<String, List<Candidate>> entry : own.entrySet())
		{
			writeOwn(gson, folder, entry.getKey(), entry.getValue(), earlier.get(entry.getKey()), ledger.get(entry.getKey()));
		}
		Filepath ca = folder.join("ca");
		if (ca.isDirectory())
		{
			for (Filepath file : list(ca))
			{
				if (file.getFileName().endsWith(".json") && !file.getFileName().matches("[0-9a-f]{16}\\.json"))
				{
					archive(folder, file, LEGACY, "ca");
				}
			}
		}
		Filepath ledgerFile = folder.join(LEDGER);
		if (ledgerFile.exists())
		{
			archive(folder, ledgerFile, LEGACY);
		}
	}

	/**
	 * The stamped hash, when first-party evidence backs it and a sidecar's name
	 * agrees. A file without a marker map predates marking and is never proof.
	 */
	private static String provenOwner(String fileName, PlayerClogData data)
	{
		String hash = data.ownerHash;
		if (hash == null || !hash.matches("-?\\d{1,19}") || data.firstPartyByCategory == null
			|| fileName.startsWith(SIDECAR) && !fileName.startsWith(SIDECAR + hash + "-"))
		{
			return null;
		}
		boolean evidence = ClogRecords.hasFirstPartyMarks(data)
			|| Boolean.TRUE.equals(data.firstPartySetupComplete);
		return evidence ? hash : null;
	}

	/**
	 * One account's own log from its proven copies, each cut to its first-party
	 * core. The base is an earlier run's result, else what 2.4 serves for the
	 * account: its ledger name, then its parked copy, then the newest.
	 */
	private static void writeOwn(Gson gson, Filepath folder, String hash, List<Candidate> candidates,
		PlayerClogData earlier, String ledgerName) throws IOException
	{
		List<Candidate> ordered = new ArrayList<>(candidates);
		String served = ledgerName != null ? LocalClogCache.fileName(ledgerName) : null;
		ordered.sort(Comparator.<Candidate, Boolean>comparing(c -> !c.file.getFileName().equals(served))
			.thenComparing(c -> !c.file.getFileName().startsWith(SIDECAR))
			.thenComparing(c -> c.data.lastUpdated, Comparator.nullsLast(Comparator.reverseOrder())));
		PlayerClogData merged = earlier != null ? ClogRecords.ownCore(earlier, hash) : null;
		for (Candidate candidate : ordered)
		{
			PlayerClogData core = ClogRecords.ownCore(candidate.data, hash);
			merged = merged == null ? core : ClogRecords.mergeOwn(merged, core);
		}
		write(gson, folder, folder.join(ownFileName(hash)), merged);
		for (Candidate candidate : candidates)
		{
			archive(folder, candidate.file, LEGACY);
		}
	}

	private static void toLookups(Gson gson, Filepath folder, Filepath file, PlayerClogData data) throws IOException
	{
		Filepath dest = folder.join(LOOKUPS, safeName(file.getFileName()));
		if (!LocalClogCache.absent(dest))
		{
			PlayerClogData there = read(gson, dest, PlayerClogData.class);
			if (there != null && Objects.compare(there.lastUpdated, data.lastUpdated,
				Comparator.nullsFirst(Comparator.naturalOrder())) >= 0)
			{
				// Both are regenerable provider copies; the newer one stays.
				file.deleteIfExists();
				return;
			}
		}
		folder.join(LOOKUPS).createDirectories();
		LocalClogCache.atomicMove(file, dest);
	}

	private static void archive(Filepath folder, Filepath file, String... dir) throws IOException
	{
		Filepath target = folder.join(dir[0], java.util.Arrays.copyOfRange(dir, 1, dir.length));
		target.createDirectories();
		Filepath dest = target.join(safeName(file.getFileName()));
		if (dest.exists())
		{
			dest = target.join(System.currentTimeMillis() + "-" + safeName(file.getFileName()));
		}
		LocalClogCache.atomicMove(file, dest);
	}

	/** Off Windows a 2.4 file can carry a Windows device name, which RuneLite refuses to create. */
	private static String safeName(String fileName)
	{
		String stem = fileName.substring(0, fileName.length() - ".json".length());
		return stem.matches("con|prn|aux|nul|(com|lpt)[1-9]") ? "+" + fileName : fileName;
	}

	static void write(Gson gson, Filepath folder, Filepath dest, Object data) throws IOException
	{
		Filepath tmp = folder.createTempFile(".write-", ".tmp");
		try
		{
			try (BufferedWriter writer = tmp.openBufferedWriter())
			{
				gson.toJson(data, writer);
			}
			LocalClogCache.atomicMove(tmp, dest);
		}
		finally
		{
			tmp.deleteIfExists();
		}
	}

	static <T> T read(Gson gson, Filepath file, Class<T> type)
	{
		try (BufferedReader reader = file.openBufferedReader())
		{
			return gson.fromJson(reader, type);
		}
		catch (Exception e)
		{
			log.warn("Unreadable Kill Clog file '{}': {}", file.getFileName(), e.getMessage());
			return null;
		}
	}

	/** 2.4's ledger names (hash to name key), v2 or the v1 bare map; empty when unreadable. */
	private static Map<String, String> ledgerNames(Gson gson, Filepath file)
	{
		if (!file.exists())
		{
			return Collections.emptyMap();
		}
		try (BufferedReader reader = file.openBufferedReader())
		{
			JsonObject root = gson.fromJson(reader, JsonObject.class);
			JsonObject names = root.has("names") && root.get("names").isJsonObject()
				? root.getAsJsonObject("names") : root;
			Map<String, String> out = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : names.entrySet())
			{
				if (e.getValue().isJsonPrimitive())
				{
					out.put(e.getKey(), e.getValue().getAsString());
				}
			}
			return out;
		}
		catch (Exception e)
		{
			return Collections.emptyMap();
		}
	}

	private static List<Filepath> list(Filepath dir) throws IOException
	{
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(Filepath::isFile).collect(Collectors.toList());
		}
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import net.runelite.client.game.ItemManager;

/**
 * Player summary tooltip on the summary-bar name label.
 * The player's name is the title, in white beside their account badge. Under it stand the
 * prestige cape or a Kill Clog syncer's character, centered, then the account and prestige
 * lines, then the obtained pets at full size. Like the other summaries, only the title and the hover band
 * under it stay put: the rest scrolls as one once it outgrows the window. Hovering a pet names it in that band
 * and left-click opens its wiki page - same contract as the boss grids.
 */
public class SummaryTooltip extends TitleTooltip
{
	private static final int PET_COLS = 5;
	private static final int FIGURE_GAP = 4;
	private static final String PRESTIGE_LABEL = "Prestige: ";
	private static final String FORMER_TITLE = "Player Summary";

	private int overallRank;
	// The prestige cape, or a Kill Clog syncer's character (PlayerPortraits) standing in its place.
	private BufferedImage figure;
	private String accountLabel;
	private String prestige;
	// With a character standing in, the prestige cape sits small in the header's corner and names its prestige.
	@Nullable
	private BufferedImage cape;

	// Pet data only includes obtained pets: the gallery shows what you have,
	// not the empty slots.
	private int totalPetCount;
	private List<Integer> petList;
	private Map<Integer, String> petNames;
	private Map<Integer, Integer> petCounts = Collections.emptyMap();
	@Nullable
	private TooltipItemSprites petSprites;
	// Everything under the band scrolls in the standard window, a sprite row a notch, as a skill's log does.
	private final CardBody.Scroll scroll = new CardBody.Scroll(this, CardBody.WINDOW, CardBody.GRID_CELL);

	public void setData(String rsn, int overallRank, BufferedImage figure,
						BufferedImage badgeIcon, String accountLabel, String prestige)
	{
		itemHover.clear();
		// The panel's own stand-in when a lookup has no name, so the card always keeps its title.
		setTitle(rsn != null ? rsn : "Player");
		setTitleIcon(badgeIcon);
		this.overallRank = overallRank;
		this.figure = withoutHeadroom(figure);
		this.accountLabel = accountLabel;
		this.prestige = prestige;
		// Account type and rank read under the name, above the title's divider.
		if (hasRankLine())
		{
			setSubtitle(accountLabelText(), rankTail(), Color.WHITE);
		}
		else
		{
			clearSubtitle();
		}
	}

	/** A published character's prestige cape, drawn small in the header; null when the cape is the figure. */
	void setCape(@Nullable BufferedImage cape)
	{
		this.cape = cape;
	}

	/** The player's name reads white, like the name it is, not an orange card label. */
	@Override
	protected Color titleColor()
	{
		return Color.WHITE;
	}

	/** The player's name at the size the grid cards title in. */
	@Override
	protected Font getTitleFont()
	{
		return TITLE_FONT_SMALL;
	}

	/** The pets held, in the log's order, each with its count for the corner like any item sprite. */
	public void setPets(List<Integer> allPetIds, Map<Integer, Integer> obtainedPetCounts,
		ItemManager itemManager, IntFunction<String> nameLookup)
	{
		this.totalPetCount = allPetIds != null ? allPetIds.size() : 0;
		petCounts = obtainedPetCounts != null ? obtainedPetCounts : Collections.emptyMap();

		petList = new ArrayList<>();
		if (allPetIds != null)
		{
			for (int id : allPetIds)
			{
				if (petCounts.containsKey(id))
				{
					petList.add(id);
				}
			}
		}

		// A pet without a name still hovers and links, under the name its id gives it.
		petNames = new HashMap<>();
		for (int id : petList)
		{
			petNames.put(id, nameLookup != null ? nameLookup.apply(id) : null);
		}
		petSprites = !petList.isEmpty() && itemManager != null
			? TooltipItemSprites.load(petList, petNames, itemManager, id -> 1, this) : null;
	}

	@Override
	CardBody.Scroll scroll()
	{
		return scroll;
	}

	private boolean hasRankLine()
	{
		return accountLabel != null || overallRank > 0;
	}

	private boolean hasPets()
	{
		return petList != null && !petList.isEmpty();
	}

	/** Without a figure or prestige, nothing stands between the title and the pets. */
	private boolean hasBodyAbovePets()
	{
		return figure != null || prestige != null;
	}

	@Override
	protected CardBody body()
	{
		// The cape or character stands centered under the name; with a character, the cape names its prestige from
		// the header's corner instead of a line under the figure.
		boolean capeInHeader = cape != null && prestige != null;
		CardBody card = new CardBody().add(CardBody.minWidth(c -> getFontMetrics(getTitleFont()).stringWidth(FORMER_TITLE)));
		if (capeInHeader)
		{
			card.add(headerCorner(true, cape, prestige));
		}
		if (figure != null)
		{
			card.add(CardBody.row(figure.getHeight() + FIGURE_GAP, c -> figure.getWidth(),
				(c, y) -> c.g.drawImage(figure, (c.w - figure.getWidth()) / 2, y, null)));
		}
		// Prestige centered under the figure, when the figure is the cape.
		if (prestige != null && !capeInHeader)
		{
			card.add(centered(PRESTIGE_LABEL, prestige));
		}
		if (totalPetCount > 0)
		{
			// A pet's name shows in the band over the pets, straight under the title's divider when nothing stands
			// between, and the pets scroll under it.
			int count = hasPets() ? petList.size() : 0;
			CardBody pets = new CardBody().add(CardBody.line("Pets: ", String.valueOf(count),
				completionColor(count, totalPetCount)));
			if (hasPets())
			{
				pets.add(CardBody.grid(PET_COLS, petSprites, petNames, petList, new HashSet<>(petList), petCounts));
			}
			card.add(hasBodyAbovePets() ? CardBody.hoverBand() : CardBody.headerHoverBand())
				.add(CardBody.scroll(scroll, pets.asPart()));
		}
		else if (capeInHeader)
		{
			card.add(CardBody.hoverBand());
		}
		return card;
	}

	private static CardBody.Part centered(String label, String value)
	{
		return CardBody.row(LINE_HEIGHT, c -> c.fm.stringWidth(label + value), (c, y) -> drawLabelValue(c.g, c.fm,
			(c.w - c.fm.stringWidth(label + value)) / 2, y + c.fm.getAscent(), label, value));
	}

	private String accountLabelText()
	{
		return accountLabel != null ? accountLabel : "";
	}

	/** " #1,234" after an account label, "#1,234" alone, nothing when unranked. */
	private String rankTail()
	{
		return overallRank > 0 ? (accountLabel != null ? " #" : "#") + grouped(overallRank) : "";
	}

	/**
	 * The figure cut to its first row of pixels: a character's portrait leaves room above the head
	 * for tall hats, which would read as a gap under the name.
	 */
	@Nullable
	static BufferedImage withoutHeadroom(@Nullable BufferedImage image)
	{
		if (image == null)
		{
			return null;
		}
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					return y == 0 ? image : image.getSubimage(0, y, image.getWidth(), image.getHeight() - y);
				}
			}
		}
		return image;
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ThreadLocalRandom;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;

/**
 * Pushes the active player's locally captured collection log to the
 * killclog.com first-party ingest endpoint
 * ({@code POST https://killclog.com/api/player/<rsn>/sync}).
 *
 * <p>Gated behind a default-off config toggle
 * ({@link KillClogConfig#killclogSync()}); nothing is pushed until the
 * player opts in.
 *
 * <p>Scope: only the logged-in account can push, and only its own local
 * store - the log this client has accumulated across its own captures and
 * live unlocks. Publishing your own account's truth is what the opt-in
 * means; other players' data has no path here.
 */
@Slf4j
@Singleton
class SyncService
{
	// Attributed on the server per client build.
	static final String CLIENT_VERSION = "2.6.1";

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final LocalClogCache localClogCache;
	// The game's Collection Log as this client reads it, shared when killclog.com holds another.
	@Setter
	@Nullable
	private ClogIndex clogIndex;
	// The structure killclog.com holds, as its last sync reply named it; null until one has.
	private volatile String serverStructureHash;
	// Every loading screen schedules a push: one identical to the last that killclog.com took, within a day, stays home.
	static final long RESEND_UNCHANGED_MS = 24 * 60 * 60 * 1000L;
	private volatile String acceptedPush;
	private volatile long acceptedAt;
	private volatile SyncResult acceptedResult;
	/** What a push killclog.com already holds answers: nothing went, so nothing is said. */
	static final SyncResult UNCHANGED = new SyncResult(true, false, "");

	/** Outcome of a sync attempt, surfaced for chat feedback. */
	static final class SyncResult
	{
		final boolean ok;
		final boolean dryRun;
		final String message;
		/** Server says another sync holds this player's lock: retry, don't fail. */
		final boolean retryAdvised;
		final int retryAfterSeconds;

		SyncResult(boolean ok, boolean dryRun, String message)
		{
			this(ok, dryRun, message, false, 0);
		}

		SyncResult(boolean ok, boolean dryRun, String message,
			boolean retryAdvised, int retryAfterSeconds)
		{
			this.ok = ok;
			this.dryRun = dryRun;
			this.message = message;
			this.retryAdvised = retryAdvised;
			this.retryAfterSeconds = retryAfterSeconds;
		}
	}

	@Inject
	SyncService(OkHttpClient httpClient, Gson gson, LocalClogCache localClogCache)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.localClogCache = localClogCache;
	}

	/**
	 * Build the ingest body from this client's in-game observations and POST
	 * it. Completes with a failed-shape result rather than throwing.
	 *
	 * @param accountType the locally detected account type (client varbits),
	 *                    never the provider-derived one
	 */
	/**
	 * {@code cache} is the mode's own store and {@code cacheEpoch} its gather-time session; {@code always} sends even
	 * what killclog.com already holds (a click, or a character publish that needs the profile). {@code sending} runs
	 * just before a push goes.
	 */
	CompletableFuture<SyncResult> syncCollectionLog(String rsn, long accountHash,
		@Nullable AccountType accountType, Map<String, Double> personalBests,
		Map<String, DetailedPb> detailedPersonalBests, long cacheEpoch,
		KillclogSyncGate syncGate, int generation, LocalClogCache cache, String mode, boolean always, Runnable sending)
	{
		if (rsn == null || rsn.isBlank())
		{
			return CompletableFuture.completedFuture(
				new SyncResult(false, false, "No player to sync."));
		}

		// Only this session's account, its own log serving, can be the payload.
		// The caller's gather-time epoch rides in so a logout since then fences
		// the whole pre-flight inside the cache monitor.
		if (!cache.servesAccount(rsn, accountHash, cacheEpoch))
		{
			return CompletableFuture.completedFuture(new SyncResult(false, false,
				"Still checking this account. Try again in a moment."));
		}

		// The player's own accumulated local store is the payload: months of
		// their in-client captures and live unlocks, published as their own
		// truth - requiring a full re-walk to seed the sync would be needless
		// friction. Only the logged-in account can
		// ever push, and only its own file - filtered to items this client
		// observed first-hand, so provider-cached data (pre-login lookups,
		// cross-character searches) can never launder into first-party proof.
		ClogResult clog = cache.toFirstPartySyncResult(rsn);
		if (clog == null || clog.getObtainedItems().isEmpty())
		{
			return CompletableFuture.completedFuture(
				new SyncResult(false, false, "No local collection log to sync yet."));
		}

		JsonObject root = buildBody(accountHash, accountType, clog, personalBests, detailedPersonalBests);
		JsonObject structure = GameMode.MAIN.equals(mode) ? structureToShare() : null;
		if (structure != null)
		{
			root.add("clog_structure", structure);
		}
		String body = gson.toJson(root);
		final int observedCount = ClogResult.coverageCount(clog);
		String url = KillClogEndpoint.apiBaseUrl() + "/player/" + HttpUtil.pathSegment(rsn) + "/sync/" + mode;
		String push = url + body;
		if (!always && acceptedResult != null && push.equals(acceptedPush)
			&& System.currentTimeMillis() - acceptedAt < RESEND_UNCHANGED_MS)
		{
			return CompletableFuture.completedFuture(UNCHANGED);
		}
		sending.run();

		log.debug("Syncing collection log for '{}' to {} ({} items)",
			rsn, url, observedCount);
		final int pbCount = personalBests != null ? personalBests.size() : 0;
		CompletableFuture<HttpUtil.HttpResult> request = cache.commitIfSessionCurrent(
			cacheEpoch, () -> syncGate.commitIfCurrent(generation,
				() -> HttpUtil.httpPostJson(httpClient, url, body, null)));
		if (request == null)
		{
			return CompletableFuture.completedFuture(
				new SyncResult(false, false, "Sync session ended before send."));
		}
		return request.thenApply(r ->
		{
			SyncResult result = outcome(r, rsn, observedCount, pbCount);
			if (result.ok && !result.dryRun)
			{
				acceptedResult = result;
				acceptedAt = System.currentTimeMillis();
				acceptedPush = push;
			}
			return result;
		});
	}

	/** The game's structure when killclog.com named a different one in its last reply, else null. */
	@Nullable
	JsonObject structureToShare()
	{
		ClogIndex index = clogIndex;
		String held = serverStructureHash;
		JsonObject structure = index != null && held != null ? ClogStructure.of(index) : null;
		return structure != null && !held.equals(ClogStructure.hash(gson, structure)) ? structure : null;
	}

	/** What one round trip means for the player, in plain words. */
	SyncResult outcome(HttpUtil.HttpResult r, String rsn, int observedCount, int pbCount)
	{
		if (r.code >= 200 && r.code < 300)
		{
			rememberStructureHash(r.body);
			boolean dryRun = responseSaysDryRun(r.body);
			return new SyncResult(true, dryRun,
				"Collection log synced! ("
				+ observedCount + (observedCount == 1 ? " item" : " items")
				+ (pbCount > 0 ? ", " + pbCount + (pbCount == 1 ? " pb" : " pbs") : "")
				+ (dryRun ? ", not saved" : "") + ").");
		}
		// 409 sync_in_flight is contention, not failure: another client of
		// this account holds the per-player lock for a moment. Advise a
		// short retry instead of booking a failure.
		if (r.code == 409 && r.body != null && r.body.contains("sync_in_flight"))
		{
			return new SyncResult(false, false,
				"Another sync for this account is in flight - retrying shortly.",
				true, parseRetryAfterSeconds(r.body));
		}
		// The server's identity arbitration answers (2026-08-16 wire
		// contract): each gets plain words instead of a bare HTTP code.
		if (r.code == 409 && r.body != null && r.body.contains("name_active_with_another_account"))
		{
			return new SyncResult(false, false,
				"This name's previous owner played recently - Kill Clog will "
				+ "accept your log after their continuity window passes.");
		}
		if (r.code == 409 && r.body != null && r.body.contains("account_hash_mismatch"))
		{
			return new SyncResult(false, false,
				"This name is registered to a different account on Kill Clog.");
		}
		// The server no longer takes this version's syncs (a League cutover): only an update helps.
		if (r.code == 426)
		{
			return new SyncResult(false, false, FirstPartyFeedback.UPDATE_REQUIRED);
		}
		if (r.code == 451)
		{
			return new SyncResult(false, false,
				"This account has opted out of Kill Clog sync.");
		}
		log.debug("killclog sync failed for '{}': HTTP {}", rsn, r.code);
		// A restarting server answers 502 to 504 for a few seconds: worth one
		// quiet retry before anyone is told. The delay is spread out so the
		// clients it turned away do not all come back together.
		boolean restarting = r.code >= 502 && r.code <= 504;
		return new SyncResult(false, false,
			"Collection log sync failed. Try again later.",
			restarting, restarting ? 15 + ThreadLocalRandom.current().nextInt(16) : 0);
	}

	private int parseRetryAfterSeconds(String body)
	{
		try
		{
			JsonObject obj = gson.fromJson(body, JsonObject.class);
			if (obj != null && obj.has("retry_after_seconds"))
			{
				int seconds = obj.get("retry_after_seconds").getAsInt();
				// Bounded: the server advises, the client decides.
				return Math.max(1, Math.min(seconds, 30));
			}
		}
		catch (RuntimeException e)
		{
			// fall through to the default
		}
		return 2;
	}

	private void rememberStructureHash(String body)
	{
		try
		{
			JsonObject obj = body != null ? gson.fromJson(body, JsonObject.class) : null;
			if (obj != null && obj.has("clog_structure_hash") && obj.get("clog_structure_hash").isJsonPrimitive())
			{
				serverStructureHash = obj.get("clog_structure_hash").getAsString();
			}
		}
		catch (RuntimeException e)
		{
			// a reply without it changes nothing
		}
	}

	private boolean responseSaysDryRun(String body)
	{
		if (body == null || body.isEmpty())
		{
			return false;
		}
		try
		{
			JsonObject obj = gson.fromJson(body, JsonObject.class);
			return obj != null && obj.has("dry_run") && obj.get("dry_run").getAsBoolean();
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/**
	 * Request body per the ingest contract:
	 * {@code { account_hash, account_type?, clog: [{item_id, quantity, categories[], obtained_at?}], client_version }}.
	 * Items in multiple categories merge to one entry; sorted by item id so
	 * identical stores produce identical payloads.
	 */
	private JsonObject buildBody(long accountHash, @Nullable AccountType accountType,
		ClogResult clog, Map<String, Double> personalBests,
		Map<String, DetailedPb> detailedPersonalBests)
	{
		JsonObject root = new JsonObject();
		root.addProperty("account_hash", Long.toString(accountHash));
		if (accountType != null)
		{
			root.addProperty("account_type", accountType.name().toLowerCase(Locale.ROOT));
		}
		// The game's own unique counters (varp-sourced) ride along so the
		// site can show the true "obtained out of how many" fraction instead
		// of approximating the denominator from catalogs.
		if (clog.getUniqueObtained() > 0)
		{
			root.addProperty("unique_obtained", clog.getUniqueObtained());
		}
		if (clog.getUniqueTotal() > 0)
		{
			root.addProperty("unique_total", clog.getUniqueTotal());
		}
		// PBs are the sync's defining cargo: RuneLite records them locally per
		// profile and no public provider serves them. Raw seconds; the site
		// owns formatting.
		if (personalBests != null && !personalBests.isEmpty())
		{
			JsonObject pbs = new JsonObject();
			for (Map.Entry<String, Double> entry : new TreeMap<>(personalBests).entrySet())
			{
				pbs.addProperty(entry.getKey(), entry.getValue());
			}
			root.add("pbs", pbs);
		}

		// Ladder cargo: the same bests keyed by vanilla's variant key with
		// team sizes SPLIT ("chambers of xeric solo" vs "... 5 players").
		// The collapsed map above stays for display compatibility; ladders
		// need the split because solo and team runs rank separately. Each
		// entry carries where this client observed it: "store" from
		// RuneLite's own pb store, "advlog" from the Counters scroll harvest.
		if (detailedPersonalBests != null && !detailedPersonalBests.isEmpty())
		{
			JsonObject detailed = new JsonObject();
			for (Map.Entry<String, DetailedPb> entry : new TreeMap<>(detailedPersonalBests).entrySet())
			{
				JsonObject record = new JsonObject();
				record.addProperty("seconds", entry.getValue().seconds);
				record.addProperty("source", entry.getValue().source);
				detailed.add(entry.getKey(), record);
			}
			root.add("pbs_detailed", detailed);
		}

		Map<Integer, ItemEntry> byId = new TreeMap<>();
		for (Map.Entry<String, List<ClogResult.ClogItem>> categoryEntry
			: clog.getObtainedItems().entrySet())
		{
			String category = categoryEntry.getKey();
			for (ClogResult.ClogItem item : categoryEntry.getValue())
			{
				ItemEntry entry = byId.computeIfAbsent(item.getId(),
					id -> new ItemEntry(id, item.getCount()));
				entry.quantity = Math.max(entry.quantity, item.getCount());
				String date = ClogDates.iso(item.getDate());
				if (date != null && (entry.obtainedAt == null || date.compareTo(entry.obtainedAt) < 0))
				{
					entry.obtainedAt = date;
				}
				if (!entry.categories.contains(category))
				{
					entry.categories.add(category);
				}
			}
		}

		JsonArray items = new JsonArray();
		for (ItemEntry entry : byId.values())
		{
			JsonObject obj = new JsonObject();
			obj.addProperty("item_id", entry.id);
			obj.addProperty("quantity", Math.max(entry.quantity, 1));
			if (entry.obtainedAt != null) obj.addProperty("obtained_at", entry.obtainedAt);
			JsonArray cats = new JsonArray();
			for (String category : new TreeSet<>(entry.categories))
			{
				cats.add(category);
			}
			obj.add("categories", cats);
			items.add(obj);
		}
		root.add("clog", items);
		root.addProperty("client_version", CLIENT_VERSION);
		return root;
	}

	/** One variant-keyed pb with the lane this client observed it through. */
	static final class DetailedPb
	{
		final double seconds;
		final String source;

		DetailedPb(double seconds, String source)
		{
			this.seconds = seconds;
			this.source = source;
		}
	}

	private static final class ItemEntry
	{
		final int id;
		int quantity;
		String obtainedAt;
		final List<String> categories = new ArrayList<>();

		ItemEntry(int id, int quantity)
		{
			this.id = id;
			this.quantity = Math.max(quantity, 1);
		}
	}
}

package com.killclog;

import net.runelite.client.config.ConfigManager;

/**
 * Sync and its two followers, Automatic sync and Publish Character Model. RuneLite can't gray a setting out,
 * so the dependency is kept at the data: the followers read off while Sync is off, and turn on with it.
 */
final class SyncSettings
{
	private final KillClogConfig config;
	private final ConfigManager configManager;

	SyncSettings(KillClogConfig config, ConfigManager configManager)
	{
		this.config = config;
		this.configManager = configManager;
	}

	/** At startup and whenever a follower changes: one ticked while Sync is off doesn't stay ticked. */
	void enforce()
	{
		if (!config.killclogSync())
		{
			if (config.automaticSync())
			{
				configManager.setConfiguration("killclog", "automaticSync", false);
			}
			if (config.characterModel())
			{
				configManager.unsetConfiguration("killclog", "characterModel");
			}
		}
	}

	/** Turning Sync on turns its followers on with it. */
	void syncTurnedOn()
	{
		configManager.unsetConfiguration("killclog", "automaticSync");
		configManager.setConfiguration("killclog", "characterModel", true);
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Consumer;
import java.util.function.IntFunction;
import javax.annotation.Nullable;
import javax.swing.JToolTip;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

/**
 * Intermediate tooltip with a titled header zone: bold title line,
 * optional subtitle (label: value), optional rank line, then separator.
 * Subclasses provide content below the separator via
 * {@link #getContentSize(int)} and {@link #paintBody(Graphics2D, int, int, int)}.
 *
 * <p>Family convention: every Compare* tooltip pairs with a solo sibling, and
 * paint/format helpers shared by a pair live package-private on the solo class,
 * never duplicated across the pair.
 */
public abstract class TitleTooltip extends NativeTooltip
{
	private static final int NAME_LINE_HEIGHT = 20;
	// The hiscore badges are 18 px art, the title line's own height.
	private static final int TITLE_ICON_MAX = 18;
	private static final int TITLE_ICON_GAP = 4;
	static final int SEPARATOR_GAP = 6;
	private static final int INFO_PAIR_GAP = 8;
	private static final String ELLIPSIS = "...";
	private static final Font TITLE_FONT = FontManager.getRunescapeBoldFont().deriveFont(18f);
	static final Font TITLE_FONT_SMALL = FontManager.getRunescapeBoldFont().deriveFont(16f);
	static final Color SEPARATOR_COLOR = new Color(80, 70, 50);

	protected static final Color CLOG_RED = new Color(255, 0, 0);
	protected static final Color CLOG_GREEN = new Color(0, 255, 0);
	protected static final Color STALE_RED = new Color(255, 60, 60);
	protected static final Color CLOG_YELLOW = new Color(255, 255, 0);
	protected static final Color COMPARE_BLUE = new Color(91, 164, 207);
	protected static final Color COMPARE_RED = new Color(224, 86, 86);
	protected static final Color MUTED_GRAY = new Color(148, 148, 148);

	@Getter(AccessLevel.PROTECTED)
	@Setter
	private String title; // the bold orange title line (always required)
	@Getter(AccessLevel.PROTECTED)
	private String titleSuffix;
	@Getter(AccessLevel.PROTECTED)
	private Color titleSuffixColor;
	private String subtitleLabel;
	// A card for a Collection Log page reads as the game's own page does: Obtained first, then its stats.
	private boolean obtainedFirst;
	private String subtitleValue;
	private Color subtitleColor;
	// The header's stat lines (KC and PB; a raid's hard mode on a second), each a label and value and maybe a pair.
	private final List<InfoLine> infoLines = new ArrayList<>();
	private String rankText;
	// A raid's hard mode ranks beside the raid on the same line.
	private String rankPairLabel;
	private String rankPairText;
	private String titleWikiPage;
	@Nullable
	private BufferedImage titleIcon;
	private boolean wikiLinksEnabled = true;
	private boolean titleHovered;
	// The way back to the card this one opened from: the card's first line, above its title, white while hovered.
	private String backLabel;
	@Nullable
	private Consumer<MouseEvent> onBack;
	private boolean backHovered;
	private int backTop = -1;
	// Item sprites on the card: hover names and wiki links. Installed after the
	// title's own listeners, as the cards' own copies were.
	final TooltipItemHover itemHover;

	protected TitleTooltip()
	{
		installTitleLinkHandlers();
		itemHover = new TooltipItemHover(this);
	}

	/** Optional colored text painted immediately after the main title. */
	protected void setTitleSuffix(String titleSuffix, Color color)
	{
		this.titleSuffix = titleSuffix;
		this.titleSuffixColor = color;
	}

	protected void clearTitleSuffix()
	{
		titleSuffix = null;
		titleSuffixColor = null;
	}

	/**
	 * Optional badge before the title, drawn at its own size: art no taller than the title's line
	 * stays crisp, and anything taller is scaled down to fit it.
	 */
	protected void setTitleIcon(@Nullable BufferedImage icon)
	{
		if (icon != null && icon.getHeight() > TITLE_ICON_MAX)
		{
			int width = Math.max(1, (int) Math.round((double) icon.getWidth() / icon.getHeight() * TITLE_ICON_MAX));
			icon = ImageUtil.resizeImage(icon, width, TITLE_ICON_MAX);
		}
		titleIcon = icon;
	}

	/**
	 * An image in the header's right corner, every header line kept clear of it: the Collection Log's current tier, a
	 * published character's prestige cape. The room is kept whether or not the image has loaded yet, so the card
	 * never changes size when it arrives. With a name, hovering it shows the name in the card's band.
	 */
	CardBody.Part headerCorner(boolean keepRoom, @Nullable BufferedImage image, @Nullable String name)
	{
		return CardBody.row(0, c -> keepRoom ? headerTextWidth() + 40 : 0, (c, y) ->
		{
			if (image == null)
			{
				return;
			}
			int x = c.w - c.inset() - image.getWidth();
			int top = c.inset() + (getHeaderHeight() - image.getHeight()) / 2;
			c.g.drawImage(image, x, top, null);
			if (name != null)
			{
				c.hits.add(new TooltipItemHover.HitBox(9, 0, name, new Rectangle(x, top, image.getWidth(), image.getHeight()), true));
			}
		});
	}

	private int titleIconWidth()
	{
		return titleIcon != null ? titleIcon.getWidth() + TITLE_ICON_GAP : 0;
	}

	/** The card's first line, above its title, leads back to the card this one opened from. */
	void setBack(String label, Consumer<MouseEvent> onBack)
	{
		backLabel = label;
		this.onBack = onBack;
	}

	/** The way back on a card, or on both cards of a comparison. */
	static JToolTip withBack(JToolTip tip, String label, Consumer<MouseEvent> onBack)
	{
		for (JToolTip card : tip instanceof SideBySideTooltip ? ((SideBySideTooltip) tip).sides() : new JToolTip[]{tip})
		{
			if (card instanceof TitleTooltip)
			{
				((TitleTooltip) card).setBack(label, onBack);
			}
		}
		return tip;
	}

	/** Optional OSRS Wiki page opened when the title is clicked. */
	public void setTitleWikiPage(String titleWikiPage)
	{
		this.titleWikiPage = titleWikiPage;
		titleHovered = false;
	}

	public void setWikiLinksEnabled(boolean wikiLinksEnabled)
	{
		this.wikiLinksEnabled = wikiLinksEnabled;
		itemHover.setWikiLinksEnabled(wikiLinksEnabled);
		if (!wikiLinksEnabled && titleHovered)
		{
			titleHovered = false;
			repaint();
		}
	}

	/**
	 * Set a subtitle line: label in orange, value in the given color.
	 */
	public void setSubtitle(String label, String value, Color valueColor)
	{
		this.subtitleLabel = label;
		this.subtitleValue = value;
		this.subtitleColor = valueColor;
	}

	protected void clearSubtitle()
	{
		subtitleLabel = null;
		subtitleValue = null;
		subtitleColor = null;
	}

	/**
	 * Set the obtained subtitle line. Pass -1 for unknown ("?/Y").
	 * Color follows native OSRS stoplight progress: red, yellow, green.
	 */
	public void setObtained(int obtained, int total)
	{
		setSubtitle(obtainedLabel(), progressCountText(obtained, total), completionColor(obtained, total));
	}

	/** The count's label; the Collection Log card counts the whole log, not one page. */
	protected String obtainedLabel()
	{
		return "Obtained: ";
	}

	/**
	 * Empty-state obtained line: the shape of the data with no player in it.
	 * Muted gray so the preview never reads as a score.
	 */
	public void setObtainedPlaceholder(int total)
	{
		setSubtitle(obtainedLabel(), progressPlaceholderText(total), MUTED_GRAY);
	}

	protected static String progressPlaceholderText(int total)
	{
		return "--/" + (total >= 0 ? String.valueOf(total) : "?");
	}

	/** Native OSRS stoplight progress color: red for none, yellow for some, green for complete. */
	protected static Color completionColor(int obtained, int total)
	{
		if (obtained >= total && total > 0)
		{
			return CLOG_GREEN;
		}
		if (obtained == 0 && total > 0)
		{
			return CLOG_RED;
		}
		return CLOG_YELLOW;
	}

	protected static String progressCountText(int obtained, int total)
	{
		return (obtained < 0 ? "?" : String.valueOf(obtained))
			+ "/" + (total < 0 ? "?" : String.valueOf(total));
	}

	protected static String wrappedProgressCountText(int obtained, int total)
	{
		return " (" + progressCountText(obtained, total) + ")";
	}

	protected static int wrappedProgressCountWidth(FontMetrics fm, int obtained, int total)
	{
		return fm.stringWidth(wrappedProgressCountText(obtained, total));
	}

	protected static int paintWrappedProgressCount(Graphics2D g2, FontMetrics fm, int x, int y,
		int obtained, int total)
	{
		String progress = wrappedProgressCountText(obtained, total);
		g2.setColor(completionColor(obtained, total));
		g2.drawString(progress, x, y);
		return x + fm.stringWidth(progress);
	}

	/** A thousands-grouped count, the game's way: 1,234,567. */
	static String grouped(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	/** Value-column text: a thousands-grouped count, or "--" when absent. */
	protected static String scoreText(long value)
	{
		return value > 0 ? grouped(value) : "--";
	}

	/** Rank tail that flows after a score column, e.g. " #1,234,567". */
	protected static String rankTailText(int rank)
	{
		return " #" + grouped(rank);
	}

	/** Efficient-hours text: one decimal, thousands-grouped, "--" when absent. */
	protected static String ehbText(double hours)
	{
		return hours >= 0 ? String.format(Locale.US, "%,.1f", hours) : "--";
	}

	/**
	 * Widest rendered width across actual values under the given formatter.
	 * Sizing measures the strings it will paint, never a placeholder.
	 */
	protected static int widestValue(FontMetrics fm, int[] values, IntFunction<String> fmt)
	{
		int width = 0;
		for (int value : values)
		{
			width = Math.max(width, fm.stringWidth(fmt.apply(value)));
		}
		return width;
	}

	/** Draw text so its right edge lands at rightX (right-aligned value column). */
	protected static void drawRightAligned(Graphics2D g2, FontMetrics fm, String text, int rightX, int y)
	{
		g2.drawString(text, rightX - fm.stringWidth(text), y);
	}

	protected static String tierDisplayName(CombatAchievementResult ca)
	{
		CombatAchievementTier tier = ca != null ? ca.getTier() : null;
		return tier != null ? tier.name().charAt(0) + tier.name().substring(1).toLowerCase() : "None";
	}

	protected static int separatorHeight(int pad)
	{
		return pad + 1 + pad;
	}

	protected int paintSeparator(Graphics2D g2, int w, int y, int pad)
	{
		int inset = getInset();
		y += pad;
		g2.setColor(SEPARATOR_COLOR);
		g2.drawLine(inset, y, w - inset - 1, y);
		return y + 1 + pad;
	}

	static final int SUBHEADER_HEIGHT = 16;

	/** A bold orange subheader, the small font handed back after; returns the Y under it. */
	int paintSubheader(Graphics2D g2, int y, String text)
	{
		g2.setFont(FontManager.getRunescapeBoldFont());
		g2.setColor(OSRS_ORANGE);
		g2.drawString(text, getInset(), y + g2.getFontMetrics().getAscent());
		g2.setFont(FontManager.getRunescapeSmallFont());
		return y + SUBHEADER_HEIGHT;
	}

	static int drawLabelValue(Graphics2D g2, FontMetrics fm, int x, int y,
		String label, String value)
	{
		return drawLabelValue(g2, fm, x, y, label, value, Color.WHITE);
	}

	/** An orange label with its value right after it; returns the pair's width. */
	static int drawLabelValue(Graphics2D g2, FontMetrics fm, int x, int y,
		String label, String value, Color valueColor)
	{
		return drawLabelValue(g2, fm, x, y, label, value, OSRS_ORANGE, valueColor);
	}

	/** A label in its own color (white on a hovered row) with its value right after it. */
	static int drawLabelValue(Graphics2D g2, FontMetrics fm, int x, int y,
		String label, String value, Color labelColor, Color valueColor)
	{
		g2.setColor(labelColor);
		g2.drawString(label, x, y);
		int labelWidth = fm.stringWidth(label);
		g2.setColor(valueColor);
		g2.drawString(value, x + labelWidth, y);
		return labelWidth + fm.stringWidth(value);
	}

	/** Set the info line under the title, in place of any before it. Label in orange, value in given color. */
	public void setInfoLine(String label, String value, Color valueColor)
	{
		infoLines.clear();
		addInfoLine(label, value, valueColor);
	}

	/** One more info line under the last. */
	void addInfoLine(String label, String value, Color valueColor)
	{
		infoLines.add(new InfoLine(label, value, valueColor));
	}

	/** Optional second label+value pair painted after the first on the last info line. */
	public void setInfoLinePair(String label, String value, Color valueColor)
	{
		if (!infoLines.isEmpty())
		{
			infoLines.get(infoLines.size() - 1).pair = new InfoLine(label, value, valueColor);
		}
	}

	/** A label and value in the header's info lines, and the pair painted after it. */
	private static final class InfoLine
	{
		private final String label;
		private final String value;
		private final Color color;
		@Nullable
		private InfoLine pair;

		private InfoLine(String label, String value, Color color)
		{
			this.label = label;
			this.value = value;
			this.color = color;
		}

		private int width(FontMetrics fm)
		{
			return fm.stringWidth(label + value) + (pair != null ? INFO_PAIR_GAP + pair.width(fm) : 0);
		}
	}

	/** A second rank after the first on the rank line, as a raid's hard mode ranks beside the raid. */
	void setRankPair(String label, int rank)
	{
		rankPairLabel = label;
		rankPairText = rank > 0 ? grouped(rank) : "Unranked";
	}

	/** Leads the header with the Obtained line, as the game's Collection Log pages do. */
	void setObtainedFirst(boolean obtainedFirst)
	{
		this.obtainedFirst = obtainedFirst;
	}

	/** Set the rank line. 0 = "Unranked". */
	public void setRank(int rank)
	{
		if (rank > 0)
		{
			this.rankText = grouped(rank);
		}
		else
		{
			this.rankText = "Unranked";
		}
	}

	/** Override in subclasses that need a smaller title font. */
	protected Font getTitleFont()
	{
		return TITLE_FONT;
	}

	protected String getHeaderHoverLineText()
	{
		return itemHover.hoveredItemName();
	}

	protected Color getHeaderHoverLineColor()
	{
		return itemHover.hoveredItemObtained() ? CLOG_GREEN : CLOG_RED;
	}

	private static String fitHeaderText(FontMetrics fm, String text, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}

		int ellipsisWidth = fm.stringWidth(ELLIPSIS);
		if (ellipsisWidth >= maxWidth)
		{
			return "";
		}

		StringBuilder out = new StringBuilder(text);
		while (out.length() > 0 && fm.stringWidth(out.toString()) + ellipsisWidth > maxWidth)
		{
			out.deleteCharAt(out.length() - 1);
		}
		return out + ELLIPSIS;
	}

	/**
	 * Number of pixel rows the header occupies (title + optional lines).
	 * Does not include the separator gap below.
	 */
	int getHeaderHeight()
	{
		int h = NAME_LINE_HEIGHT;
		if (subtitleLabel != null)
		{
			h += LINE_HEIGHT;
		}
		h += infoLines.size() * LINE_HEIGHT;
		if (rankText != null)
		{
			h += LINE_HEIGHT;
		}
		if (onBack != null)
		{
			h += LINE_HEIGHT;
		}
		return h;
	}

	/**
	 * Total header zone height including separator line and gaps.
	 * Content starts at inset + this value.
	 */
	protected int getHeaderZoneHeight()
	{
		return getHeaderHeight() + SEPARATOR_GAP + 1 + SEPARATOR_GAP;
	}

	/** The scroll window of a card that has one. */
	@Nullable
	CardBody.Scroll scroll()
	{
		return null;
	}

	/** A comparison's two cards scroll as one wherever both can. */
	static void scrollTogether(JToolTip blue, JToolTip red)
	{
		CardBody.Scroll left = blue instanceof TitleTooltip ? ((TitleTooltip) blue).scroll() : null;
		CardBody.Scroll right = red instanceof TitleTooltip ? ((TitleTooltip) red).scroll() : null;
		if (left != null && right != null)
		{
			left.scrollWith(right);
		}
	}

	/** The card's body as parts; a card that lists its body needs no sizing or painting of its own. */
	protected CardBody body()
	{
		return new CardBody();
	}

	/**
	 * Return the content dimensions given the available width.
	 * The availableWidth accounts for the header-driven minimum width, so subclasses
	 * can wrap content to fill the space.
	 */
	protected Dimension getContentSize(int availableWidth)
	{
		return body().size(this, availableWidth);
	}

	/**
	 * Paint the body content starting at the given Y coordinate (below separator).
	 */
	protected void paintBody(Graphics2D g2, int w, int h, int startY)
	{
		itemHover.setHitBoxes(body().paint(this, g2, w, startY));
	}

	@Override
	public Dimension getPreferredSize()
	{
		int inset = getInset();

		// Header text widths drive minimum tooltip width.
		// The full header width flows to getContentSize so grids can fill the space.
		int headerMinWidth = headerTextWidth();

		Dimension contentSize = getContentSize(Math.max(headerMinWidth, 1));

		int contentWidth = Math.max(headerMinWidth, contentSize.width);
		// The body paints at the card's final width, where a grid may take another column: measured there too.
		int totalHeight = inset + getHeaderZoneHeight() + getContentSize(contentWidth).height + inset;
		int totalWidth = contentWidth + inset * 2;

		return new Dimension(totalWidth, totalHeight);
	}

	/** The widest header line: the card is never narrower, and a corner image keeps clear of every line. */
	private int headerTextWidth()
	{
		FontMetrics nfm = getFontMetrics(getTitleFont());
		FontMetrics sfm = getFontMetrics(FontManager.getRunescapeSmallFont());
		int titleTextWidth = title != null ? titleIconWidth() + nfm.stringWidth(title) : 0;
		if (titleSuffix != null)
		{
			titleTextWidth += nfm.stringWidth(titleSuffix);
		}
		int subTextWidth = subtitleLabel != null
			? sfm.stringWidth(subtitleLabel + subtitleValue) : 0;
		int infoTextWidth = 0;
		for (InfoLine line : infoLines)
		{
			infoTextWidth = Math.max(infoTextWidth, line.width(sfm));
		}
		int rnkTextWidth = rankText != null ? sfm.stringWidth("Rank: " + rankText) : 0;
		if (rankText != null && rankPairLabel != null)
		{
			rnkTextWidth += INFO_PAIR_GAP + sfm.stringWidth(rankPairLabel + rankPairText);
		}
		int maxTextWidth = Math.max(titleTextWidth,
			Math.max(subTextWidth, Math.max(infoTextWidth, rnkTextWidth)));
		if (onBack != null)
		{
			maxTextWidth = Math.max(maxTextWidth, sfm.stringWidth(backLabel));
		}
		return maxTextWidth;
	}

	@Override
	protected void paintContent(Graphics2D g2, int w, int h)
	{
		int startY = paintHeader(g2, w);
		paintBody(g2, w, h, startY);
	}

	/**
	 * Paint the header (title, optional subtitle, optional rank, separator).
	 * Returns the Y coordinate where body content should start.
	 */
	int paintHeader(Graphics2D g2, int w)
	{
		if (title == null)
		{
			return getInset();
		}

		int inset = getInset();
		// The way back leads the card, top left above the title.
		int top = inset;
		if (onBack != null)
		{
			g2.setFont(FontManager.getRunescapeSmallFont());
			g2.setColor(backHovered ? Color.WHITE : OSRS_ORANGE);
			g2.drawString(backLabel, inset, inset + g2.getFontMetrics().getAscent());
			backTop = inset;
			top += LINE_HEIGHT;
		}
		// Modal titles remain stable while body labels change.
		String headerTitle = title;
		Color headerColor = titleColor();
		boolean showTitleSuffix = titleSuffix != null;
		g2.setFont(getTitleFont());
		FontMetrics nfm = g2.getFontMetrics();
		int lineY = top + nfm.getAscent();
		int titleBaseline = lineY;
		g2.setColor(headerColor);
		// Long reveal texts (recent-item names) ellipsize instead of clipping.
		int suffixWidth = showTitleSuffix ? nfm.stringWidth(titleSuffix) : 0;
		int titleX = inset + titleIconWidth();
		if (titleIcon != null)
		{
			// Centered on the title's line, lifted a pixel to sit level with the letters.
			g2.drawImage(titleIcon, inset, top + (NAME_LINE_HEIGHT - titleIcon.getHeight()) / 2 - 1, null);
		}
		headerTitle = fitHeaderText(nfm, headerTitle,
			w - inset - titleX - suffixWidth);
		g2.drawString(headerTitle, titleX, lineY);
		if (showTitleSuffix)
		{
			g2.setColor(titleSuffixColor != null ? titleSuffixColor : OSRS_ORANGE);
			g2.drawString(titleSuffix, titleX + nfm.stringWidth(headerTitle), lineY);
		}

		g2.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g2.getFontMetrics();

		// Header line order: stats read first (KC/PB info line, then rank),
		// clog progress reads last. The first line under the title keeps the
		// wider gap the larger title font needs.

		if (obtainedFirst && subtitleLabel != null)
		{
			lineY += lineY == titleBaseline ? NAME_LINE_HEIGHT : LINE_HEIGHT;
			drawLabelValue(g2, fm, inset, lineY, subtitleLabel, subtitleValue, subtitleColor);
		}

		// Info lines (KC/PB for boss cells, a raid's hard mode under them, Kills for unsynced)
		for (InfoLine line : infoLines)
		{
			lineY += lineY == titleBaseline ? NAME_LINE_HEIGHT : LINE_HEIGHT;
			int infoWidth = drawLabelValue(g2, fm, inset, lineY, line.label, line.value, line.color);
			if (line.pair != null)
			{
				drawLabelValue(g2, fm, inset + infoWidth + INFO_PAIR_GAP, lineY, line.pair.label, line.pair.value,
					line.pair.color);
			}
		}

		// Rank line
		if (rankText != null)
		{
			lineY += lineY == titleBaseline ? NAME_LINE_HEIGHT : LINE_HEIGHT;
			int rankWidth = drawLabelValue(g2, fm, inset, lineY, "Rank: ", rankText,
				"Unranked".equals(rankText) ? OSRS_ORANGE : Color.WHITE);
			if (rankPairLabel != null)
			{
				drawLabelValue(g2, fm, inset + rankWidth + INFO_PAIR_GAP, lineY, rankPairLabel, rankPairText,
					"Unranked".equals(rankPairText) ? OSRS_ORANGE : Color.WHITE);
			}
		}

		// Subtitle (label in orange, value in subtitleColor)
		if (!obtainedFirst && subtitleLabel != null)
		{
			lineY += lineY == titleBaseline ? NAME_LINE_HEIGHT : LINE_HEIGHT;
			drawLabelValue(g2, fm, inset, lineY, subtitleLabel, subtitleValue, subtitleColor);
		}

		// Separator
		int sepY = lineY + SEPARATOR_GAP;
		g2.setColor(SEPARATOR_COLOR);
		g2.drawLine(inset, sepY, w - inset - 1, sepY);

		return sepY + 1 + SEPARATOR_GAP;
	}

	/** Room above and below the label, shared by sprite-section readouts. */
	static int hoverRowHeight(FontMetrics fm)
	{
		return fm.getHeight() + 4;
	}

	protected final void paintHeaderHoverLine(Graphics2D g2, FontMetrics fm, int w, int baseline)
	{
		String itemName = getHeaderHoverLineText();
		if (itemName != null && !itemName.isEmpty())
		{
			g2.setColor(getHeaderHoverLineColor());
			g2.drawString(fitHeaderText(fm, itemName, w - getInset() * 2), getInset(), baseline + 2);
		}
	}

	private void installTitleLinkHandlers()
	{
		addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				updateHeaderHover(e.getX(), e.getY());
			}
		});
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1 && onBack != null && onBackRow(e.getY()))
				{
					onBack.accept(e);
					e.consume();
					return;
				}
				if (e.getButton() == MouseEvent.BUTTON1 && titleLinkActive()
					&& titleBounds().contains(e.getX(), e.getY()))
				{
					TooltipItemLink.openWikiPage(titleWikiPage);
					titleHovered = false;
					NativeTooltip.hideTooltipTree(TitleTooltip.this);
					e.consume();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (titleHovered || backHovered)
				{
					titleHovered = false;
					backHovered = false;
					repaint();
				}
			}
		});
	}

	private void updateHeaderHover(int x, int y)
	{
		boolean nextTitle = titleLinkActive() && titleBounds().contains(x, y);
		boolean nextBack = onBack != null && onBackRow(y);
		if (nextTitle != titleHovered || nextBack != backHovered)
		{
			titleHovered = nextTitle;
			backHovered = nextBack;
			repaint();
		}
	}

	/** The back line answers across the card's whole width, a row like the others. */
	boolean onBackRow(int y)
	{
		return backTop >= 0 && y >= backTop && y < backTop + LINE_HEIGHT;
	}

	private boolean titleLinkActive()
	{
		return wikiLinksEnabled && titleWikiPage != null && !titleWikiPage.trim().isEmpty();
	}

	protected Color titleColor()
	{
		return titleHovered && titleLinkActive() ? Color.WHITE : OSRS_ORANGE;
	}

	private Rectangle titleBounds()
	{
		int inset = getInset();
		int width = title != null ? getFontMetrics(getTitleFont()).stringWidth(title) : 0;
		return new Rectangle(inset + titleIconWidth(), inset + (onBack != null ? LINE_HEIGHT : 0), width,
			NAME_LINE_HEIGHT);
	}
}

package com.killclog;

import java.awt.AWTEvent;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.event.AWTEventListener;
import java.awt.event.HierarchyEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseListener;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Set;
import java.util.WeakHashMap;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToolTip;
import javax.swing.Popup;
import javax.swing.PopupFactory;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.ToolTipManager;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * Manages tooltip display mechanics: pinned popups, cell hover effects,
 * and component-scoped ToolTipManager registration.
 */
class TooltipController
{
	static final Border CELL_BORDER = new EmptyBorder(1, 1, 1, 1);
	private static final Color HOVER_OUTLINE_DIM = new Color(90, 90, 90);
	private static final Color HOVER_TINT_BG = new Color(41, 41, 41);
	private static final Color KC_COLOR = KillClogPanel.KC_COLOR;

	private final KillClogConfig config;

	// Stable popup state. Click mode opens this directly; hover mode promotes its
	// transient preview into the same popup when the source is pressed.
	private Popup activePinnedPopup;
	private JComponent activePinnedComponent;
	private JPanel activePinnedCell;
	private boolean pinnedFromHover;
	private JComponent suppressedTooltipComponent;
	private String suppressedTooltipText;
	private AWTEventListener pinDismissListener;
	private JComponent pinDismissedComponent;
	private Window focusWindow;
	private WindowAdapter windowFocusListener;

	// Cell hover state. Only the panel's own cells take the outline; a card pinned under another
	// surface, like the info row the Collection Log card opens from, leaves that surface as it is.
	private JPanel hoveredCell;
	private final Set<JPanel> hoverCells = Collections.newSetFromMap(new WeakHashMap<>());
	private Timer hoverExitTimer;

	// ToolTipManager is shared by every RuneLite plugin. Track only Kill Clog's
	// components so click mode never changes another plugin's tooltip behavior.
	private final Set<JComponent> tooltipComponents =
		Collections.newSetFromMap(new WeakHashMap<>());

	TooltipController(KillClogConfig config)
	{
		this.config = config;
	}

	/**
	 * Wire hover effect onto a cell panel.
	 * Shows outline or tint on hover, handles click-to-reveal.
	 * 150ms debounced exit keeps the effect while tooltip is open.
	 */
	void addCellHoverEffect(JPanel cell, JLabel label)
	{
		addCellHoverEffect(cell, label, label);
	}

	/**
	 * Row-shaped variant: the hover outline follows {@code colorSource}'s
	 * foreground while the cell and every listed surface accept hover and
	 * click. The pinned tooltip comes from the pressed surface when it carries
	 * one, else from the first surface (which also keeps the popup anchor
	 * stable for presses on the bare cell).
	 */
	void addCellHoverEffect(JPanel cell, JLabel colorSource, JLabel... surfaces)
	{
		MouseAdapter hoverAdapter = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				JLabel source = e.getSource() instanceof JLabel
					&& ((JLabel) e.getSource()).getToolTipText() != null
					? (JLabel) e.getSource() : surfaces[0];
				if (source.getToolTipText() != null)
				{
					pinTooltipFromPress(source, cell, e);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (hoverExitTimer != null) hoverExitTimer.stop();
				hoverCell(cell, colorSource);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (hoverExitTimer != null) hoverExitTimer.stop();
				hoverExitTimer = new Timer(150, evt ->
				{
					if (hoveredCell == cell
						&& !(pinnedFromHover && activePinnedCell == cell))
					{
						resetCellHover();
						hoveredCell = null;
					}
				});
				hoverExitTimer.setRepeats(false);
				hoverExitTimer.start();
			}
		};
		hoverCells.add(cell);
		cell.addMouseListener(hoverAdapter);
		for (JLabel surface : surfaces)
		{
			surface.addMouseListener(hoverAdapter);
			trackTooltipComponent(surface);
		}
	}

	void trackTooltipComponent(JComponent component)
	{
		if (tooltipComponents.add(component))
		{
			component.addPropertyChangeListener("ToolTipText", event ->
				SwingUtilities.invokeLater(() -> applyTooltipMode(component)));
		}
		applyTooltipMode(component);
	}

	/**
	 * Update a tracked tooltip and immediately reapply this controller's
	 * registration rule. Swing otherwise re-registers null-to-value changes
	 * even while another tooltip is pinned.
	 */
	void setTooltipText(JComponent component, String tooltipText)
	{
		component.setToolTipText(tooltipText);
		applyTooltipMode(component);
	}

	void onTooltipModeChanged()
	{
		hideTransientTooltipState();
		refreshTooltipRegistrations();
	}

	void resetCellHover()
	{
		if (hoveredCell != null)
		{
			hoveredCell.setBorder(CELL_BORDER);
			hoveredCell.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		}
	}

	/**
	 * Wire mouse + hierarchy listeners on a tooltip to clear the parent cell's hover
	 * when the tooltip hides. Listeners attach to the tooltip and its children
	 * (a side-by-side comparison tooltip hosts two live child tooltips), and the
	 * exit handler checks position so crossing between the composite and a child
	 * never reads as leaving the tooltip.
	 */
	void keepTooltipOnHover(JToolTip tip, JPanel parentCell)
	{
		attachToTipTree(tip, new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (hoverExitTimer != null) hoverExitTimer.stop();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Guard against the WHOLE tooltip: a child card's exit while
				// crossing into its sibling must not read as leaving.
				if (((JToolTip) NativeTooltip.tooltipRoot(tip)).getMousePosition(true) != null)
				{
					return;
				}
				clearCellHover(parentCell);
			}
		});
		tip.addHierarchyListener(e ->
		{
			if ((e.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0 && !tip.isShowing())
			{
				clearCellHover(parentCell);
			}
		});
	}

	private static void attachToTipTree(JToolTip tip, MouseListener listener)
	{
		tip.addMouseListener(listener);
		for (Component child : tip.getComponents())
		{
			child.addMouseListener(listener);
		}
	}

	void pinTooltipFromPress(JComponent source, JPanel cell, MouseEvent event)
	{
		if (config.tooltipMode() == TooltipMode.HOVER)
		{
			dismissHoverPreview(event);
		}
		showPinnedTooltip(source, cell);
	}

	/**
	 * A press inside one modal that opens another in its place, the way a rare
	 * row opens its collection from the Clue Summary. The hover preview is a
	 * window of its own and has to be taken down like any other press does, and
	 * the cell keeps the outline that modal's closing just cleared.
	 */
	void pinTooltipFromPress(JComponent source, JPanel cell, MouseEvent event, JToolTip tip)
	{
		if (config.tooltipMode() == TooltipMode.HOVER)
		{
			dismissHoverPreview(event);
		}
		pinTooltip(source, cell, tip);
		if (hoverCells.contains(cell))
		{
			hoverCell(cell, source);
		}
	}

	private void hoverCell(JPanel cell, JComponent colorSource)
	{
		if (hoveredCell == cell) return;

		if (hoveredCell != null) resetCellHover();

		hoveredCell = cell;
		switch (config.hoverStyle())
		{
			case OUTLINE:
				Color fg = colorSource.getForeground();
				Color outline = (fg.equals(KC_COLOR) || fg.equals(ColorScheme.LIGHT_GRAY_COLOR))
					? HOVER_OUTLINE_DIM : fg;
				cell.setBorder(new MatteBorder(1, 1, 1, 1, outline));
				break;
			case TINT:
				cell.setBackground(HOVER_TINT_BG);
				break;
			case NONE:
				break;
		}
	}

	void dismissHoverPreview(MouseEvent event)
	{
		ToolTipManager.sharedInstance().mousePressed(event);
	}

	/** Pin the tooltip for any component with tooltip text (labels included). */
	void showPinnedTooltip(JComponent source, JPanel cell)
	{
		// The global listener dismissed this component on the same click; treat it as toggle-off.
		if (source == pinDismissedComponent)
		{
			pinDismissedComponent = null;
			return;
		}
		pinTooltip(source, cell, source.createToolTip());
	}

	/**
	 * Pin a specific modal on a cell: how one modal opens another in its place.
	 * It skips the toggle-off check above, because the press that asked for this
	 * is the same press that just dismissed the modal it came from.
	 */
	void pinTooltip(JComponent source, JPanel cell, JToolTip tip)
	{
		// A row pressed in a preview that outlived its panel has nowhere to open.
		if (!source.isShowing())
		{
			return;
		}
		pinDismissedComponent = null;

		hidePinnedTooltip();

		String tooltipText = source.getToolTipText();
		tip.setTipText(tooltipText);
		guardPinnedTooltip(tip);

		Dimension tipSize = tip.getPreferredSize();

		Point sourceLoc = source.getLocationOnScreen();
		Point cellLoc = cell.getLocationOnScreen();
		Rectangle screen = cell.getGraphicsConfiguration().getBounds();

		int x = sourceLoc.x;
		int y = cellLoc.y + cell.getHeight();

		if (x + tipSize.width > screen.x + screen.width)
		{
			x = screen.x + screen.width - tipSize.width;
		}
		if (y + tipSize.height > screen.y + screen.height)
		{
			y = cellLoc.y - tipSize.height;
		}
		// Wide side-by-side tooltips must stay reachable: clamp the top and
		// left edges too, like the hover path does.
		x = Math.max(x, screen.x);
		y = Math.max(y, screen.y);

		activePinnedPopup = PopupFactory.getSharedInstance().getPopup(cell, tip, x, y);
		activePinnedComponent = source;
		activePinnedCell = cell;
		pinnedFromHover = config.tooltipMode() == TooltipMode.HOVER;
		suppressPinnedSourceTooltip(source, tooltipText);
		activePinnedPopup.show();
		refreshTooltipRegistrations();

		pinDismissListener = event ->
		{
			if (event.getID() == MouseEvent.MOUSE_PRESSED)
			{
				JComponent dismissedComponent = activePinnedComponent;
				pinDismissedComponent = dismissedComponent;
				hidePinnedTooltip();
				SwingUtilities.invokeLater(() ->
				{
					if (pinDismissedComponent == dismissedComponent)
					{
						pinDismissedComponent = null;
					}
				});
			}
			else if (event.getID() == KeyEvent.KEY_PRESSED
				&& ((KeyEvent) event).getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				pinDismissedComponent = null;
				hidePinnedTooltip();
			}
		};
		Toolkit.getDefaultToolkit().addAWTEventListener(
			pinDismissListener, AWTEvent.MOUSE_EVENT_MASK | AWTEvent.KEY_EVENT_MASK);
	}

	void hidePinnedTooltip()
	{
		JPanel pinnedCell = activePinnedCell;
		boolean clearPinnedHover = pinnedFromHover;
		boolean hadPopup = activePinnedPopup != null;

		if (pinDismissListener != null)
		{
			Toolkit.getDefaultToolkit().removeAWTEventListener(pinDismissListener);
			pinDismissListener = null;
		}
		if (activePinnedPopup != null)
		{
			activePinnedPopup.hide();
			activePinnedPopup = null;
		}
		activePinnedComponent = null;
		activePinnedCell = null;
		pinnedFromHover = false;
		restorePinnedSourceTooltip();

		if (hadPopup)
		{
			refreshTooltipRegistrations();
		}
		if (clearPinnedHover && pinnedCell != null)
		{
			clearCellHover(pinnedCell);
		}
	}

	/** Dismiss only when a refresh is replacing the pinned tooltip's own source. */
	void hidePinnedTooltipIfOwnedBy(JComponent source)
	{
		if (activePinnedComponent == source)
		{
			hidePinnedTooltip();
		}
	}

	void guardPinnedTooltip(JToolTip tip)
	{
		attachToTipTree(tip, new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent event)
			{
				dismissHoverPreview(event);
			}
		});
	}

	void suppressPinnedSourceTooltip(JComponent component, String tooltipText)
	{
		suppressedTooltipComponent = component;
		suppressedTooltipText = tooltipText;
		setTooltipText(component, null);
	}

	void restorePinnedSourceTooltip()
	{
		JComponent component = suppressedTooltipComponent;
		String tooltipText = suppressedTooltipText;
		suppressedTooltipComponent = null;
		suppressedTooltipText = null;
		if (component != null && component.getToolTipText() == null)
		{
			setTooltipText(component, tooltipText);
		}
	}

	void activate(Component owner)
	{
		onTooltipModeChanged();
		installWindowFocusListener(owner);
	}

	void deactivate()
	{
		hideTransientTooltipState();
		uninstallWindowFocusListener();
	}

	void clearHoveredCell()
	{
		if (hoverExitTimer != null)
		{
			hoverExitTimer.stop();
			hoverExitTimer = null;
		}
		resetCellHover();
		hoveredCell = null;
	}

	private void clearCellHover(JPanel cell)
	{
		if (hoveredCell == cell)
		{
			if (pinnedFromHover && activePinnedCell == cell)
			{
				return;
			}
			Point mouse = cell.getMousePosition();
			if (mouse != null)
			{
				return;
			}
			resetCellHover();
			hoveredCell = null;
		}
	}

	private void applyTooltipMode(JComponent component)
	{
		ToolTipManager manager = ToolTipManager.sharedInstance();
		boolean registered = false;
		for (MouseListener listener : component.getMouseListeners())
		{
			if (listener == manager)
			{
				registered = true;
				break;
			}
		}

		boolean shouldRegister = config.tooltipMode() == TooltipMode.HOVER
			&& !hasPinnedTooltip()
			&& component.getToolTipText() != null;
		if (shouldRegister && !registered)
		{
			manager.registerComponent(component);
		}
		else if (!shouldRegister && registered)
		{
			manager.unregisterComponent(component);
		}
	}

	boolean hasPinnedTooltip()
	{
		return activePinnedPopup != null;
	}

	private void refreshTooltipRegistrations()
	{
		for (JComponent component : new ArrayList<>(tooltipComponents))
		{
			applyTooltipMode(component);
		}
	}

	private void installWindowFocusListener(Component owner)
	{
		if (owner == null)
		{
			return;
		}
		Window window = SwingUtilities.getWindowAncestor(owner);
		if (window == null)
		{
			return;
		}
		if (focusWindow == window && windowFocusListener != null)
		{
			return;
		}
		uninstallWindowFocusListener();
		focusWindow = window;
		windowFocusListener = new WindowAdapter()
		{
			@Override
			public void windowLostFocus(WindowEvent e)
			{
				hideTransientTooltipState();
			}
		};
		window.addWindowFocusListener(windowFocusListener);
	}

	private void uninstallWindowFocusListener()
	{
		if (focusWindow != null && windowFocusListener != null)
		{
			focusWindow.removeWindowFocusListener(windowFocusListener);
		}
		focusWindow = null;
		windowFocusListener = null;
	}

	private void hideTransientTooltipState()
	{
		hidePinnedTooltip();
		clearHoveredCell();
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Builder;

/** Immutable data holder for sprite tooltip content. */
@Builder(toBuilder = true)
final class TooltipData
{
	final String name;
	@Builder.Default
	final int rank = -1;
	/** -1 means unsynced; the default keeps an omission from faking a synced state. */
	@Builder.Default
	final int obtainedCount = -1;
	final int totalItems;
	@Builder.Default
	final boolean rankTracked = true;
	final String statLabel;
	@Builder.Default
	final int statValue = -1;
	final List<Integer> allItemIds;
	final Set<Integer> obtainedIds;
	final Map<Integer, Integer> obtainedCounts;
	@Builder.Default
	final Map<Integer, String> itemNames = Collections.emptyMap();
	/** Boss kill count for the KC/PB header line, -1 when unknown. */
	@Builder.Default
	final int kc = -1;
	/** That line's label where it is not "KC: ", as a clue card's "Master clues completed: ". */
	final String kcLabel;
	/** The local player's recorded personal best for the KC/PB header line, null when none. */
	final String pb;
	/** A raid's hard mode on the raid's card, a second KC/PB line and a second rank: its name, KC, PB and rank. */
	final String hardLabel;
	@Builder.Default
	final int hardKc = -1;
	final String hardPb;
	@Builder.Default
	final int hardRank = -1;

	static List<Integer> itemList(int[] itemIds)
	{
		List<Integer> items = new ArrayList<>(itemIds.length);
		for (int itemId : itemIds)
		{
			items.add(itemId);
		}
		return items;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.UnaryOperator;
import javax.annotation.Nullable;
import net.runelite.client.game.ItemManager;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Builds {@link TooltipData} objects from a {@link ClogResult} without touching any UI.
 */
final class TooltipDataBuilder
{
	private final ItemManager itemManager;
	@Nullable
	private ClogIndex clogIndex;

	TooltipDataBuilder(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	void setClogIndex(@Nullable ClogIndex clogIndex)
	{
		this.clogIndex = clogIndex;
	}

	/**
	 * Build TooltipData for a clog category.
	 * Returns null if no item data exists for the category.
	 */
	TooltipData buildTooltipData(String displayName, String category, int rank, ClogResult clogResult)
	{
		return buildTooltipData(displayName, category, rank, -1, null, clogResult);
	}

	/**
	 * Boss-cell variant: carries the hiscore kc and the local player's
	 * recorded pb for the KC/PB header line.
	 */
	TooltipData buildTooltipData(String displayName, String category, int rank, int kc, String pb, ClogResult clogResult)
	{
		if (clogResult == null) return null;

		List<ClogResult.ClogItem> obtained = clogResult.getObtainedItems().get(category);
		List<Integer> allItems = canonicalItemIds(clogResult.getCategoryItems().get(category));

		if ((obtained == null || obtained.isEmpty()) && (allItems == null || allItems.isEmpty()))
		{
			return null;
		}

		Map<Integer, Integer> obtainedCounts = obtainedCounts(obtained);
		Set<Integer> obtainedIds = new HashSet<>(obtainedCounts.keySet());

		// No catalog for the category means the denominator is UNKNOWN (-1,
		// rendered as "X/?"), never obtainedIds.size() -- that would claim
		// every category complete for sources that only report obtained items.
		int totalItems = allItems != null ? allItems.size() : -1;
		int obtainedCount = allItems != null
			? ClogHelper.countObtained(allItems, obtainedIds) : obtainedIds.size();

		List<Integer> itemList = allItems != null ? allItems : new ArrayList<>(obtainedIds);
		return TooltipData.builder()
			.name(displayName)
			.rank(rank)
			.obtainedCount(obtainedCount)
			.totalItems(totalItems)
			.allItemIds(itemList)
			.obtainedIds(obtainedIds)
			.obtainedCounts(obtainedCounts)
			.itemNames(itemNamesFor(itemList, clogResult))
			.kc(kc)
			.pb(pb)
			.build();
	}

	/** A raid's card with its hard mode's KC and PB, the PB looked up by the hard mode's name; others as they are. */
	@Nullable
	static TooltipData withHardMode(@Nullable TooltipData data, HiscoreSkill raid, @Nullable HiscoreResult result,
		UnaryOperator<String> pb)
	{
		HiscoreSkill hard = PanelData.hardMode(raid);
		if (data == null || hard == null)
		{
			return data;
		}
		return data.toBuilder()
			.hardLabel(PanelData.hardLabel(raid))
			.hardKc(result != null ? result.getKc(hard.getName()) : -1)
			.hardRank(result != null ? result.getRank(hard.getName()) : -1)
			.hardPb(pb.apply(hard.getName()))
			.build();
	}

	TooltipData buildUnsyncedTooltipData(String displayName, String category, int rank,
		String statLabel, int statValue, ClogResult catalog)
	{
		if (catalog == null) return null;
		List<Integer> allItems = canonicalItemIds(catalog.getCategoryItems().get(category));
		if (allItems == null || allItems.isEmpty())
		{
			return null;
		}
		return buildUnsyncedTooltipData(displayName, allItems, rank, statLabel, statValue, true, catalog);
	}

	/**
	 * Build TooltipData for a clue rare category (3rd Age / Gilded).
	 * Returns null if the category has no items.
	 */
	TooltipData buildClueRareData(String name, String clogCategory, ClogResult clogResult)
	{
		if (clogResult == null) return null;
		List<Integer> allItems = canonicalItemIds(
			clogResult.getCategoryItems().get(clogCategory));
		List<ClogResult.ClogItem> obtained = clogResult.getObtainedItems().get(clogCategory);

		if (allItems == null || allItems.isEmpty())
		{
			allItems = canonicalItemIds(staticClueRareItems(clogCategory));
		}

		if (allItems.isEmpty())
		{
			return null;
		}

		obtained = rareObtainedItems(obtained, allItems, clogResult);
		Map<Integer, Integer> obtainedCounts = obtainedCounts(obtained);
		Set<Integer> obtainedIds = new HashSet<>(obtainedCounts.keySet());

		int obtainedCount = ClogHelper.countObtained(allItems, obtainedIds);
		return TooltipData.builder()
			.name(name)
			.obtainedCount(obtainedCount)
			.totalItems(allItems.size())
			.allItemIds(allItems)
			.obtainedIds(obtainedIds)
			.obtainedCounts(obtainedCounts)
			.itemNames(itemNamesFor(allItems, clogResult))
			.rankTracked(false)
			.build();
	}

	/** Each obtained item's highest count, keyed by canonical id. */
	private Map<Integer, Integer> obtainedCounts(@Nullable List<ClogResult.ClogItem> obtained)
	{
		Map<Integer, Integer> counts = new LinkedHashMap<>();
		if (obtained != null)
		{
			for (ClogResult.ClogItem item : obtained)
			{
				counts.merge(canonicalItemId(item.getId()), item.getCount(), Integer::max);
			}
		}
		return counts;
	}

	private List<ClogResult.ClogItem> rareObtainedItems(List<ClogResult.ClogItem> obtained,
		List<Integer> allItems, ClogResult clogResult)
	{
		if (obtained != null && !obtained.isEmpty())
		{
			return obtained;
		}

		Set<Integer> rareIds = new HashSet<>(allItems);
		List<ClogResult.ClogItem> matches = new ArrayList<>();
		for (List<ClogResult.ClogItem> catObtained : clogResult.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : catObtained)
			{
				if (rareIds.contains(canonicalItemId(item.getId())))
				{
					matches.add(item);
				}
			}
		}
		return matches;
	}

	private static List<Integer> staticClueRareItems(String clogCategory)
	{
		if (PanelData.CLOG_THIRD_AGE.equals(clogCategory))
		{
			return TooltipData.itemList(PanelData.THIRD_AGE_ITEMS);
		}
		if (PanelData.CLOG_GILDED.equals(clogCategory))
		{
			return TooltipData.itemList(PanelData.GILDED_ITEMS);
		}
		return new ArrayList<>();
	}

	/** A custom rare collection (Hard, Elite and Master Rare), held from anywhere in the log. */
	TooltipData buildCustomRareData(String name, int[] itemIds, ClogResult clogResult)
	{
		return buildPageData(name, TooltipData.itemList(itemIds), clogResult);
	}

	/**
	 * A set of items, such as a Collection Log page from the game, with what the player holds of each
	 * anywhere in the log: an item counts once however many pages list it, the way the game counts it.
	 */
	TooltipData buildPageData(String name, List<Integer> itemIds, ClogResult clogResult)
	{
		if (clogResult == null) return null;
		Map<Integer, Integer> held = new HashMap<>();
		for (List<ClogResult.ClogItem> catObtained : clogResult.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : catObtained)
			{
				held.merge(canonicalItemId(item.getId()), item.getCount(), Integer::max);
			}
		}

		List<Integer> allItemsList = canonicalItemIds(itemIds);
		Set<Integer> obtainedIds = new HashSet<>();
		Map<Integer, Integer> obtainedCounts = new LinkedHashMap<>();
		for (int itemId : allItemsList)
		{
			Integer count = held.get(itemId);
			if (count != null)
			{
				obtainedIds.add(itemId);
				obtainedCounts.put(itemId, count);
			}
		}

		return TooltipData.builder()
			.name(name)
			.obtainedCount(obtainedIds.size())
			.totalItems(allItemsList.size())
			.allItemIds(allItemsList)
			.obtainedIds(obtainedIds)
			.obtainedCounts(obtainedCounts)
			.itemNames(itemNamesFor(allItemsList, clogResult))
			.rankTracked(false)
			.build();
	}

	TooltipData buildUnsyncedItemData(String name, int[] itemIds, ClogResult catalog)
	{
		return buildUnsyncedItemData(name, TooltipData.itemList(itemIds), catalog);
	}

	TooltipData buildUnsyncedItemData(String name, List<Integer> itemIds, ClogResult catalog)
	{
		if (catalog == null || itemIds == null || itemIds.isEmpty())
		{
			return null;
		}
		return buildUnsyncedTooltipData(name, itemIds, -1, null, -1, false, catalog);
	}

	private TooltipData buildUnsyncedTooltipData(String displayName, List<Integer> itemIds,
		int rank, String statLabel, int statValue, boolean rankTracked, ClogResult catalog)
	{
		List<Integer> canonicalItems = canonicalItemIds(itemIds);
		return TooltipData.builder()
			.name(displayName)
			.rank(rank)
			.totalItems(canonicalItems.size())
			.allItemIds(canonicalItems)
			.obtainedIds(new HashSet<>())
			.obtainedCounts(new LinkedHashMap<>())
			.itemNames(itemNamesFor(canonicalItems, catalog))
			.rankTracked(rankTracked)
			.statLabel(statLabel)
			.statValue(statValue)
			.build();
	}

	private Map<Integer, String> itemNamesFor(List<Integer> itemIds, ClogResult clogResult)
	{
		Map<Integer, String> names = new LinkedHashMap<>();
		for (int itemId : itemIds)
		{
			String name = clogIndex != null
				? clogIndex.itemName(clogResult, itemId) : clogResult.getItemName(itemId);
			if (name != null)
			{
				names.put(itemId, name);
			}
		}
		return names;
	}

	private List<Integer> canonicalItemIds(@Nullable List<Integer> itemIds)
	{
		if (itemIds == null)
		{
			return null;
		}
		Set<Integer> distinct = new java.util.LinkedHashSet<>();
		for (int itemId : itemIds)
		{
			distinct.add(canonicalItemId(itemId));
		}
		return new ArrayList<>(distinct);
	}

	private int canonicalItemId(int itemId)
	{
		return clogIndex != null
			? clogIndex.canonicalItemId(itemId) : ClogIndex.fallbackCanonicalItemId(itemId);
	}

	/** Trigger async loads for all tooltip items. */
	void preloadItemImages(TooltipData data)
	{
		for (int itemId : data.allItemIds)
		{
			int count = data.obtainedIds.contains(itemId)
				? data.obtainedCounts.getOrDefault(itemId, 1) : 1;
			itemManager.getImage(itemId, count, false);
		}
	}
}

package com.killclog;

import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nullable;
import javax.swing.JComponent;
import lombok.AccessLevel;
import lombok.Setter;

final class TooltipItemHover
{
	private final JComponent component;
	private List<HitBox> hitBoxes = Collections.emptyList();
	private int hoveredItemId = -1;
	private int hoveredSection = -1;
	private boolean hoveredObtained;
	private String hoveredItemName;
	// Where the mouse last was over the card, so a scroll can hover what now sits under it.
	private int lastX = -1;
	private int lastY = -1;
	private boolean rehover;
	@Setter(AccessLevel.PACKAGE)
	private boolean wikiLinksEnabled = true;

	TooltipItemHover(JComponent component)
	{
		this.component = component;
		install();
	}

	void setHitBoxes(List<HitBox> hitBoxes)
	{
		this.hitBoxes = hitBoxes != null ? hitBoxes : Collections.emptyList();
		if (rehover)
		{
			rehover = false;
			updateHoveredItem(lastX, lastY);
		}
	}

	/** After a scroll the item now under the still mouse becomes the hovered one, once the card repaints. */
	void rehoverAfterPaint()
	{
		rehover = true;
	}

	void clear()
	{
		if (hoveredItemId != -1 || hoveredItemName != null || hoveredSection != -1)
		{
			hoveredItemId = -1;
			hoveredItemName = null;
			hoveredSection = -1;
			hoveredObtained = false;
			component.repaint();
		}
	}

	String hoveredItemName()
	{
		return hoveredItemName;
	}

	int hoveredSection()
	{
		return hoveredSection;
	}

	/** Whether the hovered thing is held: an item the player has, a tier reached, a source that supplied the log. */
	boolean hoveredItemObtained()
	{
		return hoveredObtained;
	}

	private void install()
	{
		component.addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				updateHoveredItem(e.getX(), e.getY());
			}
		});
		component.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				updateHoveredItem(e.getX(), e.getY());
				if (wikiLinksEnabled && e.getButton() == MouseEvent.BUTTON1 && hoveredItemId > 0)
				{
					TooltipItemLink.openWiki(hoveredItemId);
					closeTooltip();
					e.consume();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				lastX = -1;
				lastY = -1;
				clear();
			}
		});
	}

	private void updateHoveredItem(int mx, int my)
	{
		lastX = mx;
		lastY = my;
		HitBox hitBox = findHitBox(mx, my);
		int nextId = hitBox != null ? hitBox.itemId : -1;
		int nextSection = hitBox != null ? hitBox.section : -1;
		boolean nextObtained = hitBox != null && hitBox.obtained;
		if (nextId == hoveredItemId && nextSection == hoveredSection
			&& nextObtained == hoveredObtained
			&& Objects.equals(hitBox != null ? hitBox.itemName : null, hoveredItemName))
		{
			return;
		}
		hoveredItemId = nextId;
		hoveredItemName = hitBox != null ? hitBox.itemName : null;
		hoveredSection = nextSection;
		hoveredObtained = nextObtained;
		component.repaint();
	}

	private void closeTooltip()
	{
		clear();
		NativeTooltip.hideTooltipTree(component);
	}

	private HitBox findHitBox(int mx, int my)
	{
		for (HitBox hitBox : hitBoxes)
		{
			if (hitBox.bounds.contains(mx, my))
			{
				return hitBox;
			}
		}
		return null;
	}

	static final class HitBox
	{
		private final int section;
		private final int itemId;
		private final String itemName;
		private final Rectangle bounds;
		private final boolean obtained;

		HitBox(int section, int itemId, String itemName, Rectangle bounds, boolean obtained)
		{
			this.section = section;
			this.itemId = itemId;
			this.itemName = TooltipItemLink.displayName(itemId, itemName);
			this.bounds = bounds;
			this.obtained = obtained;
		}

		/** The part of this box a window shows, or null when it shows none of it. */
		@Nullable
		HitBox within(Rectangle window)
		{
			Rectangle shown = bounds.intersection(window);
			return shown.isEmpty() ? null : new HitBox(section, itemId, itemName, shown, obtained);
		}
	}
}

package com.killclog;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import net.runelite.client.util.LinkBrowser;

/** Wiki-link and display helpers for tooltip affordances. */
final class TooltipItemLink
{
	private static final String WIKI_ITEM_LOOKUP =
		"https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=";
	private static final String WIKI_PAGE =
		"https://oldschool.runescape.wiki/w/";
	private static final String FALLBACK_NAME_PREFIX = "Item ";

	private static final String[] CHOMPY_TIERS = {
		"Ogre Bowman", "Bowman", "Ogre Yeoman", "Yeoman", "Ogre Marksman", "Marksman",
		"Ogre Woodsman", "Woodsman", "Ogre Forester", "Forester", "Ogre Bowmaster", "Bowmaster",
		"Ogre Expert", "Expert", "Ogre Dragon Archer", "Dragon Archer",
		"Expert Ogre Dragon Archer", "Expert Dragon Archer"
	};
	private static final int[] CHOMPY_KILLS = {
		30, 40, 50, 70, 95, 125, 170, 225, 300, 400, 550, 700, 1000, 1300, 1700, 2250, 3000, 4000
	};

	static String displayName(int itemId, String name)
	{
		int hat = itemId - 2978;
		return hat >= 0 && hat < CHOMPY_TIERS.length
			? CHOMPY_KILLS[hat] + ": " + CHOMPY_TIERS[hat] : name;
	}

	private TooltipItemLink()
	{
	}

	static String wikiUrl(int itemId)
	{
		return WIKI_ITEM_LOOKUP + itemId;
	}

	static void openWiki(int itemId)
	{
		if (itemId > 0)
		{
			LinkBrowser.browse(wikiUrl(itemId));
		}
	}

	static String wikiPageUrl(String pageName)
	{
		return WIKI_PAGE + encodePageName(pageName);
	}

	static void openWikiPage(String pageName)
	{
		if (pageName != null && !pageName.trim().isEmpty())
		{
			LinkBrowser.browse(wikiPageUrl(pageName));
		}
	}

	static String itemName(Map<Integer, String> itemNames, int itemId)
	{
		String hatName = displayName(itemId, null);
		if (hatName != null) return hatName;
		if (itemNames == null)
		{
			return fallbackName(itemId);
		}
		String name = itemNames.get(itemId);
		if (name == null || name.trim().isEmpty() || "null".equalsIgnoreCase(name))
		{
			return fallbackName(itemId);
		}
		return name;
	}

	/** A page name, and after a '#' the section on it, as the wiki's URLs write them. */
	private static String encodePageName(String pageName)
	{
		if (pageName == null)
		{
			return "";
		}
		int section = pageName.indexOf('#');
		if (section >= 0)
		{
			return encodePageName(pageName.substring(0, section)) + "#" + encodePageName(pageName.substring(section + 1));
		}
		String normalized = pageName.trim().replace(' ', '_');
		String[] parts = normalized.split("/", -1);
		for (int i = 0; i < parts.length; i++)
		{
			parts[i] = URLEncoder.encode(parts[i], StandardCharsets.UTF_8)
				.replace("+", "_");
		}
		return String.join("/", parts);
	}

	private static String fallbackName(int itemId)
	{
		return FALLBACK_NAME_PREFIX + itemId;
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import javax.swing.SwingUtilities;

@Slf4j
final class TooltipItemNameResolver
{
	private static final int BATCH_SIZE = 48;

	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final Runnable onComplete;
	private final Set<ClogResult> inFlight = Collections.synchronizedSet(
		Collections.newSetFromMap(new IdentityHashMap<>()));

	TooltipItemNameResolver(ClientThread clientThread, ItemManager itemManager, Runnable onComplete)
	{
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.onComplete = onComplete;
	}

	void resolve(ClogResult result)
	{
		Set<Integer> allIds = new HashSet<>();
		for (List<ClogResult.ClogItem> items : result.getObtainedItems().values())
		{
			for (ClogResult.ClogItem item : items)
			{
				allIds.add(item.getId());
			}
		}
		for (List<Integer> ids : result.getCategoryItems().values())
		{
			allIds.addAll(ids);
		}

		List<Integer> missing = new ArrayList<>();
		for (int id : allIds)
		{
			if (!result.isItemResolved(id))
			{
				missing.add(id);
			}
		}
		if (missing.isEmpty() || !inFlight.add(result))
		{
			return;
		}

		log.debug("Resolving {} untradeable item names via game cache", missing.size());
		resolveBatch(result, missing, 0);
	}

	private void resolveBatch(ClogResult result, List<Integer> missing, int start)
	{
		clientThread.invokeLater(() ->
		{
			int end = Math.min(start + BATCH_SIZE, missing.size());
			for (int i = start; i < end; i++)
			{
				try
				{
					int id = missing.get(i);
					String name = itemManager.getItemComposition(id).getName();
					if (name != null && !name.isEmpty() && !name.equals("null") && !name.equals("Null"))
					{
						result.markItemResolved(id, name);
					}
				}
				catch (Exception e)
				{
					// Item not in cache - skip.
				}
			}
			if (end < missing.size())
			{
				resolveBatch(result, missing, end);
				return;
			}
			inFlight.remove(result);
			SwingUtilities.invokeLater(onComplete);
		});
	}
}

package com.killclog;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import javax.swing.JComponent;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

final class TooltipItemSprites
{
	private final BufferedImage[] sprites;
	private final String[] itemNames;

	private TooltipItemSprites(int count)
	{
		sprites = new BufferedImage[count];
		itemNames = new String[count];
	}

	static TooltipItemSprites load(List<Integer> itemIds, Map<Integer, String> itemNames,
		ItemManager itemManager, IntUnaryOperator countForItem, JComponent repaintTarget)
	{
		TooltipItemSprites loaded = new TooltipItemSprites(itemIds.size());
		for (int i = 0; i < itemIds.size(); i++)
		{
			int itemId = itemIds.get(i);
			loaded.itemNames[i] = TooltipItemLink.itemName(itemNames, itemId);
			BufferedImage img = itemManager.getImage(itemId, Math.max(1, countForItem.applyAsInt(itemId)), false);
			final int idx = i;
			if (img instanceof AsyncBufferedImage)
			{
				((AsyncBufferedImage) img).onLoaded(() ->
					SwingUtilities.invokeLater(() ->
					{
						loaded.sprites[idx] = img;
						repaintTarget.repaint();
					}));
			}
			loaded.sprites[i] = img;
		}
		return loaded;
	}

	BufferedImage spriteAt(int index)
	{
		if (index < 0 || index >= sprites.length)
		{
			return null;
		}
		return sprites[index];
	}

	String nameAt(int index)
	{
		if (index < 0 || index >= itemNames.length)
		{
			return null;
		}
		return itemNames[index];
	}

	/**
	 * One grid of item sprites in the current font: unobtained ones dimmed,
	 * each centered in its cell, the quantity in the corner when wanted.
	 * Returns a hit box per item, named from {@code names} when given, else as the sprites were loaded.
	 * Without sprites the cells still hover.
	 */
	static List<TooltipItemHover.HitBox> paintGrid(Graphics2D g2, TooltipItemSprites sprites,
		Map<Integer, String> names, int section, List<Integer> ids, Set<Integer> obtainedIds,
		Map<Integer, Integer> counts, int startX, int startY, int cols, int size, int cellSize)
	{
		List<TooltipItemHover.HitBox> hitBoxes = new ArrayList<>(ids.size());
		int ascent = g2.getFontMetrics().getAscent();
		for (int i = 0; i < ids.size(); i++)
		{
			int x = startX + (i % cols) * cellSize;
			int y = startY + (i / cols) * cellSize;
			int itemId = ids.get(i);
			boolean obtained = obtainedIds.contains(itemId);
			int count = obtained ? counts.getOrDefault(itemId, 1) : 1;
			hitBoxes.add(new TooltipItemHover.HitBox(section, itemId,
				names != null || sprites == null ? TooltipItemLink.itemName(names, itemId) : sprites.nameAt(i),
				new Rectangle(x, y, size, size), obtained));
			BufferedImage sprite = sprites != null ? sprites.spriteAt(i) : null;
			if (sprite != null)
			{
				g2.setComposite(obtained
					? AlphaComposite.SrcOver
					: AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.3f));
				g2.drawImage(sprite, x + (size - sprite.getWidth()) / 2, y + (size - sprite.getHeight()) / 2, null);
				g2.setComposite(AlphaComposite.SrcOver);
			}
			if (obtained && count > 1)
			{
				String quantity = String.valueOf(count);
				g2.setColor(Color.BLACK);
				g2.drawString(quantity, x + 1, y + ascent + 1);
				g2.setColor(atCap(itemId, count) ? TitleTooltip.CLOG_GREEN : TitleTooltip.CLOG_YELLOW);
				g2.drawString(quantity, x, y + ascent);
			}
		}
		return hitBoxes;
	}

	/** A count the game stops at, 250 for most log items and 65,535 for the rest, reads green: there's no more to log. */
	static boolean atCap(int itemId, int count)
	{
		return count >= 65535 || count == 250 && Arrays.stream(PanelData.COUNTS_PAST_250_ITEMS).noneMatch(id -> id == itemId);
	}
}

