public class ClueSummaryTooltipTest
{
	@Test
	public void rareRowsAreHitTestedOnlyWhereTheyWerePainted()
	{
		ClueSummaryTooltip tip = painted(card());
		// Nothing above the rare section answers, and nothing below its five rows.
		assertEquals(-1, tip.rareAt(0));
		int top = firstRareY(tip);
		assertEquals(-1, tip.rareAt(top - 1));
		for (int row = 0; row < ClueSummaryTooltip.RARE_LABELS.length; row++)
		{
			assertEquals(row, tip.rareAt(top + row * NativeTooltip.LINE_HEIGHT));
			assertEquals(row, tip.rareAt(top + row * NativeTooltip.LINE_HEIGHT + NativeTooltip.LINE_HEIGHT - 1));
		}
		assertEquals(-1, tip.rareAt(top + ClueSummaryTooltip.RARE_LABELS.length * NativeTooltip.LINE_HEIGHT));
	}

	@Test
	public void aRareRowAnswersExactlyWhereItsIconWasPainted()
	{
		ClueSummaryTooltip tip = card();
		BufferedImage[] icons = new BufferedImage[ClueSummaryTooltip.RARE_LABELS.length];
		for (int row = 0; row < icons.length; row++)
		{
			icons[row] = new BufferedImage(13, 13, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = icons[row].createGraphics();
			g.setColor(new Color(255, 0, 255 - row));
			g.fillRect(0, 0, 13, 13);
			g.dispose();
		}
		tip.setRareIcons(icons);
		Dimension size = tip.getPreferredSize();
		tip.setSize(size);
		BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		tip.paint(graphics);
		graphics.dispose();

		int x = NativeTooltip.getInset() + 6;
		int found = 0;
		for (int y = 0; y < size.height; y++)
		{
			int rgb = image.getRGB(x, y);
			for (int row = 0; row < icons.length; row++)
			{
				if (rgb == new Color(255, 0, 255 - row).getRGB())
				{
					// Every painted pixel of a row's icon belongs to that row and no other.
					assertEquals(row, tip.rareAt(y));
					found++;
				}
			}
		}
		assertEquals(13 * icons.length, found);
		// The last row ends inside the card.
		assertTrue(firstRareY(tip) + icons.length * NativeTooltip.LINE_HEIGHT
			<= size.height - NativeTooltip.getInset());
	}

	@Test
	public void pressingARareRowOpensThatCollectionAndNothingElseDoes()
	{
		ClueSummaryTooltip tip = card();
		List<Integer> opened = new ArrayList<>();
		tip.setOnOpenRare((press, row) -> opened.add(row));

		// Before the first paint there is no rare section to press.
		press(tip, 5, 200, MouseEvent.BUTTON1);
		assertTrue(opened.isEmpty());

		painted(tip);
		int top = firstRareY(tip);
		press(tip, 5, top + 2 * NativeTooltip.LINE_HEIGHT + 3, MouseEvent.BUTTON1);
		assertEquals(List.of(2), opened);

		// A tier line is not a link, and neither is a right click on a rare row.
		press(tip, 5, top - 40, MouseEvent.BUTTON1);
		press(tip, 5, top + 3, MouseEvent.BUTTON3);
		assertEquals(List.of(2), opened);
	}

	@Test
	public void theHoveredRareRowIsTrackedAndClearedOnExit()
	{
		ClueSummaryTooltip tip = painted(card());
		int top = firstRareY(tip);
		move(tip, 5, top + NativeTooltip.LINE_HEIGHT + 2);
		assertEquals(1, tip.hoveredRare());
		move(tip, 5, 2);
		assertEquals(-1, tip.hoveredRare());
		move(tip, 5, top + 2);
		for (MouseListener listener : tip.getMouseListeners())
		{
			listener.mouseExited(event(tip, MouseEvent.MOUSE_EXITED, 5, top + 2, MouseEvent.NOBUTTON));
		}
		assertEquals(-1, tip.hoveredRare());
	}

	@Test
	public void progressWidensTheCardAndItsAbsenceLeavesItBare()
	{
		ClueSummaryTooltip bare = new ClueSummaryTooltip();
		bare.setData(null, false);
		ClueSummaryTooltip withProgress = card();
		// Same rows either way, so a comparison pair never staggers.
		assertEquals(bare.getPreferredSize().height, withProgress.getPreferredSize().height);
		assertTrue(bare.getPreferredSize().width < withProgress.getPreferredSize().width);

		// Counts cleared again (an unsynced player): back to the bare width.
		for (int line = 1; line <= 7; line++)
		{
			withProgress.setProgress(line, null);
		}
		for (int row = 0; row < ClueSummaryTooltip.RARE_LABELS.length; row++)
		{
			withProgress.setRare(row, null);
		}
		assertEquals(bare.getPreferredSize().width, withProgress.getPreferredSize().width);
	}

	private static ClueSummaryTooltip card()
	{
		ClueSummaryTooltip tip = new ClueSummaryTooltip();
		tip.setData(null, false);
		for (int line = 1; line <= 6; line++)
		{
			tip.setProgress(line, new int[]{line * 10, 140});
		}
		tip.setProgress(7, new int[]{1, 1});
		for (int row = 0; row < ClueSummaryTooltip.RARE_LABELS.length; row++)
		{
			tip.setRare(row, new int[]{row, 38});
		}
		return tip;
	}

	private static ClueSummaryTooltip painted(ClueSummaryTooltip tip)
	{
		Dimension size = tip.getPreferredSize();
		tip.setSize(size);
		Graphics2D graphics = new BufferedImage(
			size.width, size.height, BufferedImage.TYPE_INT_ARGB).createGraphics();
		tip.paint(graphics);
		graphics.dispose();
		return tip;
	}

	/** The first y that answers as rare row 0, found the way a pointer would. */
	private static int firstRareY(ClueSummaryTooltip tip)
	{
		for (int y = 0; y < tip.getHeight(); y++)
		{
			if (tip.rareAt(y) == 0)
			{
				return y;
			}
		}
		throw new AssertionError("no rare section painted");
	}

	private static void press(ClueSummaryTooltip tip, int x, int y, int button)
	{
		for (MouseListener listener : tip.getMouseListeners())
		{
			listener.mousePressed(event(tip, MouseEvent.MOUSE_PRESSED, x, y, button));
		}
	}

	private static void move(ClueSummaryTooltip tip, int x, int y)
	{
		for (MouseMotionListener listener : tip.getMouseMotionListeners())
		{
			listener.mouseMoved(event(tip, MouseEvent.MOUSE_MOVED, x, y, MouseEvent.NOBUTTON));
		}
	}

	private static MouseEvent event(ClueSummaryTooltip tip, int id, int x, int y, int button)
	{
		return new MouseEvent(tip, id, System.currentTimeMillis(), 0, x, y, 1, false, button);
	}
}

package com.killclog;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class CollectionLogSearchSetupTest
{
	@Test
	public void onlyCollectionLogSearchStartsFirstTimeCapture()
	{
		int collectionLogHeader = KillClogPlugin.CLOG_INTERFACE << 16 | 1;
		int unrelatedWidget = 320 << 16 | 1;

		assertTrue(KillClogPlugin.isCollectionLogSearchClick("Search", collectionLogHeader));
		assertTrue(KillClogPlugin.isCollectionLogSearchClick(
			"<col=ff9040>Search</col>", collectionLogHeader));
		assertFalse(KillClogPlugin.isCollectionLogSearchClick("Lookup", collectionLogHeader));
		assertFalse(KillClogPlugin.isCollectionLogSearchClick("Search", unrelatedWidget));
		assertFalse(KillClogPlugin.isCollectionLogSearchClick("Search", -1));
	}

	@Test
	public void searchStreamFinalizesAfterThreeQuietTicksWithoutBackAction()
	{
		BulkCaptureState capture = new BulkCaptureState();
		capture.arm(100, 1, 1_500);
		capture.captureScriptArguments(new Object[]{4100, 995, 42}, 101);

		assertFalse(capture.readyToFinalize(103));
		assertTrue(capture.readyToFinalize(104));
	}

	@Test
	public void emptySearchSchedulesFinalizationWithoutItemScripts()
	{
		BulkCaptureState capture = new BulkCaptureState();
		capture.arm(200, 0, 0);
		capture.scheduleEmptySearchFinalization(200);

		assertFalse(capture.readyToFinalize(209));
		assertTrue(capture.readyToFinalize(210));
	}

	@Test
	public void itemStreamExtendsAnInitiallyEmptySearchDeadline()
	{
		BulkCaptureState capture = new BulkCaptureState();
		capture.arm(300, 0, 0);
		capture.scheduleEmptySearchFinalization(300);
		capture.captureScriptArguments(new Object[]{4100, 995, 42}, 302);

		assertFalse(capture.readyToFinalize(303));
		assertFalse(capture.readyToFinalize(304));
		assertTrue(capture.readyToFinalize(305));
	}

	@Test
	public void reportedItemsCancelEmptyDeadlineUntilScriptsArrive()
	{
		BulkCaptureState capture = new BulkCaptureState();
		capture.arm(400, 0, 0);
		capture.scheduleEmptySearchFinalization(400);
		capture.deferEmptyFinalizationIfItemsReported(5);

		assertFalse(capture.readyToFinalize(410));
		capture.captureScriptArguments(new Object[]{4100, 995, 42}, 411);
		assertTrue(capture.readyToFinalize(414));
	}
}

package com.killclog;

import java.util.EnumMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class CombatAchievementTest
{
	@Test
	public void testHighestForPointsBoundaries()
	{
		// Current OSRS Combat Achievement thresholds.
		assertNull(CombatAchievementTier.highestForPoints(0));
		assertNull(CombatAchievementTier.highestForPoints(40));
		assertEquals(CombatAchievementTier.EASY, CombatAchievementTier.highestForPoints(41));
		assertEquals(CombatAchievementTier.EASY, CombatAchievementTier.highestForPoints(160));
		assertEquals(CombatAchievementTier.MEDIUM, CombatAchievementTier.highestForPoints(161));
		assertEquals(CombatAchievementTier.MEDIUM, CombatAchievementTier.highestForPoints(418));
		assertEquals(CombatAchievementTier.HARD, CombatAchievementTier.highestForPoints(419));
		assertEquals(CombatAchievementTier.ELITE, CombatAchievementTier.highestForPoints(1075));
		assertEquals(CombatAchievementTier.MASTER, CombatAchievementTier.highestForPoints(1945));
		// Grandmaster is completion-gated, never returned by highestForPoints.
		assertEquals(CombatAchievementTier.MASTER, CombatAchievementTier.highestForPoints(99999));
	}

	@Test
	public void testRewardMapping()
	{
		assertEquals(CombatAchievementReward.EASY, CombatAchievementTier.EASY.reward());
		assertEquals(CombatAchievementReward.MEDIUM, CombatAchievementTier.MEDIUM.reward());
		assertEquals(CombatAchievementReward.HARD, CombatAchievementTier.HARD.reward());
		assertEquals(CombatAchievementReward.ELITE, CombatAchievementTier.ELITE.reward());
		assertEquals(CombatAchievementReward.MASTER, CombatAchievementTier.MASTER.reward());
		assertEquals(CombatAchievementReward.GRANDMASTER, CombatAchievementTier.GRANDMASTER.reward());
	}

	@Test
	public void testFromName()
	{
		assertEquals(CombatAchievementTier.EASY, CombatAchievementTier.fromName("Easy"));
		assertEquals(CombatAchievementTier.EASY, CombatAchievementTier.fromName("easy"));
		assertEquals(CombatAchievementTier.GRANDMASTER, CombatAchievementTier.fromName("GRANDMASTER"));
		assertNull(CombatAchievementTier.fromName("bogus"));
		assertNull(CombatAchievementTier.fromName(null));
	}

	@Test
	public void testResultPointsAndTier()
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		completed.put(CombatAchievementTier.EASY, 41);
		completed.put(CombatAchievementTier.MEDIUM, 60);
		CombatAchievementResult r = CombatAchievementResult.of(completed, null);
		assertEquals(161, r.getTotalPoints());
		assertEquals(CombatAchievementTier.MEDIUM, r.getTier());
		assertEquals(CombatAchievementReward.MEDIUM, r.getReward());
	}

	@Test
	public void testGrandmasterRequiresFullCompletion()
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			total.put(tier, 100);
			completed.put(tier, 99); // one short in every tier
		}
		CombatAchievementResult r = CombatAchievementResult.of(completed, total);
		assertTrue(r.getTotalPoints() > 1945);
		assertEquals(CombatAchievementTier.MASTER, r.getTier());
		assertEquals(CombatAchievementReward.MASTER, r.getReward());
		assertFalse(r.isAllComplete());
	}

	@Test
	public void testGrandmasterRequiresCanonicalTotals()
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			completed.put(tier, tier.totalTasks() - 1);
			total.put(tier, tier.totalTasks() - 1);
		}
		CombatAchievementResult r = CombatAchievementResult.of(completed, total);
		assertEquals(CombatAchievementTier.MASTER, r.getTier());
		assertFalse(r.isAllComplete());
	}

	@Test
	public void testGrandmasterWithFullCompletion()
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			total.put(tier, tier.totalTasks());
			completed.put(tier, tier.totalTasks());
		}
		CombatAchievementResult r = CombatAchievementResult.of(completed, total);
		assertEquals(CombatAchievementTier.GRANDMASTER, r.getTier());
		assertEquals(CombatAchievementReward.GRANDMASTER, r.getReward());
		assertTrue(r.isAllComplete());
	}

	@Test
	public void testGrandmasterWithCanonicalTotals()
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			completed.put(tier, tier.totalTasks());
			total.put(tier, tier.totalTasks());
		}
		CombatAchievementResult r = CombatAchievementResult.of(completed, total);
		assertEquals(2671, r.getTotalPoints());
		assertEquals(CombatAchievementTier.GRANDMASTER, r.getTier());
		assertEquals(CombatAchievementReward.GRANDMASTER, r.getReward());
	}

	@Test
	public void testTierMathFollowsLiveCatalog()
	{
		// The release-day regression: a Grandmaster snapshot synced before a
		// Combat Achievement batch must lose the tier against the game's new
		// catalog, exactly as it does in the client, before the player
		// re-syncs. Completed counts never revoke; only denominators move.
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			completed.put(tier, tier.totalTasks());
			total.put(tier, tier.totalTasks());
		}
		Map<CombatAchievementTier, Integer> live = liveCatalogWithNewBatch();

		CombatAchievementResult r = CombatAchievementResult.of(completed, total, live);
		assertEquals(2671, r.getTotalPoints());
		assertFalse(r.isAllComplete());
		assertEquals(CombatAchievementTier.MASTER, r.getTier());
		// Display denominators follow the live catalog, not the stale snapshot.
		assertEquals(129, r.getTotal(CombatAchievementTier.GRANDMASTER));
		assertEquals(121, r.getCompleted(CombatAchievementTier.GRANDMASTER));
	}

	@Test
	public void testLiveCatalogCompletionReclaimsGrandmaster()
	{
		// A player who has finished the new batch is Grandmaster against the
		// live catalog even while the provider still reports old totals.
		Map<CombatAchievementTier, Integer> live = liveCatalogWithNewBatch();
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			completed.put(tier, live.get(tier));
			total.put(tier, tier.totalTasks());
		}

		CombatAchievementResult r = CombatAchievementResult.of(completed, total, live);
		assertTrue(r.isAllComplete());
		assertEquals(CombatAchievementTier.GRANDMASTER, r.getTier());
	}

	@Test
	public void testRebasedOnHealsStaleVerdicts()
	{
		// A result built before any catalog capture holds a fallback
		// Grandmaster; rebasing against an expanded catalog demotes it with
		// no refetch, and rebasing an already-current result is free.
		Map<CombatAchievementTier, Integer> full = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			full.put(tier, tier.totalTasks());
		}
		CombatAchievementResult stale = CombatAchievementResult.of(full, full);
		assertEquals(CombatAchievementTier.GRANDMASTER, stale.getTier());

		Map<CombatAchievementTier, Integer> live = liveCatalogWithNewBatch();
		CombatAchievementResult healed = stale.rebasedOn(live);
		assertEquals(CombatAchievementTier.MASTER, healed.getTier());
		assertEquals(129, healed.getTotal(CombatAchievementTier.GRANDMASTER));
		assertSame(healed, healed.rebasedOn(live));
		assertSame(stale, stale.rebasedOn(null));
	}

	@Test
	public void testDeriveTotalsFromThresholds()
	{
		// The live thresholds encode the fallback catalog exactly.
		Map<CombatAchievementTier, Integer> thresholds = new EnumMap<>(CombatAchievementTier.class);
		thresholds.put(CombatAchievementTier.EASY, 41);
		thresholds.put(CombatAchievementTier.MEDIUM, 161);
		thresholds.put(CombatAchievementTier.HARD, 419);
		thresholds.put(CombatAchievementTier.ELITE, 1075);
		thresholds.put(CombatAchievementTier.MASTER, 1945);
		thresholds.put(CombatAchievementTier.GRANDMASTER, 2671);

		Map<CombatAchievementTier, Integer> totals = CaCatalog.deriveTotals(thresholds);
		assertNotNull(totals);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			assertEquals(tier.totalTasks(), (int) totals.get(tier));
		}
	}

	@Test
	public void testDeriveTotalsRejectsPartialReads()
	{
		// Pre-login zeros.
		Map<CombatAchievementTier, Integer> zeros = new EnumMap<>(CombatAchievementTier.class);
		for (CombatAchievementTier tier : CombatAchievementTier.values())
		{
			zeros.put(tier, 0);
		}
		assertNull(CaCatalog.deriveTotals(zeros));

		// Non-monotonic thresholds.
		Map<CombatAchievementTier, Integer> reversed = new EnumMap<>(CombatAchievementTier.class);
		reversed.put(CombatAchievementTier.EASY, 161);
		reversed.put(CombatAchievementTier.MEDIUM, 41);
		reversed.put(CombatAchievementTier.HARD, 416);
		reversed.put(CombatAchievementTier.ELITE, 1064);
		reversed.put(CombatAchievementTier.MASTER, 1904);
		reversed.put(CombatAchievementTier.GRANDMASTER, 2630);
		assertNull(CaCatalog.deriveTotals(reversed));

		// A step that does not divide by the tier's points per task.
		Map<CombatAchievementTier, Integer> garbled = new EnumMap<>(CombatAchievementTier.class);
		garbled.put(CombatAchievementTier.EASY, 41);
		garbled.put(CombatAchievementTier.MEDIUM, 162);
		garbled.put(CombatAchievementTier.HARD, 416);
		garbled.put(CombatAchievementTier.ELITE, 1064);
		garbled.put(CombatAchievementTier.MASTER, 1904);
		garbled.put(CombatAchievementTier.GRANDMASTER, 2630);
		assertNull(CaCatalog.deriveTotals(garbled));
	}

	@Test
	public void testEmptyResult()
	{
		CombatAchievementResult r = CombatAchievementResult.of(null, null);
		assertEquals(0, r.getTotalPoints());
		assertNull(r.getTier());
		assertNull(r.getReward());
		assertFalse(r.isAllComplete());
	}

	/** The fallback catalog plus an invented release batch across every tier. */
	private static Map<CombatAchievementTier, Integer> liveCatalogWithNewBatch()
	{
		Map<CombatAchievementTier, Integer> live = new EnumMap<>(CombatAchievementTier.class);
		live.put(CombatAchievementTier.EASY, 42);
		live.put(CombatAchievementTier.MEDIUM, 61);
		live.put(CombatAchievementTier.HARD, 87);
		live.put(CombatAchievementTier.ELITE, 165);
		live.put(CombatAchievementTier.MASTER, 177);
		live.put(CombatAchievementTier.GRANDMASTER, 129);
		return live;
	}

	@Test
	public void testResultCountAccessors()
	{
		Map<CombatAchievementTier, Integer> completed = new EnumMap<>(CombatAchievementTier.class);
		Map<CombatAchievementTier, Integer> total = new EnumMap<>(CombatAchievementTier.class);
		completed.put(CombatAchievementTier.HARD, 50);
		total.put(CombatAchievementTier.HARD, 142);
		CombatAchievementResult r = CombatAchievementResult.of(completed, total);
		assertEquals(50, r.getCompleted(CombatAchievementTier.HARD));
		assertEquals(142, r.getTotal(CombatAchievementTier.HARD));
		assertEquals(0, r.getCompleted(CombatAchievementTier.MASTER));
	}
}

package com.killclog;

import java.util.HashMap;
import org.junit.Test;
import static com.killclog.LookupTestFixture.*;
import static org.junit.Assert.*;

public class ComparisonLifecycleTest
{
	@Test
	public void exitCancelsPendingLookupBeforeHiscoreAndAfterHiscore() throws Exception
	{
		for (boolean hiscoreFirst : new boolean[]{false, true})
		{
			LookupTestFixture fixture = new LookupTestFixture();
			edt(() -> fixture.comparison.doCompareLookup("Red", "Blue", null));
			if (hiscoreFirst)
			{
				fixture.hiscores.get("Red").complete(hiscore(2));
				edt(() -> assertTrue(fixture.comparison.isCompareLookupInFlight()));
			}
			edt(fixture.comparison::exit);
			fixture.hiscores.get("Red").complete(hiscore(2));
			if (hiscoreFirst) fixture.clogs.get("Red").complete(clog("Red"));
			fixture.cas.get("Red").complete(ca(2));
			edt(() -> assertFalse(fixture.comparison.isComparisonMode()));
			assertEquals(0, fixture.events("onComparisonEnter"));
			assertEquals(1, fixture.events("onComparisonExit"));
			assertNull(fixture.comparison.getCompareCaResult());
		}
	}

	@Test
	public void quietResetFencesBothSessionsAndAcceptsFreshLookups() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() ->
		{
			fixture.comparison.doCompareLookup("Red", "Blue", null);
			fixture.primary.start("Green", null, null);
			fixture.comparison.reset();
			fixture.primary.reset();
		});
		HashMap<String, Integer> before = new HashMap<>(fixture.events);
		fixture.hiscores.get("Red").complete(hiscore(2));
		fixture.hiscores.get("Green").complete(hiscore(3));
		fixture.clogs.get("Green").complete(clog("Green"));
		fixture.cas.get("Green").complete(ca(3));
		fixture.cas.get("Red").complete(ca(2));
		edt(() -> assertEquals(before, fixture.events));
		assertNull(fixture.primary.getHiscoreResult());
		assertNull(fixture.comparison.getCompareHiscoreResult());
		edt(() -> fixture.primary.start("Fresh", null, null));
		fixture.hiscores.get("Fresh").complete(hiscore(4));
		// A finished hiscore is shown with its clog, so the clog lane settles first.
		fixture.clogs.get("Fresh").complete(clog("Fresh"));
		edt(() -> assertEquals(4, fixture.primary.getHiscoreResult().getTotalLevel()));
		edt(() -> fixture.comparison.doCompareLookup("Other", "Fresh", null));
		assertTrue(fixture.hiscores.containsKey("Other"));
	}

	@Test
	public void cancelAfterPrimarySettlementStillFencesOptionalCa() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.primary.start("Green", null, null));
		fixture.hiscores.get("Green").complete(hiscore(3));
		edt(() ->
		{
			assertFalse(fixture.primary.isLookupInFlight());
			fixture.primary.cancelInFlight();
		});
		fixture.cas.get("Green").complete(ca(3));
		fixture.clogs.get("Green").complete(clog("Green"));
		edt(() -> assertNull(fixture.primary.getCaResult()));
		assertEquals(0, fixture.events("onCaResult"));
		assertEquals(0, fixture.events("onClogResult"));
	}

	@Test
	public void failedComparisonFencesLateCa() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.comparison.doCompareLookup("Missing", "Blue", null));
		fixture.hiscores.get("Missing").complete(null);
		edt(() -> assertEquals(1, fixture.events("onCompareError")));
		fixture.cas.get("Missing").complete(ca(3));
		edt(() -> assertNull(fixture.comparison.getCompareCaResult()));
		assertFalse(fixture.comparison.isComparisonMode());
	}
}

package com.killclog;

import org.junit.Test;
import static com.killclog.LookupTestFixture.*;
import static org.junit.Assert.*;

public class ComparisonSnapshotTest
{
	@Test
	public void replacementPublishesOnePlayerForEveryCaArrivalOrder() throws Exception
	{
		for (int caStage = 0; caStage < 3; caStage++)
		{
			for (boolean clogPresent : new boolean[]{false, true})
			{
				LookupTestFixture fixture = new LookupTestFixture();
				commitFirstPlayer(fixture);
				edt(() -> fixture.comparison.doCompareLookup("Second", "Blue", null));
				assertPlayer(fixture, "First", 2, "First", 2);
				if (caStage == 0) fixture.cas.get("Second").complete(ca(3));
				fixture.hiscores.get("Second").complete(hiscore(3));
				edt(() -> assertTrue(fixture.comparison.isCompareLookupInFlight()));
				if (caStage == 1) fixture.cas.get("Second").complete(ca(3));
				assertPlayer(fixture, "First", 2, "First", 2);
				edt(() -> fixture.comparison.doCompareLookup("Third", "Blue", null));
				assertFalse(fixture.hiscores.containsKey("Third"));
				assertEquals(1, fixture.events("onComparisonEnter"));
				fixture.clogs.get("Second").complete(clogPresent ? clog("Second") : null);
				assertPlayer(fixture, "Second", 3, clogPresent ? "Second" : null, caStage < 2 ? 3 : null);
				assertFalse(fixture.comparison.isCompareLookupInFlight());
				if (caStage == 2) fixture.cas.get("Second").complete(ca(3));
				assertPlayer(fixture, "Second", 3, clogPresent ? "Second" : null, 3);
				assertEquals(2, fixture.events("onComparisonEnter"));
			}
		}
	}

	@Test
	public void failedReplacementRetainsTheWholePreviousPlayer() throws Exception
	{
		for (boolean error : new boolean[]{false, true})
		{
			LookupTestFixture fixture = new LookupTestFixture();
			commitFirstPlayer(fixture);
			edt(() -> fixture.comparison.doCompareLookup("Missing", "Blue", null));
			fixture.cas.get("Missing").complete(ca(3));
			if (error) fixture.hiscores.get("Missing").completeExceptionally(new IllegalStateException("fixture"));
			else fixture.hiscores.get("Missing").complete(null);
			assertPlayer(fixture, "First", 2, "First", 2);
			assertFalse(fixture.comparison.isCompareLookupInFlight());
			assertEquals(1, fixture.events("onCompareError"));
			assertEquals(0, fixture.events("onCompareDataReady"));
		}
	}

	@Test
	public void failedClogCommitsAbsentClogInsteadOfKeepingAnotherPlayersItems() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		commitFirstPlayer(fixture);
		edt(() -> fixture.comparison.doCompareLookup("Second", "Blue", null));
		fixture.hiscores.get("Second").complete(hiscore(3));
		edt(() -> fixture.clogs.get("Second").completeExceptionally(new IllegalStateException("fixture")));
		assertPlayer(fixture, "Second", 3, null, null);
	}

	@Test
	public void mirrorCommitsBlueSnapshotAndFencesPreviousLateCa() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.comparison.doCompareLookup("First", "Blue", null));
		fixture.hiscores.get("First").complete(hiscore(2));
		edt(() -> fixture.clogs.get("First").complete(clog("First")));
		edt(() -> fixture.comparison.doCompareLookup("Blue", "Blue", null));
		fixture.cas.get("First").complete(ca(2));
		assertPlayer(fixture, "Blue", 1, "Blue", 1);
		assertFalse(fixture.hiscores.containsKey("Blue"));
		assertSame(fixture.primary.getNativeHiscoreResult(), fixture.comparison.getCompareHiscoreResult());
	}

	@Test
	public void aLateCaKeepsTheLocalPlayersOwnAccountType() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		// The local player, a group ironman the hiscores read as regular, on the red side.
		edt(() -> fixture.comparison.doCompareLookup("Me", "Me", AccountType.GROUP_IRONMAN));
		fixture.hiscores.get("Me").complete(hiscore(2));
		edt(() -> fixture.clogs.get("Me").complete(clog("Me")));
		assertEquals(AccountType.GROUP_IRONMAN, redSelfType(fixture));
		fixture.cas.get("Me").complete(ca(5));
		assertPlayer(fixture, "Me", 2, "Me", 5);
		assertEquals(AccountType.GROUP_IRONMAN, redSelfType(fixture));
	}

	private static AccountType redSelfType(LookupTestFixture fixture) throws Exception
	{
		AccountType[] type = new AccountType[1];
		edt(() ->
		{
			try
			{
				java.lang.reflect.Field compared = ComparisonController.class.getDeclaredField("compared");
				compared.setAccessible(true);
				Object red = compared.get(fixture.comparison);
				java.lang.reflect.Field selfType = red.getClass().getDeclaredField("selfType");
				selfType.setAccessible(true);
				type[0] = (AccountType) selfType.get(red);
			}
			catch (ReflectiveOperationException e)
			{
				throw new AssertionError(e);
			}
		});
		return type[0];
	}

	private static void commitFirstPlayer(LookupTestFixture fixture) throws Exception
	{
		edt(() -> fixture.comparison.doCompareLookup("First", "Blue", null));
		fixture.cas.get("First").complete(ca(2));
		fixture.hiscores.get("First").complete(hiscore(2));
		edt(() -> fixture.clogs.get("First").complete(clog("First")));
		assertPlayer(fixture, "First", 2, "First", 2);
	}

	private static void assertPlayer(LookupTestFixture fixture, String name, int level,
		String clogName, Integer points) throws Exception
	{
		edt(() ->
		{
			ComparisonController comparison = fixture.comparison;
			assertTrue(comparison.isComparisonMode());
			assertEquals(name, comparison.getCompareRsn());
			assertEquals(level, comparison.getCompareHiscoreResult().getTotalLevel());
			assertEquals(clogName, comparison.getCompareClogResult() == null
				? null : comparison.getCompareClogResult().getPlayerName());
			assertEquals(points, comparison.getCompareCaResult() == null
				? null : Integer.valueOf(comparison.getCompareCaResult().getTotalPoints()));
		});
	}
}

package com.killclog;

import net.runelite.client.config.ConfigManager;
import org.junit.Test;
import org.mockito.InOrder;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.inOrder;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ConfigMigrationsTest
{
	@Test
	public void skillSummaryOnlyPlayersMoveToTheActivityTray()
	{
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfiguration("killclog", "skillDisplay")).thenReturn("TOOLTIP");

		ConfigMigrations.run(config);

		verify(config).setConfiguration("killclog", "skillDisplay", SkillDisplay.TRAY);
	}

	@Test
	public void savedSettingsMoveBeforeTheConfigIsHandedToAnything()
	{
		// The panel is built at injection and reads its skill location then,
		// so the move belongs to the provider rather than to startUp.
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfiguration("killclog", "skillDisplay")).thenReturn("TOOLTIP");

		new KillClogPlugin().provideConfig(config);

		InOrder order = inOrder(config);
		order.verify(config).setConfiguration("killclog", "skillDisplay", SkillDisplay.TRAY);
		order.verify(config).getConfig(KillClogConfig.class);
	}

	@Test
	public void everyOtherSkillLocationIsLeftAlone()
	{
		for (String saved : new String[]{"FIXED", "TRAY", null})
		{
			ConfigManager config = mock(ConfigManager.class);
			when(config.getConfiguration("killclog", "skillDisplay")).thenReturn(saved);

			ConfigMigrations.run(config);

			verify(config, never()).setConfiguration(eq("killclog"), eq("skillDisplay"), any(Object.class));
		}
	}

	@Test
	public void legacyCompletionColourStillBecomesAColourModeOnce()
	{
		ConfigManager config = mock(ConfigManager.class);
		when(config.getConfiguration("killclog", "skillCompletionColor")).thenReturn("false");

		ConfigMigrations.run(config);

		verify(config).setConfiguration("killclog", "skillColorMode", SkillColorMode.SKILL_COLOR);
		verify(config).unsetConfiguration("killclog", "skillCompletionColor");

		// A mode the player already chose is never overwritten by the legacy value.
		ConfigManager chosen = mock(ConfigManager.class);
		when(chosen.getConfiguration("killclog", "skillCompletionColor")).thenReturn("true");
		when(chosen.getConfiguration("killclog", "skillColorMode")).thenReturn("CLOG_PROGRESSION");

		ConfigMigrations.run(chosen);

		verify(chosen, never()).setConfiguration(anyString(), eq("skillColorMode"), any(Object.class));
		verify(chosen).unsetConfiguration("killclog", "skillCompletionColor");
	}
}

package com.killclog;

import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * EHB rates resource integrity and computation. Rate values are read from the
 * bundled TempleOSRS table rather than hardcoded, so a rates refresh cannot
 * silently break the suite.
 */
public class EhbRatesTest
{
	private static HiscoreResult result(AccountType type, Map<String, Integer> kcs)
	{
		return new HiscoreResult(type, HiscoreTable.STANDARD, kcs, new HashMap<>(),
			new HashMap<>(), new HashMap<>(), new HashMap<>(), 0, 0, 0, -1);
	}

	/** A boss Temple rates 0 for mains but positive for ironmen, or null. */
	private static String mainZeroIronPositiveBoss()
	{
		for (Map.Entry<String, double[]> e : EhbRates.rates().entrySet())
		{
			if (e.getValue()[0] == 0 && e.getValue()[1] > 0)
			{
				return e.getKey();
			}
		}
		return null;
	}

	@Test
	public void testEveryHiscoreBossHasRates()
	{
		Map<String, double[]> rates = EhbRates.rates();
		for (String boss : HiscoreService.bossNames())
		{
			double[] pair = rates.get(boss);
			assertNotNull("No EHB rates entry for " + boss, pair);
			assertEquals(2, pair.length);
			assertTrue(boss + " main rate negative", pair[0] >= 0);
			assertTrue(boss + " ironman rate negative", pair[1] >= 0);
		}
	}

	@Test
	public void testNoUnknownBossesInRates()
	{
		Set<String> known = new HashSet<>(Arrays.asList(HiscoreService.bossNames()));
		for (String boss : EhbRates.rates().keySet())
		{
			assertTrue("Rates entry is not a hiscore boss: " + boss, known.contains(boss));
		}
	}

	@Test
	public void testComputeSumsKcOverRate()
	{
		double vorkRate = EhbRates.rates().get("Vorkath")[0];
		double zulrahRate = EhbRates.rates().get("Zulrah")[0];
		assertTrue(vorkRate > 0 && zulrahRate > 0);

		Map<String, Integer> kcs = new HashMap<>();
		kcs.put("Vorkath", 340);
		kcs.put("Zulrah", 92);
		double expected = 340 / vorkRate + 92 / zulrahRate;
		assertEquals(expected,
			EhbRates.compute(result(AccountType.REGULAR, kcs), null), 1e-9);
	}

	@Test
	public void testZeroRateBossAwardsNothingOnMainButCountsForIronman()
	{
		String split = mainZeroIronPositiveBoss();
		if (split == null)
		{
			return;
		}
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put(split, 1000);
		assertEquals(0, EhbRates.compute(result(AccountType.REGULAR, kcs), null), 1e-9);
		double imRate = EhbRates.rates().get(split)[1];
		assertEquals(1000 / imRate,
			EhbRates.compute(result(AccountType.IRONMAN, kcs), null), 1e-9);
	}

	@Test
	public void testResolvedGroupIronmanOutranksRegularHiscoreTag()
	{
		// GIMs only appear on the regular hiscores: the result arrives tagged
		// REGULAR and the provider-resolved type must still pick the ironman
		// column, or a GIM's Barrows-shaped hours silently vanish.
		String split = mainZeroIronPositiveBoss();
		if (split == null)
		{
			return;
		}
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put(split, 1000);
		HiscoreResult regularTagged = result(AccountType.REGULAR, kcs);
		double imRate = EhbRates.rates().get(split)[1];
		assertEquals(1000 / imRate,
			EhbRates.compute(regularTagged, AccountType.GROUP_IRONMAN), 1e-9);
	}

	@Test
	public void testEveryIronmanModeUsesIronmanRates()
	{
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put("Vorkath", 340);
		HiscoreResult regularTagged = result(AccountType.REGULAR, kcs);
		double im = EhbRates.compute(regularTagged, AccountType.IRONMAN);
		for (AccountType type : AccountType.values())
		{
			if (type == AccountType.REGULAR)
			{
				continue;
			}
			assertEquals("Ironman mode " + type + " diverged from ironman rates",
				im, EhbRates.compute(regularTagged, type), 1e-9);
		}
	}

	@Test
	public void testUnrankedKcAwardsNothing()
	{
		Map<String, Integer> kcs = new HashMap<>();
		kcs.put("Vorkath", -1);
		assertEquals(0, EhbRates.compute(result(AccountType.REGULAR, kcs), null), 1e-9);
	}

	@Test
	public void testNullResultIsAbsent()
	{
		assertEquals(-1, EhbRates.compute(null, null), 1e-9);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class FirstPartyFeedbackTest
{
	private static final class Settings implements KillClogConfig
	{
		boolean silentAutomatic = true;

		@Override
		public boolean silentAutomaticSync()
		{
			return silentAutomatic;
		}
	}

	private final Settings config = new Settings();
	private final List<String> events = new ArrayList<>();
	private final List<StatusMessage.Kind> kinds = new ArrayList<>();
	private final FirstPartyFeedback feedback = feedback("sync failed");

	private FirstPartyFeedback feedback(String failureText)
	{
		return new FirstPartyFeedback(config,
			(kind, text, autoClear) ->
			{
				events.add(text);
				kinds.add(kind);
			}, () -> events.add("flash"), failureText);
	}

	@Test
	public void aRefusedVersionSaysUpdateNeededNotFailed()
	{
		feedback.complete(true, false, FirstPartyFeedback.UPDATE_REQUIRED + " Reference: 0123456789abcdef.");
		assertEquals(java.util.Arrays.asList("update needed"), events);
		assertEquals("update needed - restart RuneLite", feedback.hoverText("publish collection log", "publish failed"));
		feedback.complete(true, false, "Server unavailable");
		assertEquals("publish failed", feedback.hoverText("publish collection log", "publish failed"));
		feedback.complete(true, true, "Synced");
		assertEquals("publish collection log", feedback.hoverText("publish collection log", "publish failed"));
	}

	@Test
	public void automaticSyncIsSilentThroughProgressRetryFailureAndSuccess()
	{
		feedback.progress(false, "syncing...", false);
		feedback.progress(false, "retrying...", false);
		feedback.complete(false, false, "Server unavailable");
		assertEquals("Server unavailable", feedback.lastFailure());
		assertTrue(events.isEmpty());
		feedback.complete(false, true, "Synced");
		assertNull(feedback.lastFailure());
		assertTrue(events.isEmpty());
	}

	@Test
	public void manualSyncShowsProgressAndFailureButOnlyFlashesForSuccess()
	{
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, false, "Account opted out");
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed"), events);
		assertEquals("Account opted out", feedback.lastFailure());
		feedback.complete(true, true, "Synced");
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed", "flash"), events);
		assertNull(feedback.lastFailure());
	}

	@Test
	public void manualActionsDoNotUnmuteAutomaticSync()
	{
		feedback.progress(false, "syncing...", false);
		feedback.complete(false, false, "Unavailable");
		assertTrue(events.isEmpty());
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, false, "Unavailable");
		feedback.complete(true, true, "Synced");
		feedback.progress(false, "retrying...", false);
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed", "flash"), events);
	}

	@Test
	public void automaticFeedbackCanBeEnabledWithoutChangingManualFeedback()
	{
		config.silentAutomatic = false;
		feedback.progress(false, "syncing...", false);
		feedback.complete(false, true, "Synced");
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, true, "Synced");
		assertEquals(java.util.Arrays.asList("syncing...", "flash", "syncing...", "flash"), events);
	}

	@Test
	public void characterUploadAlwaysShowsManualFeedbackAndKeepsItsOwnFailure()
	{
		FirstPartyFeedback character = feedback("Publish failed");
		character.progress(true, "rendering...", false);
		character.complete(true, false, "Character upload failed");
		assertEquals(java.util.Arrays.asList("rendering...", "Publish failed"), events);
		feedback.complete(false, true, "Synced prerequisite");
		assertEquals("Character upload failed", character.lastFailure());
		character.complete(true, true, "Published");
		assertEquals(java.util.Arrays.asList("rendering...", "Publish failed", "flash"), events);
		assertNull(character.lastFailure());
		events.clear();
		config.silentAutomatic = false;
		character.progress(true, "rendering...", false);
		character.complete(true, false, "Unavailable");
		assertEquals(java.util.Arrays.asList("rendering...", "Publish failed"), events);
	}

	@Test
	public void changedPreferencesApplyToThePendingResultAndResetForgetsFailure()
	{
		config.silentAutomatic = false;
		feedback.progress(false, "syncing...", false);
		events.clear();
		config.silentAutomatic = true;
		feedback.complete(false, false, "Unavailable");
		assertTrue(events.isEmpty());
		feedback.reset();
		assertNull(feedback.lastFailure());
	}

	@Test
	public void progressNoticeAndFailureCarryTheirKind()
	{
		feedback.progress(true, "syncing...", false);
		feedback.complete(true, false, "Server unavailable");
		feedback.show(true, StatusMessage.Kind.NOTICE, "Change equipment, then retry", true);
		feedback.show(false, StatusMessage.Kind.RESULT, "Finishing previous request...", true);
		assertEquals(java.util.Arrays.asList("syncing...", "sync failed", "Change equipment, then retry"), events);
		assertEquals(java.util.Arrays.asList(StatusMessage.Kind.PROGRESS, StatusMessage.Kind.RESULT,
			StatusMessage.Kind.NOTICE), kinds);
	}
}

package com.killclog;

import java.util.EnumSet;
