package com.killclog;

import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.*;

public class HttpSingleFlightTest
{
	private final Map<String, CompletableFuture<String>> flights = new ConcurrentHashMap<>();

	@Test
	public void timeoutCannotSuppressSourceCompletionOrServiceCleanup() throws Exception
	{
		CompletableFuture<String> transport = new CompletableFuture<>();
		AtomicInteger cached = new AtomicInteger();
		CompletableFuture<String> source = transport.thenApply(value ->
		{
			cached.incrementAndGet();
			return value;
		});
		CompletableFuture<String> first = HttpUtil.singleFlightLookup(flights, "player", () -> source);
		CompletableFuture<String> second = HttpUtil.singleFlightLookup(flights, "player", () -> source);
		assertNull(first.completeOnTimeout(null, 1, TimeUnit.MILLISECONDS).get(1, TimeUnit.SECONDS));
		assertFalse(source.isDone());
		assertFalse(second.isDone());
		transport.complete("late data");
		assertEquals("late data", second.join());
		assertEquals(1, cached.get());
		assertTrue(flights.isEmpty());
		assertEquals("fresh", HttpUtil.singleFlightLookup(flights, "player",
			() -> CompletableFuture.completedFuture("fresh")).join());
	}

	@Test
	public void immediateCompletionRemovesRegisteredFlightWithoutRecursiveUpdate()
	{
		assertEquals("ready", HttpUtil.singleFlightLookup(flights, "player",
			() -> CompletableFuture.completedFuture("ready")).join());
		assertTrue(flights.isEmpty());

		CompletableFuture<String> failed = new CompletableFuture<>();
		failed.completeExceptionally(new IllegalStateException("test failure"));
		assertTrue(HttpUtil.singleFlightLookup(flights, "player", () -> failed)
			.isCompletedExceptionally());
		assertTrue(flights.isEmpty());
	}

	@Test
	public void pendingRequestsShareOneFlightAndReleaseItOnCompletion()
	{
		AtomicInteger starts = new AtomicInteger();
		CompletableFuture<String> source = new CompletableFuture<>();
		java.util.function.Supplier<CompletableFuture<String>> start = () ->
		{
			starts.incrementAndGet();
			return source;
		};
		CompletableFuture<String> first = HttpUtil.singleFlightLookup(flights, "player", start);
		CompletableFuture<String> second = HttpUtil.singleFlightLookup(flights, "player", start);
		assertEquals(1, starts.get());
		assertSame(source, flights.get("player"));
		assertFalse(first.isDone());
		assertFalse(second.isDone());
		source.complete("ready");
		assertEquals("ready", first.join());
		assertEquals("ready", second.join());
		assertTrue(flights.isEmpty());
	}

	@Test
	public void aLookupStartedAsAFlightAnswersStartsAFreshOne()
	{
		AtomicInteger starts = new AtomicInteger();
		java.util.function.Supplier<CompletableFuture<String>> start = () ->
		{
			starts.incrementAndGet();
			return new CompletableFuture<>();
		};
		// The answer is spent: an outage after it must be fetched, not read from the old flight.
		CompletableFuture<String> next = HttpUtil.singleFlightLookup(flights, "player", start)
			.thenCompose(answer -> HttpUtil.singleFlightLookup(flights, "player", start));
		flights.get("player").complete(null);
		assertEquals(2, starts.get());
		assertFalse(next.isDone());
	}

	@Test
	public void lateExceptionalCompletionCannotRemoveReplacementFlight()
	{
		CompletableFuture<String> source = new CompletableFuture<>();
		CompletableFuture<String> first = HttpUtil.singleFlightLookup(flights, "player", () -> source);
		CompletableFuture<String> replacement = new CompletableFuture<>();
		flights.put("player", replacement);
		source.completeExceptionally(new IllegalStateException("test failure"));
		assertTrue(first.isCompletedExceptionally());
		assertSame(replacement, flights.get("player"));
	}
}

package com.killclog;

import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class HttpUtilLaneTest
{
	@Test
	public void aLaneHoldsAtMostTheCapAndTheStalestNameGoesFirst()
	{
		HttpUtil.Lane<String> lane = new HttpUtil.Lane<>(new CircuitBreaker("test"));
		for (int i = 0; i <= HttpUtil.CACHE_CAP; i++)
		{
			lane.ok("name" + i, "value" + i);
			lane.fetched.put("name" + i, 1_000L + i);
		}
		lane.ok("fresh", "value");
		assertEquals(HttpUtil.CACHE_CAP, lane.values.size());
		assertFalse("the name fetched longest ago went", lane.values.containsKey("name0"));
		assertFalse(lane.fetched.containsKey("name0"));
		assertTrue(lane.values.containsKey("fresh"));
	}

	@Test
	public void pastTheCapOnlyExpiredStampsGo()
	{
		Map<String, Long> stamps = new HashMap<>();
		long now = System.currentTimeMillis();
		for (int i = 0; i < HttpUtil.CACHE_CAP; i++)
		{
			stamps.put("old" + i, now - 10_000L);
		}
		stamps.put("live", now);
		HttpUtil.prune(stamps, 5_000L);
		assertEquals(1, stamps.size());
		assertTrue(stamps.containsKey("live"));

		Map<String, Long> few = new HashMap<>(Map.of("old", now - 10_000L));
		HttpUtil.prune(few, 5_000L);
		assertTrue("under the cap nothing is touched", few.containsKey("old"));
	}

	@Test
	public void aMissingNameKeepsWhatTheLaneHeld()
	{
		HttpUtil.Lane<String> lane = new HttpUtil.Lane<>(new CircuitBreaker("test"));
		lane.ok("name", "value");
		assertEquals("value", lane.missing("name"));
		assertTrue(lane.hold("name"));
	}
}

package com.killclog;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.*;

public class KillClogChatCommandTest
{
	@Test
	public void testKcReceivedTextKeepsExactCounts()
	{
		assertEquals("Elder venator fang received on 421 kc",
			KillClogChatCommand.kcReceivedText("Elder venator fang", 421));
		// Provenance never rounds: no 12k/1m shorthand above 9,999.
		assertEquals("Scurry received on 12,345 kc",
			KillClogChatCommand.kcReceivedText("Scurry", 12345));
	}

	@Test
	public void testCommandHeaderIncludesBossKc()
	{
		assertEquals("Vorkath: 420 kc, 2/14",
			KillClogChatCommand.buildCommandHeader("Vorkath", 420, 2, 14, false));
		assertEquals("Vorkath: 420 kc, 12/14 missing",
			KillClogChatCommand.buildCommandHeader("Vorkath", 420, 12, 14, true));
	}

	@Test
	public void testCommandHeaderOmitsUnknownBossKc()
	{
		assertEquals("Vorkath: 2/14",
			KillClogChatCommand.buildCommandHeader("Vorkath", -1, 2, 14, false));
		assertEquals("Vorkath: 12/14 missing",
			KillClogChatCommand.buildCommandHeader("Vorkath", -1, 12, 14, true));
	}

	@Test
	public void testCompleteHeaderIncludesBossKcWhenKnown()
	{
		assertEquals("Vorkath: 420 kc, complete",
			KillClogChatCommand.buildCompleteHeader("Vorkath", 420));
		assertEquals("Vorkath: complete",
			KillClogChatCommand.buildCompleteHeader("Vorkath", -1));
	}

	@Test
	public void testObtainedItemIconShowsExactDuplicateQuantity()
	{
		assertEquals("<img=42>", KillClogChatCommand.formatItemIcon(42, 1));
		assertEquals("<img=42>x3", KillClogChatCommand.formatItemIcon(42, 3));
		assertEquals("<img=42>x12345", KillClogChatCommand.formatItemIcon(42, 12345));
	}

	@Test
	public void testLogCompatibilityMatchesOnlyWholeCommandsInPlayerChat()
	{
		assertTrue(KillClogChatCommand.isCompatibleLogCommand(
			ChatMessageType.PUBLICCHAT, "!log Vorkath"));
		assertTrue(KillClogChatCommand.isCompatibleLogCommand(
			ChatMessageType.CLAN_CHAT, "!LOG missing Vorkath"));
		assertFalse(KillClogChatCommand.isCompatibleLogCommand(
			ChatMessageType.GAMEMESSAGE, "!log Vorkath"));
		assertFalse(KillClogChatCommand.isCompatibleLogCommand(
			ChatMessageType.PUBLICCHAT, "!logger Vorkath"));
		assertFalse(KillClogChatCommand.isCompatibleLogCommand(
			ChatMessageType.PUBLICCHAT, "hello !log Vorkath"));
	}

	@Test
	public void longClogsHaveNativeWrapPointsWithoutSplittingDuplicateCounts()
	{
		List<Integer> items = new java.util.ArrayList<>();
		Map<Integer, Integer> icons = new HashMap<>();
		Map<Integer, Integer> quantities = new HashMap<>();
		for (int i = 0; i < 134; i++)
		{
			items.add(i);
			icons.put(i, 1000 + i);
			quantities.put(i, i % 2 == 0 ? 1 : 12345);
		}
		String header = "Hard Treasure Trails: 134/134";
		String message = KillClogChatCommand.formatMessage(header, items, quantities, icons);
		assertTrue(message.startsWith(header + " "));
		String[] words = message.substring(header.length() + 1).split(" ");
		assertEquals(items.size(), words.length);
		for (int i = 0; i < words.length; i++)
		{
			assertEquals("<img=" + (1000 + i) + ">" + (i % 2 == 0 ? "" : "x12345"), words[i]);
		}
		assertEquals("Missing: 2/2 <img=10> <img=11>", KillClogChatCommand.formatMessage(
			"Missing: 2/2", Arrays.asList(1, 2), Collections.emptyMap(), Map.of(1, 10, 2, 11)));
		assertEquals(header, KillClogChatCommand.formatMessage(header, items, quantities, Collections.emptyMap()));
		assertEquals(header, KillClogChatCommand.formatMessage(header, Collections.emptyList(), quantities, icons));
	}

	@Test
	public void testLogCompatibilityDelegatesToKillClogCommands()
	{
		assertEquals("!kclog Vorkath", KillClogChatCommand.toKillClogCommand("!log Vorkath"));
		assertEquals("!kclog medium clues",
			KillClogChatCommand.toKillClogCommand("!log medium clues"));
		assertEquals("!missing Vorkath",
			KillClogChatCommand.toKillClogCommand("!log missing Vorkath"));
		assertEquals("!missing medium clues",
			KillClogChatCommand.toKillClogCommand("!log missing medium clues"));
		assertEquals("!missing Vorkath",
			KillClogChatCommand.toKillClogCommand("!LOG MiSsInG   Vorkath"));
		assertNull(KillClogChatCommand.toKillClogCommand("!log"));
		assertNull(KillClogChatCommand.toKillClogCommand("!log missing"));
	}

	@Test
	public void testClueAliasesMatchRuneProfileGrammar()
	{
		assertEquals("beginner_treasure_trails",
			KillClogChatCommand.resolveClueCategory("beginner clues"));
		assertEquals("easy_treasure_trails",
			KillClogChatCommand.resolveClueCategory("clues easy"));
		assertEquals("medium_treasure_trails",
			KillClogChatCommand.resolveClueCategory("medium clues"));
		assertEquals("medium_treasure_trails",
			KillClogChatCommand.resolveClueCategory("clues medium"));
		assertEquals("hard_treasure_trails",
			KillClogChatCommand.resolveClueCategory("hards"));
		assertEquals("elite_treasure_trails",
			KillClogChatCommand.resolveClueCategory("elite treasure trails"));
		assertEquals("master_treasure_trails",
			KillClogChatCommand.resolveClueCategory("master clue"));
		assertNull(KillClogChatCommand.resolveClueCategory("medium"));
	}

	@Test
	public void testTotalsFallBackToCatalogForUnknownCategories()
	{
		// A cache bulk-synced before a page existed has no entry for it, so
		// the command used to answer "no clog items found" for real content.
		// The in-game catalog fills the total; captured entries always win.
		Map<String, List<Integer>> catalog = new HashMap<>();
		catalog.put("maggotking", Arrays.asList(1, 2, 3));

		assertEquals(Arrays.asList(1, 2, 3), KillClogChatCommand.totalsWithCatalogFallback(
			Collections.emptyList(), catalog, "maggotking"));
		assertEquals(Arrays.asList(9), KillClogChatCommand.totalsWithCatalogFallback(
			Arrays.asList(9), catalog, "maggotking"));
		// No parsed catalog or a category it also lacks keeps the empty list,
		// which still renders "no clog items found".
		assertEquals(Collections.emptyList(), KillClogChatCommand.totalsWithCatalogFallback(
			Collections.emptyList(), null, "maggotking"));
		assertEquals(Collections.emptyList(), KillClogChatCommand.totalsWithCatalogFallback(
			Collections.emptyList(), catalog, "vorkath"));
	}

	@Test
	public void testChatCanonMatchesHiscoreBossNames()
	{
		// The alias table carries its own copy of the boss canon. This pins it
		// to the hiscore list in both directions so the duplicate can never
		// drift (2026-07-16 pre-Mad-Angel hardening review).
		Set<String> csvNames = new HashSet<>(Arrays.asList(HiscoreService.bossNames()));
		for (String name : csvNames)
		{
			assertEquals("Hiscore boss missing from chat canon: " + name,
				name, KillClogChatCommand.aliases().get(KillClogChatCommand.normalize(name)));
		}
		for (String canonical : KillClogChatCommand.aliases().values())
		{
			assertTrue("Chat canon points at a boss the hiscores do not know: " + canonical,
				csvNames.contains(canonical));
		}
	}
}

