			ProfileAppearanceService.scopedKey(255L, "deviceSecret"));

		System.setProperty(KillClogEndpoint.ENDPOINT_PROPERTY, KillClogEndpoint.STAGING_API);
		assertEquals("ff.staging.deviceSecret",
			ProfileAppearanceService.scopedKey(255L, "deviceSecret"));
	}
}

