import java.util.Map;
import java.util.concurrent.CompletableFuture;
import org.junit.Test;
import static com.killclog.LookupTestFixture.*;
import static org.junit.Assert.*;

/** The cached-hiscore branch of a lookup goes through the same display hold. */
public class LookupCachedHoldTest
{
	private final Map<String, CompletableFuture<ClogResult>> clogs = new HashMap<>();
	private final Map<String, ClogResult> cachedClogs = new HashMap<>();
	private final List<String> order = new ArrayList<>();

	private LookupSession session()
	{
		HiscoreService hiscores = new HiscoreService(null, null)
		{
			@Override
			public HiscoreResult getCached(String name)
			{
				return hiscore(5);
			}

			@Override
			public boolean isStale(String name)
			{
				return false;
			}
		};
		ClogService clogService = new ClogService(null, null, null)
		{
			@Override
			public ClogResult getCachedResult(String name)
			{
				return cachedClogs.get(name);
			}

			@Override
			public CompletableFuture<ClogResult> lookup(String name)
			{
				return clogs.computeIfAbsent(name, ignored -> new CompletableFuture<>());
			}
		};
		RuneProfileService runeProfile = new RuneProfileService(null, null, null)
		{
			@Override
			public CompletableFuture<CombatAchievementResult> lookup(String name)
			{
				return new CompletableFuture<>();
			}

			@Override
			public CompletableFuture<ClogResult> lookupClog(String name)
			{
				return CompletableFuture.completedFuture(null);
			}
		};
		LookupSession.Listener listener = (LookupSession.Listener) Proxy.newProxyInstance(
			getClass().getClassLoader(), new Class<?>[]{LookupSession.Listener.class},
			(proxy, method, args) ->
			{
				order.add(method.getName());
				return null;
			});
		return new LookupSession(hiscores, clogService, runeProfile, null,
			new KillClogConfig()
			{
			}, listener);
	}

	/** The 600 ms cached reveal is a local one-shot timer; wait it out in real time. */
	private static void awaitCachedReveal() throws Exception
	{
		Thread.sleep(900);
		edt(() ->
		{
		});
	}

	// Cached hiscore + cached clog reveal together, with no hold.
	@Test
	public void cachedHiscoreWithACachedClogIsShownWithoutAHold() throws Exception
	{
		LookupSession session = session();
		cachedClogs.put("Red", clog("Red"));
		edt(() -> session.start("Red", "Blue", AccountType.REGULAR));
		edt(() -> assertTrue("in flight until the cached reveal", session.isLookupInFlight()));
		awaitCachedReveal();
		edt(() ->
		{
			assertEquals(5, session.getHiscoreResult().getTotalLevel());
			assertEquals("Red", session.getClogResult().getPlayerName());
			assertFalse(session.isLookupInFlight());
			assertNull(LookupHoldTest.holdTimer(session));
		});
		assertEquals(Arrays.asList("onLookupStart", "onCachedResult"), order);
	}

	// Cached hiscore with no clog yet is held, never blocks a new search, and shows with its clog.
	@Test
	public void cachedHiscoreWithoutAClogIsHeldUntilTheClogLands() throws Exception
	{
		LookupSession session = session();
		edt(() -> session.start("Red", "Blue", AccountType.REGULAR));
		awaitCachedReveal();
		edt(() ->
		{
			assertNull("held, not shown", session.getHiscoreResult());
			assertFalse("the hold must not block a new search", session.isLookupInFlight());
			assertNotNull(LookupHoldTest.holdTimer(session));
		});
		assertEquals(Arrays.asList("onLookupStart"), order);
		clogs.get("Red").complete(clog("Red"));
		edt(() -> assertEquals(5, session.getHiscoreResult().getTotalLevel()));
		assertEquals(Arrays.asList("onLookupStart", "onCachedResult", "onClogResult"), order);
	}

	// A cancelled cached lookup never reveals when its 600 ms timer fires late.
	@Test
	public void cancelledCachedLookupNeverReveals() throws Exception
	{
		LookupSession session = session();
		cachedClogs.put("Red", clog("Red"));
		edt(() ->
		{
			session.start("Red", "Blue", AccountType.REGULAR);
			session.cancelInFlight();
		});
		awaitCachedReveal();
		edt(() -> assertNull(session.getHiscoreResult()));
		assertEquals(Arrays.asList("onLookupStart"), order);
	}
}

package com.killclog;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

public class LookupFanoutTest
{
	@Test
	public void testGenerationStateMachine()
	{
		LookupFanout fanout = new LookupFanout(null, null, null, null);
		assertFalse(fanout.isInFlight());

		int first = fanout.begin();
		assertTrue(fanout.isInFlight());
		assertTrue(fanout.current(first));

		fanout.settle();
		assertFalse(fanout.isInFlight());
		// Settling resolves the generation without staling its callbacks:
		// clog and CA lanes may still deliver after the hiscore resolves.
		assertTrue(fanout.current(first));

		int second = fanout.begin();
		assertFalse(fanout.current(first));
		assertTrue(fanout.current(second));

		// Cancel abandons an in-flight generation and stales its callbacks.
		fanout.invalidate();
		assertFalse(fanout.isInFlight());
		assertFalse(fanout.current(second));

		// Optional legs can outlive settlement and must also be invalidated.
		int third = fanout.begin();
		fanout.settle();
		fanout.invalidate();
		assertFalse(fanout.current(third));
	}

	@Test
	public void aLeagueReadsLeagueHiscoresYourOwnLogAndKillClogOnly() throws Exception
	{
		HiscoreService hiscores = mock(HiscoreService.class);
		ClogService clogs = mock(ClogService.class);
		RuneProfileService runeProfile = mock(RuneProfileService.class);
		KillclogService killclog = mock(KillclogService.class);
		LocalClogCache own = mock(LocalClogCache.class);
		HiscoreResult row = mock(HiscoreResult.class);
		ClogResult theirs = mock(ClogResult.class);
		ClogResult mine = mock(ClogResult.class);
		when(hiscores.lookupLeague("Friend")).thenReturn(CompletableFuture.completedFuture(row));
		when(killclog.lookupClog("Friend", "demonic-pacts")).thenReturn(CompletableFuture.completedFuture(theirs));
		when(clogs.lookupLocal(own, "Me")).thenReturn(CompletableFuture.completedFuture(mine));
		LookupFanout fanout = new LookupFanout(hiscores, clogs, runeProfile, killclog);
		fanout.readLeague("demonic-pacts", own);
		int stamp = fanout.begin();
		List<Object> shown = new ArrayList<>();
		fanout.fetchHiscore("Friend", null, stamp, shown::add, error -> fail(error.toString()));
		fanout.fetchClog("Friend", false, stamp, shown::add, null);
		fanout.fetchClog("Me", true, stamp, shown::add, null);
		fanout.fetchCa("Friend", stamp, shown::add);
		SwingUtilities.invokeAndWait(() ->
		{
		});
		assertEquals(List.of(row, theirs, mine), shown);
		verify(hiscores, never()).lookup(any(), any());
		verify(clogs, never()).lookup(any());
		verify(killclog, never()).lookupClog("Friend");
		verifyNoInteractions(runeProfile);

		when(hiscores.lookup("Friend", null)).thenReturn(new CompletableFuture<>());
		fanout.readLeague(null, null);
		fanout.fetchHiscore("Friend", null, stamp, shown::add, error -> fail(error.toString()));
		verify(hiscores).lookup("Friend", null);
	}

	@Test
	public void yourOwnLogIsTheViewedGamesAndOnlyYours()
	{
		ClogService clogs = mock(ClogService.class);
		LocalClogCache own = mock(LocalClogCache.class);
		ClogResult main = mock(ClogResult.class);
		ClogResult league = mock(ClogResult.class);
		when(clogs.getCachedResult("Me")).thenReturn(main);
		when(clogs.localResult(own, "Me")).thenReturn(league);
		LookupFanout fanout = new LookupFanout(null, clogs, null, null);
		assertSame(main, fanout.ownLog("Me"));
		fanout.readLeague("demonic-pacts", own);
		assertSame(league, fanout.ownLog("Me"));
		fanout.readLeague("demonic-pacts", null);
		assertNull("a League read from another world has no log of yours here", fanout.ownLog("Me"));

		ClogService real = new ClogService(null, null, null);
		when(own.hasDataFor(any())).thenReturn(true);
		when(own.isActivePlayer("Me")).thenReturn(true);
		ClogResult logged = new ClogResult("Me", java.util.Map.of(), java.util.Map.of(), java.util.Map.of(), null, null);
		when(own.toClogResult(any(), any())).thenReturn(logged);
		assertTrue(real.localResult(own, "Me").isFromLocal());
		assertNull("another player's name never reads your log", real.localResult(own, "Other"));
	}

	@Test
	public void testTransportPolicyPins()
	{
		// The compare side once lost these by re-implementing transport;
		// timeout policy now has exactly one home.
		assertEquals(10, LookupFanout.CA_TIMEOUT_SECONDS);
		assertEquals(15, LookupFanout.HISCORE_TIMEOUT_SECONDS);
	}

	@Test
	public void aLookupJagexNeverAnswersReadsAsTheHiscoresBeingDown() throws Exception
	{
		// Jagex holds the request open past the lookup's own deadline.
		HiscoreService silent = org.mockito.Mockito.mock(HiscoreService.class);
		org.mockito.Mockito.when(silent.lookup("Quiet", null)).thenReturn(new CompletableFuture<>());
		LookupFanout fanout = new LookupFanout(silent, null, null, null);
		java.util.concurrent.CountDownLatch delivered = new java.util.concurrent.CountDownLatch(1);
		java.util.concurrent.atomic.AtomicReference<String> shown = new java.util.concurrent.atomic.AtomicReference<>();
		javax.swing.SwingUtilities.invokeAndWait(() -> fanout.fetchHiscore("Quiet", null, fanout.begin(),
			result -> delivered.countDown(), error ->
			{
				shown.set(HiscoreService.failureText(error));
				delivered.countDown();
			}));
		org.junit.Assert.assertTrue(delivered.await(LookupFanout.HISCORE_TIMEOUT_SECONDS + 3, java.util.concurrent.TimeUnit.SECONDS));
		assertEquals(HiscoreService.DOWN_MESSAGE, shown.get());
	}
}

package com.killclog;

import java.awt.event.ActionListener;
import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import org.junit.Test;
import static com.killclog.LookupTestFixture.*;
import static org.junit.Assert.*;

/** The display hold: a finished hiscore waits briefly for its clog, and only for its own lookup. */
public class LookupHoldTest
{
	// A timer or late callback from lookup N must neither reveal nor clear lookup N+1's hold.
	@Test
	public void staleReleaseFromAnEarlierLookupCannotTouchTheNextHold() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.primary.start("Red", "Blue", AccountType.REGULAR));
		fixture.hiscores.get("Red").complete(hiscore(7));
		List<ActionListener> redRelease = new ArrayList<>();
		edt(() -> redRelease.addAll(Arrays.asList(holdTimer(fixture.primary).getActionListeners())));

		edt(() -> fixture.primary.start("Green", "Blue", AccountType.REGULAR));
		fixture.hiscores.get("Green").complete(hiscore(9));
		edt(() -> assertNotNull("Green should be held", holdTimer(fixture.primary)));

		// Lookup Red's release arrives late (an already-queued timer event, a late callback).
		edt(() -> redRelease.forEach(listener -> listener.actionPerformed(null)));
		assertEquals("a stale release must not reveal the next lookup early",
			0, fixture.events("onHiscoreResult"));

		fixture.clogs.get("Green").complete(clog("Green"));
		edt(() ->
		{
			assertNotNull("Green's held hiscore was destroyed by Red's stale release",
				fixture.primary.getHiscoreResult());
			assertEquals(9, fixture.primary.getHiscoreResult().getTotalLevel());
		});
		assertEquals(1, fixture.events("onHiscoreResult"));
	}

	// The hold re-arms for every lookup, not only the first of the session.
	@Test
	public void everyLookupHoldsAgainAfterAnEarlierOneSettled() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.primary.start("Red", "Blue", AccountType.REGULAR));
		fixture.clogs.get("Red").complete(clog("Red"));
		fixture.hiscores.get("Red").complete(hiscore(7));
		edt(() -> assertEquals(7, fixture.primary.getHiscoreResult().getTotalLevel()));

		edt(() -> fixture.primary.start("Green", "Blue", AccountType.REGULAR));
		fixture.hiscores.get("Green").complete(hiscore(9));
		edt(() -> assertNull("Green must wait for its own clog", fixture.primary.getHiscoreResult()));
		assertEquals(1, fixture.events("onHiscoreResult"));

		fixture.clogs.get("Green").complete(clog("Green"));
		edt(() -> assertEquals(9, fixture.primary.getHiscoreResult().getTotalLevel()));
		assertEquals(2, fixture.events("onHiscoreResult"));
	}

	// A local capture that lands during the hold is a settled clog: show the hiscore first.
	@Test
	public void localCaptureDuringTheHoldReleasesItHiscoreFirst() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.primary.start("Blue", "Blue", AccountType.REGULAR));
		fixture.hiscores.get("Blue").complete(hiscore(7));
		edt(() -> assertNull(fixture.primary.getHiscoreResult()));
		fixture.cachedClogs.put("Blue", clog("Blue").withLocalSource(true));
		edt(() -> fixture.primary.refreshLocalClog("Blue", "Blue"));
		edt(() -> assertEquals(7, fixture.primary.getHiscoreResult().getTotalLevel()));
		assertEquals(Arrays.asList("onLookupStart", "onHiscoreResult", "onClogResult"), fixture.order);
	}

	// The hold really is a one-shot running timer of CLOG_HOLD_MS.
	@Test
	public void holdIsARunningOneShotTimerOfTheDocumentedLength() throws Exception
	{
		LookupTestFixture fixture = new LookupTestFixture();
		edt(() -> fixture.primary.start("Red", "Blue", AccountType.REGULAR));
		fixture.hiscores.get("Red").complete(hiscore(7));
		edt(() ->
		{
			Timer timer = holdTimer(fixture.primary);
			assertNotNull(timer);
			assertTrue("hold timer must be started", timer.isRunning());
			assertFalse("hold timer must fire once", timer.isRepeats());
			assertEquals(LookupSession.CLOG_HOLD_MS, timer.getInitialDelay());
			assertTrue("a slow provider may not hide a finished hiscore for long",
				LookupSession.CLOG_HOLD_MS <= 3000);
			fixture.primary.reset();
		});
	}

	// Cancel, reset and a new search stop the timer and drop the held reveal.
	@Test
	public void cancelResetAndNewSearchStopTheHoldTimer() throws Exception
	{
		for (String how : new String[]{"cancel", "reset", "start"})
		{
			LookupTestFixture fixture = new LookupTestFixture();
			edt(() -> fixture.primary.start("Red", "Blue", AccountType.REGULAR));
			fixture.hiscores.get("Red").complete(hiscore(7));
			Timer[] held = new Timer[1];
			edt(() ->
			{
				held[0] = holdTimer(fixture.primary);
				assertTrue(held[0].isRunning());
				if (how.equals("cancel")) fixture.primary.cancelInFlight();
				else if (how.equals("reset")) fixture.primary.reset();
				else fixture.primary.start("Green", "Blue", AccountType.REGULAR);
				assertFalse(how + " must stop the hold timer", held[0].isRunning());
				assertNull(how + " must drop the timer", holdTimer(fixture.primary));
				assertNull(how + " must drop the held reveal", field(fixture.primary, "heldReveal"));
			});
			assertEquals(0, fixture.events("onHiscoreResult"));
		}
	}

	// A clog lane that FAILS (not merely returns nothing) still releases the held hiscore.
	@Test
	public void failedClogLaneReleasesTheHeldHiscore() throws Exception
	{
		CompletableFuture<HiscoreResult> hiscore = new CompletableFuture<>();
		List<String> order = new ArrayList<>();
		HiscoreService hiscores = new HiscoreService(null, null)
		{
			@Override
			public CompletableFuture<HiscoreResult> lookup(String name, AccountType type)
			{
				return hiscore;
			}
		};
		// Two provider results with no item map: the combine throws, which is
		// the only way the fan-out's own error path is reached.
		ClogResult broken = new ClogResult("Red", null, Map.of(), Map.of(), null, null);
		ClogService clogs = new ClogService(null, null, null)
		{
			@Override
			public ClogResult getCachedResult(String name)
			{
				return null;
			}

			@Override
			public CompletableFuture<ClogResult> lookup(String name)
			{
				return CompletableFuture.completedFuture(broken);
			}
		};
		RuneProfileService runeProfile = new RuneProfileService(null, null, null)
		{
			@Override
			public CompletableFuture<CombatAchievementResult> lookup(String name)
			{
				return new CompletableFuture<>();
			}

			@Override
			public CompletableFuture<ClogResult> lookupClog(String name)
			{
				return CompletableFuture.completedFuture(broken);
			}
		};
		LookupSession.Listener listener = (LookupSession.Listener) Proxy.newProxyInstance(
			getClass().getClassLoader(), new Class<?>[]{LookupSession.Listener.class},
			(proxy, method, args) ->
			{
				order.add(method.getName());
				return null;
			});
		LookupSession session = new LookupSession(hiscores, clogs, runeProfile, null,
			new KillClogConfig()
			{
			}, listener);
		edt(() -> session.start("Red", "Blue", AccountType.REGULAR));
		hiscore.complete(hiscore(7));
		edt(() ->
		{
		});
		edt(() ->
		{
			assertNotNull("a failed clog lane left the hiscore held", session.getHiscoreResult());
			assertNull("the failed lane released the hold, it did not time out", holdTimer(session));
		});
		assertEquals(Arrays.asList("onLookupStart", "onHiscoreResult"), order);
	}

	static Timer holdTimer(LookupSession session)
	{
		return (Timer) field(session, "holdTimer");
	}

	static Object field(LookupSession session, String name)
	{
		try
		{
			Field field = LookupSession.class.getDeclaredField(name);
			field.setAccessible(true);
			return field.get(session);
		}
		catch (ReflectiveOperationException ex)
		{
			throw new AssertionError(ex);
		}
	}

	static void flush() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
		});
	}
}

