			calls.incrementAndGet();
			return response(chain, 503, "{\"accepted\":true,\"error\":\"appearance_render_failed\"}");
		}))
		{
			h.secret();
			ProfileAppearanceService.PublishResult result = h.publish().get(3, TimeUnit.SECONDS);
			assertEquals(ProfileAppearanceService.Outcome.FAILED, result.outcome);
			assertTrue(result.message.contains("render"));
			h.publish().get(3, TimeUnit.SECONDS);
			assertEquals(1, calls.get());
		}
	}

	@Test
	public void retryAfterAcceptsSecondsAndHttpDateButRejectsMalformed()
	{
		assertEquals(120, HttpUtil.retryAfterSeconds("120"));
		String date = java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME.format(
			java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC).plusSeconds(120));
		int delay = HttpUtil.retryAfterSeconds(date);
		assertTrue(delay >= 119 && delay <= 120);
		assertEquals(0, HttpUtil.retryAfterSeconds("<html>"));
		assertEquals(0, HttpUtil.retryAfterSeconds(null));
	}

	@Test
	public void missingRecoveryTokenDoesNotPromiseTimedRetry() throws Exception
	{
		try (Harness h = new Harness(chain -> response(chain, 409,
			"{\"error\":\"appearance_recovery_pending\",\"activates_at\":\"2030-09-20T12:00:00Z\"}")))
		{
			ProfileAppearanceService.PublishResult result = h.publish().get(3, TimeUnit.SECONDS);
			assertEquals(ProfileAppearanceService.Outcome.RECOVERY_PENDING, result.outcome);
			assertTrue(result.message.contains("started elsewhere"));
			assertFalse(result.message.contains("Sep 20"));
		}
	}

	private static void await(CountDownLatch latch) throws java.io.IOException
	{
		try
		{
			if (!latch.await(3, TimeUnit.SECONDS)) throw new java.io.IOException("Test timed out");
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt(); throw new java.io.IOException(e);
		}
	}

	private static Response response(Interceptor.Chain chain, int status, String json)
	{
		return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
			.code(status).message("test").body(ResponseBody.create(MediaType.parse("application/json"), json)).build();
	}

	private static final class Harness implements AutoCloseable
	{
		private final int[] equipment = new int[12];
		private final int[] colors = new int[5];
		private final AtomicInteger idle = new AtomicInteger(808);
		private Player player;
		private volatile String localName = "Test player";
		private final Item[] worn = new Item[14];
		private boolean equipmentReady = true;
		private boolean loading;
		private final AtomicBoolean authorized = new AtomicBoolean(true);
		private final AtomicBoolean loggedIn = new AtomicBoolean(true);
		private final AtomicLong account = new AtomicLong(1);
		private final AtomicInteger transform = new AtomicInteger(-1);
		private final Map<String, String> config = new ConcurrentHashMap<>();
		private final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
		private final OkHttpClient http;
		private final ProfileAppearanceService service;

		private Harness(Interceptor interceptor)
		{
			PlayerComposition composition = proxy(PlayerComposition.class, (name) ->
			{
				switch (name)
				{
					case "getTransformedNpcId": return transform.get();
					case "getGender": return 0;
					case "getEquipmentIds": return equipment;
					case "getColors": return colors;
					default: return null;
				}
			});
			player = proxy(Player.class, name ->
				"getName".equals(name) ? localName : "getPlayerComposition".equals(name) ? composition
					: "getIdlePoseAnimation".equals(name) ? idle.get() : null);
			Client client = proxy(Client.class, name ->
			{
				switch (name)
				{
					case "getItemContainer": return equipmentReady
						? proxy(ItemContainer.class, method -> "getItems".equals(method) ? worn : null) : null;
					case "getLocalPlayer": return player;
					case "getAccountHash": return account.get();
					case "getRevision": return 237;
					case "getGameState": return loading ? GameState.LOADING
						: loggedIn.get() ? GameState.LOGGED_IN : GameState.LOGIN_SCREEN;
					default: return null;
				}
			});
			ClientThread clientThread = new ClientThread()
			{
				@Override
				public void invokeLater(Runnable action)
				{
					action.run();
				}
			};
			http = new OkHttpClient.Builder().addInterceptor(interceptor).build();
			service = new ProfileAppearanceService(client, clientThread, executor, http, new Gson(), config::get,
				(key, value) ->
				{
					if (value == null) config.remove(key); else config.put(key, value);
				});
			service.captureOriginalAppearance(player);
		}

		private String key(String name)
		{
			return ProfileAppearanceService.scopedKey(1, name);
		}
		private void secret()
		{
			config.put(key("deviceSecret"), SECRET);
		}
		private CompletableFuture<ProfileAppearanceService.PublishResult> publish()
		{
			return service.publishCurrent("Test player", 1, authorized::get);
		}

		@Override public void close()
		{
			executor.shutdownNow();
			http.dispatcher().executorService().shutdownNow();
			http.connectionPool().evictAll();
		}
	}

	private static <T> T proxy(Class<T> type, java.util.function.Function<String, Object> value)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
			(instance, method, args) -> value.apply(method.getName())));
	}
}

package com.killclog;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.lang.reflect.Proxy;
import net.runelite.api.ColorTextureOverride;
import net.runelite.api.Item;
import net.runelite.api.PlayerComposition;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ProfileAppearanceManifestTest
{
	private final Gson gson = new Gson();

	@Test
	public void checksEveryVisibleSlotAndAllowsBodyKitsAndInvisibleEquipment()
	{
		for (int slot = 0; slot < 12; slot++)
		{
			if (slot == 6 || slot == 8 || slot == 11) continue;
			int[] equipment = new int[12];
			Item[] worn = new Item[14];
			equipment[slot] = PlayerComposition.ITEM_OFFSET + 4151;
			ProfileAppearanceManifest manifest = ProfileAppearanceManifest.capture(
				composition(equipment, new int[5], null, 0, -1), 237, "2.4.0", -1, 808);
			assertFalse(manifest.matchesEquipment(worn));
			worn[slot] = new Item(4151, 1);
			assertTrue(manifest.matchesEquipment(worn));
			worn[slot] = new Item(22325, 1);
			assertFalse(manifest.matchesEquipment(worn));
		}
		int[] equipment = {0, 0, 0, 0, 256, 0, 257, 258, 259, 260, 261, PlayerComposition.ITEM_OFFSET + 262};
		ProfileAppearanceManifest manifest = ProfileAppearanceManifest.capture(
			composition(equipment, new int[5], null, 0, -1), 237, "2.4.0", -1, 808);
		Item[] worn = new Item[14];
		worn[0] = new Item(-1, 0);
		worn[12] = new Item(6737, 1);
		worn[13] = new Item(892, 100);
		assertTrue(manifest.matchesEquipment(worn));
		assertTrue(manifest.matchesEquipment(new Item[0]));
		assertFalse(manifest.matchesEquipment(null));
		worn[3] = new Item(4151, 1);
		assertFalse(manifest.matchesEquipment(worn));
	}

	@Test
	public void capturesOnlyTheFixedDataRecipe()
	{
		int[] equipment = {512, 513, 514, 515, 516, 517, 518, 519, 520, 521, -1, 0};
		int[] colors = {1, 2, 3, 4, 5};
		ColorTextureOverride[] overrides = new ColorTextureOverride[12];
		overrides[3] = override(new short[]{12, -7}, new short[]{4});

		ProfileAppearanceManifest manifest = ProfileAppearanceManifest.capture(
			composition(equipment, colors, overrides, 0, -1), 233, "2.1.0", 9399, 813);

		assertNotNull(manifest);
		JsonObject json = gson.toJsonTree(manifest).getAsJsonObject();
		assertEquals(10, json.size());
		assertEquals("killclog.appearance.v3", json.get("schema").getAsString());
		assertEquals("233", json.get("game_build").getAsString());
		assertEquals("2.1.0", json.get("client_version").getAsString());
		assertEquals(0, json.get("gender").getAsInt());
		assertEquals(-1, json.get("transformed_npc_id").getAsInt());
		assertEquals(9399, json.get("follower_npc_id").getAsInt());
		assertEquals(813, json.get("idle_pose_animation").getAsInt());
		assertArrayEquals(equipment, ints(json.getAsJsonArray("equipment")));
		assertArrayEquals(colors, ints(json.getAsJsonArray("colors")));
		assertEquals(12, json.getAsJsonArray("overrides").size());
		JsonObject itemOverride = json.getAsJsonArray("overrides").get(3).getAsJsonObject();
		assertArrayEquals(new int[]{12, -7}, ints(itemOverride.getAsJsonArray("colors")));
		assertArrayEquals(new int[]{4}, ints(itemOverride.getAsJsonArray("textures")));
	}

	@Test
	public void originalRecipeSurvivesMutableClientArraysAndFreshFollower()
	{
		int[] equipment = new int[12];
		int[] colors = new int[5];
		short[] recolors = {42};
		short[] textures = {7};
		ColorTextureOverride[] overrides = new ColorTextureOverride[12];
		overrides[3] = override(recolors, textures);
		ProfileAppearanceManifest original = ProfileAppearanceManifest.capture(
			composition(equipment, colors, overrides, 1, -1), 237, "2.4.0", -1, 808);
		equipment[3] = PlayerComposition.ITEM_OFFSET + 22325;
		colors[0] = 4;
		recolors[0] = 99;
		textures[0] = 88;
		overrides[3] = null;
		JsonObject json = gson.toJsonTree(original.withFollower(9399)).getAsJsonObject();
		assertEquals(0, json.getAsJsonArray("equipment").get(3).getAsInt());
		assertEquals(0, json.getAsJsonArray("colors").get(0).getAsInt());
		assertEquals(42, json.getAsJsonArray("overrides").get(3).getAsJsonObject()
			.getAsJsonArray("colors").get(0).getAsInt());
		assertEquals(7, json.getAsJsonArray("overrides").get(3).getAsJsonObject()
			.getAsJsonArray("textures").get(0).getAsInt());
		assertEquals(1, json.get("gender").getAsInt());
		assertEquals(808, json.get("idle_pose_animation").getAsInt());
		assertEquals(9399, json.get("follower_npc_id").getAsInt());
		assertEquals(-1, gson.toJsonTree(original).getAsJsonObject().get("follower_npc_id").getAsInt());
	}

	@Test
	public void treatsNoRuntimeOverridesAsTwelveNullSlots()
	{
		ProfileAppearanceManifest manifest = ProfileAppearanceManifest.capture(
			composition(new int[12], new int[5], null, 1, -1), 233, "2.1.0", -1, 808);

		assertNotNull(manifest);
		JsonArray overrides = gson.toJsonTree(manifest).getAsJsonObject()
			.getAsJsonArray("overrides");
		assertEquals(12, overrides.size());
		for (int i = 0; i < overrides.size(); i++)
		{
			assertTrue(overrides.get(i).isJsonNull());
		}
	}

	@Test
	public void rejectsTransformsAndMalformedCompositionShapes()
	{
		assertNull(ProfileAppearanceManifest.capture(
			composition(new int[12], new int[5], null, 0, 42), 233, "2.1.0", -1, 808));
		assertNull(ProfileAppearanceManifest.capture(
			composition(new int[11], new int[5], null, 0, -1), 233, "2.1.0", -1, 808));
		assertNull(ProfileAppearanceManifest.capture(
			composition(new int[12], new int[5], null, 7, -1), 233, "2.1.0", -1, 808));
		assertNull(ProfileAppearanceManifest.capture(
			composition(new int[12], new int[5], null, 0, -1), 233, "2.1.0", -2, 808));
		assertNull(ProfileAppearanceManifest.capture(
			composition(new int[12], new int[5], null, 0, -1), 233, "2.1.0", -1, -1));
	}

	private static int[] ints(JsonArray values)
	{
		int[] result = new int[values.size()];
		for (int i = 0; i < values.size(); i++)
		{
			result[i] = values.get(i).getAsInt();
		}
		return result;
	}

	private static ColorTextureOverride override(short[] colors, short[] textures)
	{
		return (ColorTextureOverride) Proxy.newProxyInstance(
			ColorTextureOverride.class.getClassLoader(),
			new Class<?>[]{ColorTextureOverride.class},
			(proxy, method, args) -> "getColorToReplaceWith".equals(method.getName())
				? colors : textures);
	}

	private static PlayerComposition composition(int[] equipment, int[] colors,
		ColorTextureOverride[] overrides, int gender, int transformedNpcId)
	{
		return (PlayerComposition) Proxy.newProxyInstance(
			PlayerComposition.class.getClassLoader(),
			new Class<?>[]{PlayerComposition.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getEquipmentIds":
						return equipment;
					case "getColors":
						return colors;
					case "getColorTextureOverrides":
						return overrides;
					case "getGender":
						return gender;
					case "getTransformedNpcId":
						return transformedNpcId;
					case "isFemale":
						return gender == 1;
					default:
						return null;
				}
			});
	}
}

package com.killclog;

import com.google.gson.JsonObject;
import java.lang.reflect.Proxy;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProfileAppearanceServiceTest
{
	@Test
	public void visibleFollowerNpcIdUsesTransformedComposition()
	{
		NPCComposition base = composition(9999, false, null);
		NPCComposition visible = composition(12293, true, new String[]{"Pick-up"});
		NPC follower = npc(9999, base, visible);

		assertEquals(12293, ProfileAppearanceService.visibleFollowerNpcId(follower));
	}

	@Test
	public void visibleFollowerNpcIdRejectsNonPetTransformation()
	{
		NPCComposition base = composition(9999, true, new String[]{"Pick-up"});
		NPCComposition visible = composition(12296, false, new String[]{"Talk-to"});

		assertEquals(-1, ProfileAppearanceService.visibleFollowerNpcId(
			npc(9999, base, visible)));
	}

	@Test
	public void visibleFollowerNpcIdFallsBackToNpcId()
	{
		NPC follower = npc(9399,
			composition(9399, true, new String[]{"Pick-up"}), null);

		assertEquals(9399, ProfileAppearanceService.visibleFollowerNpcId(follower));
		assertEquals(-1, ProfileAppearanceService.visibleFollowerNpcId(null));
		assertEquals(-1, ProfileAppearanceService.visibleFollowerNpcId(npc(12296,
			composition(12296, false, new String[]{"Talk-to"}), null)));
	}

	@Test
	public void incumbentCredentialCancelsPendingRecoveryBeforePublishing()
	{
		JsonObject pending = new JsonObject();
		pending.addProperty("error", "appearance_recovery_pending");

		assertTrue(ProfileAppearanceService.shouldCancelPendingRecovery(409, pending, true));
		assertFalse(ProfileAppearanceService.shouldCancelPendingRecovery(409, pending, false));
		assertFalse(ProfileAppearanceService.shouldCancelPendingRecovery(401, pending, true));
		assertTrue(ProfileAppearanceService.PUBLISH_RETRY_DELAY_MS > 2000L);
	}

	@Test
	public void missingOrUnverifiedProfileRequestsOneSyncPrerequisite()
	{
		JsonObject missing = new JsonObject();
		missing.addProperty("error", "no_bound_account");
		JsonObject unverified = new JsonObject();
		unverified.addProperty("error", "binding_not_verified");

		assertTrue(ProfileAppearanceService.isProfileRequired(409, missing));
		assertTrue(ProfileAppearanceService.isProfileRequired(409, unverified));
		assertFalse(ProfileAppearanceService.isProfileRequired(403, missing));
	}

	@Test
	public void appearanceCredentialsAreStrictLowercaseHex()
	{
		assertTrue(ProfileAppearanceService.validSecret("a".repeat(64)));
		assertFalse(ProfileAppearanceService.validSecret("A".repeat(64)));
		assertFalse(ProfileAppearanceService.validSecret("short"));
	}

	@Test
	public void onlyRenderedAppearanceIsReportedAsPublished()
	{
		JsonObject ready = new JsonObject();
		ready.addProperty("published", true);
		ready.addProperty("render_status", "ready");
		JsonObject pending = ready.deepCopy();
		pending.addProperty("render_status", "pending_renderer");

		assertTrue(ProfileAppearanceService.isRenderedPublishResponse(200, ready));
		assertFalse(ProfileAppearanceService.isRenderedPublishResponse(200, pending));
		assertFalse(ProfileAppearanceService.isRenderedPublishResponse(202, ready));
		assertFalse(ProfileAppearanceService.isRenderedPublishResponse(200, null));
	}

	@Test
	public void acceptedRendererTimeoutIsPendingRatherThanPublished()
	{
		JsonObject pending = new JsonObject();
		pending.addProperty("accepted", true);
		pending.addProperty("published", false);
		pending.addProperty("render_status", "pending_renderer");

		assertTrue(ProfileAppearanceService.isAcceptedPendingPublishResponse(202, pending));
		assertFalse(ProfileAppearanceService.isAcceptedPendingPublishResponse(200, pending));
		pending.addProperty("render_status", "ready");
		assertFalse(ProfileAppearanceService.isAcceptedPendingPublishResponse(202, pending));
	}

	@Test
	public void pendingAndRecoveryAreNotFailures()
	{
		java.util.Map<ProfileAppearanceService.Outcome, String> expected = new java.util.EnumMap<>(ProfileAppearanceService.Outcome.class);
		expected.put(ProfileAppearanceService.Outcome.PUBLISHED, "character updated!");
		expected.put(ProfileAppearanceService.Outcome.RENDERING, "Still rendering...");
		expected.put(ProfileAppearanceService.Outcome.RECOVERY_PENDING, "Publishing on hold");
		expected.put(ProfileAppearanceService.Outcome.DISABLED, "Publishing unavailable");
		expected.put(ProfileAppearanceService.Outcome.BUSY, "Finishing previous request...");
		expected.put(ProfileAppearanceService.Outcome.UNKNOWN, "Check your profile");
		expected.put(ProfileAppearanceService.Outcome.APPEARANCE_PENDING, "Change equipment, then retry");
		expected.put(ProfileAppearanceService.Outcome.CANCELLED, " ");
		expected.put(ProfileAppearanceService.Outcome.FAILED, "Character failed");
		expected.put(ProfileAppearanceService.Outcome.PROFILE_REQUIRED, "Character failed");
		assertEquals(ProfileAppearanceService.Outcome.values().length, expected.size());
		for (ProfileAppearanceService.Outcome outcome : ProfileAppearanceService.Outcome.values())
		{
			assertEquals(expected.get(outcome), PublicationCoordinator.characterPublishTerminalStatus(outcome));
		}
		assertTrue(PanelStatusRow.isCharacterNotice("Still rendering..."));
		assertTrue(PanelStatusRow.isCharacterNotice("Change equipment, then retry"));
		assertFalse(PanelStatusRow.isCharacterNotice("Character failed"));
	}

	private static NPC npc(int id, NPCComposition base, NPCComposition transformed)
	{
		return (NPC) Proxy.newProxyInstance(NPC.class.getClassLoader(), new Class<?>[]{NPC.class},
			(instance, method, args) ->
			{
				if (method.getName().equals("getId"))
				{
					return id;
				}
				if (method.getName().equals("getTransformedComposition"))
				{
					return transformed;
				}
				if (method.getName().equals("getComposition"))
				{
					return base;
				}
				return defaultValue(method.getReturnType());
			});
	}

	private static NPCComposition composition(int id, boolean follower, String[] actions)
	{
		return (NPCComposition) Proxy.newProxyInstance(NPCComposition.class.getClassLoader(),
			new Class<?>[]{NPCComposition.class}, (instance, method, args) ->
			{
				if (method.getName().equals("getId"))
				{
					return id;
				}
				if (method.getName().equals("isFollower"))
				{
					return follower;
				}
				if (method.getName().equals("getActions"))
				{
					return actions;
				}
				return defaultValue(method.getReturnType());
			});
	}

	private static Object defaultValue(Class<?> returnType)
	{
		if (returnType.equals(boolean.class))
		{
			return false;
		}
		if (returnType.equals(int.class))
		{
			return 0;
		}
		return null;
	}
}

package com.killclog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
