	@Test
	public void raidRowsAreHitTestedOnlyWhereTheyWerePainted()
	{
		PvmSummaryTooltip tip = card();
		// Before the first paint there is no raid section to answer.
		assertEquals(-1, tip.raidAt(200));

		painted(tip);
		assertEquals(-1, tip.raidAt(0));
		int top = firstRaidY(tip);
		assertEquals(-1, tip.raidAt(top - 1));
		for (int row = 0; row < 3; row++)
		{
			assertEquals(row, tip.raidAt(top + row * NativeTooltip.LINE_HEIGHT));
			assertEquals(row, tip.raidAt(top + row * NativeTooltip.LINE_HEIGHT + NativeTooltip.LINE_HEIGHT - 1));
		}
		// The mega rare sprites below the rows are not part of them.
		assertEquals(-1, tip.raidAt(top + 3 * NativeTooltip.LINE_HEIGHT));
	}

	@Test
	public void aHoveredRaidTurnsItsOwnLabelWhiteAndNothingElse()
	{
		PvmSummaryTooltip tip = painted(card());
		BufferedImage resting = render(tip);
		int top = firstRaidY(tip);
		int orange = NativeTooltip.OSRS_ORANGE.getRGB();
		int white = Color.WHITE.getRGB();
		for (int row = 0; row < 3; row++)
		{
			move(tip, 5, top + row * NativeTooltip.LINE_HEIGHT + 2);
			assertEquals(row, tip.hoveredRaid());
			BufferedImage hovered = render(tip);
			int changed = 0;
			for (int y = 0; y < resting.getHeight(); y++)
			{
				for (int x = 0; x < resting.getWidth(); x++)
				{
					if (resting.getRGB(x, y) != hovered.getRGB(x, y))
					{
						// Only this row's label moves, and only from orange to white.
						assertEquals(row, tip.raidAt(y));
						assertEquals(orange, resting.getRGB(x, y));
						assertEquals(white, hovered.getRGB(x, y));
						changed++;
					}
				}
			}
			assertTrue(changed > 0);
		}

		move(tip, 5, 2);
		assertEquals(-1, tip.hoveredRaid());
		BufferedImage after = render(tip);
		for (int y = 0; y < resting.getHeight(); y++)
		{
			for (int x = 0; x < resting.getWidth(); x++)
			{
				assertEquals(resting.getRGB(x, y), after.getRGB(x, y));
			}
		}
	}

	@Test
	public void pressingARaidRowOpensThatRaidAndNothingElseDoes()
	{
		PvmSummaryTooltip tip = card();
		List<HiscoreSkill> opened = new ArrayList<>();
		tip.setOnOpenRaid((press, raid) -> opened.add(raid));

		// Before the first paint there is no raid section to press.
		press(tip, 5, 200, MouseEvent.BUTTON1);
		assertTrue(opened.isEmpty());

		painted(tip);
		int top = firstRaidY(tip);
		for (int row = 0; row < 3; row++)
		{
			// The press that opens a raid is spent on it.
			assertTrue(press(tip, 5, top + row * NativeTooltip.LINE_HEIGHT + 3, MouseEvent.BUTTON1).isConsumed());
		}
		assertEquals(List.of(HiscoreSkill.CHAMBERS_OF_XERIC, HiscoreSkill.THEATRE_OF_BLOOD,
			HiscoreSkill.TOMBS_OF_AMASCUT), opened);

		// The Slayer rows above, the sprites below and a right click are not links, and pass through.
		assertFalse(press(tip, 5, top - 40, MouseEvent.BUTTON1).isConsumed());
		assertFalse(press(tip, 5, top + 3 * NativeTooltip.LINE_HEIGHT + 3, MouseEvent.BUTTON1).isConsumed());
		assertFalse(press(tip, 5, top + 3, MouseEvent.BUTTON3).isConsumed());
		assertEquals(3, opened.size());
	}

	@Test
	public void hoverRepaintsOnlyWhenTheRaidRowChanges()
	{
		int[] repaints = {0};
		PvmSummaryTooltip tip = new PvmSummaryTooltip()
		{
			@Override
			public void repaint(long tm, int x, int y, int width, int height)
			{
				repaints[0]++;
			}
		};
		fill(tip);
		painted(tip);
		int top = firstRaidY(tip);
		repaints[0] = 0;
		move(tip, 5, top + 2);
		assertEquals(1, repaints[0]);
		move(tip, 9, top + 4);
		assertEquals(1, repaints[0]);
		move(tip, 5, top + NativeTooltip.LINE_HEIGHT + 2);
		assertEquals(2, repaints[0]);
		move(tip, 5, 2);
		assertEquals(3, repaints[0]);
		move(tip, 5, 4);
		assertEquals(3, repaints[0]);
	}

	@Test
	public void theHoveredRaidRowIsClearedOnExit()
	{
		PvmSummaryTooltip tip = painted(card());
		int top = firstRaidY(tip);
		move(tip, 5, top + 2);
		assertEquals(0, tip.hoveredRaid());
		for (MouseListener listener : tip.getMouseListeners())
		{
			listener.mouseExited(event(tip, MouseEvent.MOUSE_EXITED, 5, top + 2, MouseEvent.NOBUTTON));
		}
		assertEquals(-1, tip.hoveredRaid());
	}

	private static PvmSummaryTooltip card()
	{
		return fill(new PvmSummaryTooltip());
	}

	private static PvmSummaryTooltip fill(PvmSummaryTooltip tip)
	{
		tip.setData(110.5, 2_500, 40, PanelData.bossCount(), "Vorkath", 900);
		Map<String, Integer> kills = new HashMap<>();
		kills.put(HiscoreSkill.CHAMBERS_OF_XERIC.getName(), 120);
		kills.put(HiscoreSkill.THEATRE_OF_BLOOD.getName(), 80);
		kills.put(HiscoreSkill.TOMBS_OF_AMASCUT.getName(), 300);
		tip.setRaids(new HiscoreResult(AccountType.REGULAR, kills, Collections.emptyMap(),
			Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap(), 0, 0, 0, -1), null);
		return tip;
	}

	private static PvmSummaryTooltip painted(PvmSummaryTooltip tip)
	{
		tip.setSize(tip.getPreferredSize());
		render(tip);
		return tip;
	}

	private static BufferedImage render(PvmSummaryTooltip tip)
	{
		Dimension size = tip.getSize();
		BufferedImage image = new BufferedImage(size.width, size.height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		tip.paint(graphics);
		graphics.dispose();
		return image;
	}

	/** The first y that answers as raid row 0, found the way a pointer would. */
	private static int firstRaidY(PvmSummaryTooltip tip)
	{
		for (int y = 0; y < tip.getHeight(); y++)
		{
			if (tip.raidAt(y) == 0)
			{
				return y;
			}
		}
		throw new AssertionError("no raid section painted");
	}

	/** One press through every listener, the way Swing delivers it; returns it to read consumption. */
	private static MouseEvent press(PvmSummaryTooltip tip, int x, int y, int button)
	{
		MouseEvent press = event(tip, MouseEvent.MOUSE_PRESSED, x, y, button);
		for (MouseListener listener : tip.getMouseListeners())
		{
			listener.mousePressed(press);
		}
		return press;
	}

	private static void move(PvmSummaryTooltip tip, int x, int y)
	{
		for (MouseMotionListener listener : tip.getMouseMotionListeners())
		{
			listener.mouseMoved(event(tip, MouseEvent.MOUSE_MOVED, x, y, MouseEvent.NOBUTTON));
		}
	}

	private static MouseEvent event(PvmSummaryTooltip tip, int id, int x, int y, int button)
	{
		return new MouseEvent(tip, id, System.currentTimeMillis(), 0, x, y, 1, false, button);
	}

	private static HiscoreResult hiscoreWithGlory(int glory)
	{
		Map<String, Integer> scores = new HashMap<>();
		scores.put(ColosseumGlory.ACTIVITY_NAME, glory);
		return new HiscoreResult(AccountType.REGULAR,
			Collections.emptyMap(), Collections.emptyMap(), scores, Collections.emptyMap(),
			Collections.emptyMap(), 0, 0, 0, -1);
	}

}

package com.killclog;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The game stops counting most log items at 250 and a few stackables at 65,535; a count at its cap reads green. */
public class QuantityCapTest
{
	private static final int ZULRAHS_SCALES = 12934;
	private static final int BRACELET_OF_ETHEREUM = 21817;

	@Test
	public void eachItemReadsGreenAtItsOwnCap()
	{
		assertTrue(TooltipItemSprites.atCap(BRACELET_OF_ETHEREUM, 250));
		assertFalse(TooltipItemSprites.atCap(BRACELET_OF_ETHEREUM, 249));
		// Scales count on past 250, so 250 of them is just a stack.
		assertFalse(TooltipItemSprites.atCap(ZULRAHS_SCALES, 250));
		assertTrue(TooltipItemSprites.atCap(ZULRAHS_SCALES, 65535));
		assertEquals(53, PanelData.COUNTS_PAST_250_ITEMS.length);
	}

	@Test
	public void theGridPaintsACappedCountGreenAndAnyOtherYellow()
	{
		assertEquals(TitleTooltip.CLOG_GREEN.getRGB(), quantityColor(BRACELET_OF_ETHEREUM, 250));
		assertEquals(TitleTooltip.CLOG_YELLOW.getRGB(), quantityColor(BRACELET_OF_ETHEREUM, 249));
		assertEquals(TitleTooltip.CLOG_YELLOW.getRGB(), quantityColor(ZULRAHS_SCALES, 250));
	}

	/** The brightest pixel the count paints in its corner: its digits in the count's color over their black shadow. */
	private static int quantityColor(int itemId, int count)
	{
		BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
		TooltipItemSprites.paintGrid(g, null, null, 0, List.of(itemId), Set.of(itemId), Map.of(itemId, count),
			0, 0, 1, 32, 36);
		g.dispose();
		for (int y = 0; y < 40; y++)
		{
			for (int x = 0; x < 40; x++)
			{
				int rgb = image.getRGB(x, y);
				if (rgb == TitleTooltip.CLOG_GREEN.getRGB() || rgb == TitleTooltip.CLOG_YELLOW.getRGB())
				{
					return rgb;
				}
			}
		}
		return 0;
	}
}

package com.killclog;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.Interceptor;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Test;
import static org.junit.Assert.*;

public class RankLookupTest
{
	private static String body(int rank)
	{
		return "{\"skills\":[{\"name\":\"Overall\",\"rank\":" + rank
			+ ",\"level\":2000,\"xp\":10000},{\"name\":\"Defence\",\"rank\":12,\"level\":99,\"xp\":1000}],\"activities\":[]}";
	}

	private static Response response(Interceptor.Chain chain, int code, String body)
	{
		return new Response.Builder().request(chain.request()).protocol(Protocol.HTTP_1_1)
			.code(code).message("fixture").body(ResponseBody.create(MediaType.parse("application/json"), body)).build();
	}

	@Test
	public void knownTypeRetainsNeededTablesAndOtherRankSelectionsFetchLazily() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		OkHttpClient client = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			calls.incrementAndGet();
			String path = chain.request().url().encodedPath();
			int rank = path.contains("ultimate") ? 1 : path.contains("hardcore") ? 2 : path.contains("ironman") ? 3 : 4;
			return response(chain, 200, body(rank));
		}).build();
		HiscoreService service = new HiscoreService(client, new Gson());
		HiscoreResult original = service.lookup("Test Player", AccountType.IRONMAN).get(3, TimeUnit.SECONDS);
		assertEquals(AccountType.IRONMAN, original.getAccountType());
		assertEquals(3, original.getOverallRank());
		assertEquals(2, calls.get());
		assertEquals(4, service.lookupRanks("test player", RankLeaderboard.NORMAL).get().getOverallRank());
		assertEquals(3, service.lookupRanks("TEST PLAYER", RankLeaderboard.IRONMAN).get().getOverallRank());
		assertEquals(2, service.lookupRanks("Test Player", RankLeaderboard.HARDCORE).get().getOverallRank());
		assertEquals(1, service.lookupRanks("Test Player", RankLeaderboard.ULTIMATE).get().getOverallRank());
		assertEquals(4, calls.get());
		assertSame(original, service.getCached("Test Player"));
		assertEquals(3, original.getOverallRank());
	}

	@Test
	public void simultaneousRankSelectionsShareOneRequest() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		OkHttpClient client = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			calls.incrementAndGet();
			entered.countDown();
			try
			{
				if (!release.await(3, TimeUnit.SECONDS)) throw new IOException("fixture timed out");
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
				throw new IOException(e);
			}
			assertTrue(chain.request().url().encodedPath().contains("hiscore_oldschool_skiller_defence/"));
			return response(chain, 200, body(50));
		}).build();
		HiscoreService service = new HiscoreService(client, new Gson());
		CompletableFuture<HiscoreResult> first = service.lookupRanks("Test Player", RankLeaderboard.PURE);
		CompletableFuture<HiscoreResult> second;
		try
		{
			assertTrue(entered.await(3, TimeUnit.SECONDS));
			second = service.lookupRanks("TEST PLAYER", RankLeaderboard.PURE);
			assertNotSame(first, second);
			first.complete(null);
		}
		finally
		{
			release.countDown();
		}
		assertNull(first.get());
		assertEquals(50, second.get(3, TimeUnit.SECONDS).getOverallRank());
		assertEquals(50, service.lookupRanks("Test Player", RankLeaderboard.PURE).get().getOverallRank());
		assertEquals(1, calls.get());
		assertNull(service.getCached("Test Player"));
	}

	@Test
	public void failedAndMalformedResponsesNeverBecomeRankData() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		OkHttpClient client = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			int call = calls.incrementAndGet();
			return response(chain, call == 1 ? 404 : 200, call == 2 ? "{broken" : body(99));
		}).build();
		HiscoreService service = new HiscoreService(client, new Gson());
		assertNull(service.lookupRanks("Test", RankLeaderboard.SKILLER).get(3, TimeUnit.SECONDS));
		assertEquals(1, calls.get());
		assertTrue(service.notOnBoard("TEST", RankLeaderboard.SKILLER));
		assertNull("not found is remembered, not asked again",
			service.lookupRanks("Test", RankLeaderboard.SKILLER).get(3, TimeUnit.SECONDS));
		assertEquals(1, calls.get());
		assertEquals(99, service.lookupRanks("Test", RankLeaderboard.PURE).get(3, TimeUnit.SECONDS).getOverallRank());
		assertEquals(3, calls.get());
		assertFalse(service.notOnBoard("Test", RankLeaderboard.PURE));
	}

	@Test
	public void theLookupsOwnFanOutTellsWhichBoardsHaveARow() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		OkHttpClient client = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			calls.incrementAndGet();
			boolean ultimate = chain.request().url().encodedPath().contains("ultimate");
			return response(chain, ultimate ? 404 : 200, ultimate ? "" : body(7));
		}).build();
		HiscoreService service = new HiscoreService(client, new Gson());
		assertNotNull(service.lookup("Ye Ol Buck", null).get(3, TimeUnit.SECONDS));
		int asked = calls.get();
		assertTrue(service.notOnBoard("ye ol buck", RankLeaderboard.ULTIMATE));
		assertFalse(service.notOnBoard("Ye Ol Buck", RankLeaderboard.HARDCORE));
		assertNull(service.lookupRanks("Ye Ol Buck", RankLeaderboard.ULTIMATE).get(3, TimeUnit.SECONDS));
		assertEquals(7, service.lookupRanks("Ye Ol Buck", RankLeaderboard.HARDCORE).get(3, TimeUnit.SECONDS).getOverallRank());
		assertEquals("both answers came from the lookup itself", asked, calls.get());
	}

	@Test
	public void anOutageIsNeverReadAsNotOnTheBoard() throws Exception
	{
		AtomicInteger calls = new AtomicInteger();
		OkHttpClient client = new OkHttpClient.Builder().addInterceptor(chain ->
		{
			calls.incrementAndGet();
			return response(chain, 503, "");
		}).build();
		HiscoreService service = new HiscoreService(client, new Gson());
		assertNull(service.lookupRanks("Test", RankLeaderboard.ULTIMATE).get(5, TimeUnit.SECONDS));
		assertFalse(service.notOnBoard("Test", RankLeaderboard.ULTIMATE));
		int asked = calls.get();
		assertNull(service.lookupRanks("Test", RankLeaderboard.ULTIMATE).get(5, TimeUnit.SECONDS));
		assertTrue("an outage is asked again", calls.get() > asked);
	}
}

