		// Only items with quantity > 0 appear in obtainedItems.
		Map<String, List<ClogResult.ClogItem>> obtained = r.getObtainedItems();
		assertTrue(obtained.containsKey("zulrah"));
		assertEquals(2, obtained.get("zulrah").size());
