	/** The old per-map names, now each lane's own maps ("summaryFetchTimes" is the summary lane's fetched). */
	@SuppressWarnings("unchecked")
	private <T> Map<String, T> cache(String fieldName) throws Exception
	{
		Field field = RuneProfileService.class.getDeclaredField(fieldName.startsWith("summary") ? "summaries" : "clogs");
		field.setAccessible(true);
		HttpUtil.Lane<?> lane = (HttpUtil.Lane<?>) field.get(service);
		switch (fieldName.replaceFirst("^(summary|clog)", ""))
		{
			case "Cache":
				return (Map<String, T>) lane.values;
			case "FetchTimes":
				return (Map<String, T>) (Map<?, ?>) lane.fetched;
			case "NotFoundTimes":
				return (Map<String, T>) (Map<?, ?>) lane.notFound;
			case "Failures":
				return (Map<String, T>) (Map<?, ?>) lane.failed;
			default:
				throw new AssertionError(fieldName);
		}
	}

	private Map<String, RuneProfileService.RuneProfileSummary> summaryCache() throws Exception
	{
		return cache("summaryCache");
	}

	private Map<String, ClogResult> clogCache() throws Exception
	{
		return cache("clogCache");
	}

	private Map<String, Long> longCache(String fieldName) throws Exception
	{
		return cache(fieldName);
	}

	private CircuitBreaker breaker() throws Exception
	{
		Field field = RuneProfileService.class.getDeclaredField("breaker");
		field.setAccessible(true);
		return (CircuitBreaker) field.get(service);
	}

	private long[] recentFailures() throws Exception
	{
		Field field = CircuitBreaker.class.getDeclaredField("recentFailures");
		field.setAccessible(true);
		return (long[]) field.get(breaker());
	}

	private boolean hasRecentFailure() throws Exception
	{
		for (long failure : recentFailures())
		{
			if (failure != 0L)
			{
				return true;
			}
		}
		return false;
	}

	private void recordBreakerFailure() throws Exception
	{
		breaker().failure();
	}
}

