	@Test
	public void totalXpAndOverallRankFillIdleRowsInBothSummaryModes()
	{
		HiscoreResult blue = hiscores(24_000_000L, 12_345);
		HiscoreResult red = hiscores(4_800_000_000L, 42);

		SkillsTooltip solo = new SkillsTooltip();
		solo.setData(blue);
